  "On the Land Buying page, answering a few questions (agricultural land, planning to build, inherited land, etc.) automatically adds the right conditional steps — including NA conversion — to your personalised procedure.",
  "Once verification is clean, both parties sign a sale agreement, stamp duty and the registration fee are paid (use the Charges page to estimate this for your state and property value), and both parties plus two witnesses appear in person at the Sub-Registrar office for registration. Carry originals and photocopies of everything.",
  "Once you've found a property, get its survey/plot number and the seller's name before anything else. Cross-check that name against the state's land record portal (Land Buying page's Official Portals panel has the direct link for your state) — the name on the record is the only name that legally matters, not who's showing you the property.",
