  "Registration is what transfers legal title. An unregistered sale deed does not give you ownership, whatever the seller says.",
  "Registration makes you the legal owner. It does not, by itself, update the revenue department's land record — that's a separate step called mutation, and it can take 15–30 days. Skipping it is the single most common reason a buyer's name never shows up when they check the land record a year later.",
  "Registration transfers title; mutation updates the government's revenue record. Until mutation is done, tax bills and future sales stay in the seller's name.",
