    "See required documents": "కావాల్సిన పత్రాలు చూడండి",
    "Select": "ఎంచుకోండి",
    "Select a district to see the government offices you will need to visit.": "మీరు వెళ్లాల్సిన ప్రభుత్వ కార్యాలయాలు చూడాలంటే ఒక జిల్లాను ఎంచుకోండి.",
    "Select a state and district above to see the contacts listed for that area.": "ఆ ప్రాంతానికి సంబంధించిన సంప్రదింపు వివరాలు చూడాలంటే పైన రాష్ట్రం, జిల్లా ఎంచుకోండి.",
    "Select a subject": "విషయాన్ని ఎంచుకోండి",
