    "Send message": "సందేశం పంపండి",
    "Send us a message": "మాకు సందేశం పంపండి",
    "Seven quick questions. Inherited land, joint owners, urban plots and company buyers each add their own steps.": "ఏడు చిన్న ప్రశ్నలు. వారసత్వ భూమి, ఉమ్మడి యజమానులు, పట్టణ ప్లాట్లు, కంపెనీ కొనుగోలుదారులు — వీటిలో ఒక్కోదానికి అదనపు దశలు ఉంటాయి.",
    "Several states charge less stamp duty when the buyer is a woman.": "కొనుగోలుదారు మహిళ అయితే చాలా రాష్ట్రాల్లో స్టాంప్ డ్యూటీ తక్కువగా ఉంటుంది.",
    "Show all": "అన్నీ చూపించు",
    "Show rules for": "దీని నిబంధనలు చూపించు",
    "Sign in to manage your account": "మీ ఖాతాను నిర్వహించడానికి సైన్ ఇన్ చేయండి",
    "Sign in to see your dashboard": "మీ డాష్‌బోర్డ్ చూడటానికి సైన్ ఇన్ చేయండి",
    "Smart Procedure": "స్మార్ట్ ప్రొసీజర్",
    "Smart Procedure Generator": "స్మార్ట్ ప్రొసీజర్ జనరేటర్",
    "Stamp duty by state": "రాష్ట్రాల వారీగా స్టాంప్ డ్యూటీ",
    "Start a new verification": "కొత్త ధృవీకరణ మొదలుపెట్టండి",
    "Survey / Plot / Gat number": "సర్వే / ప్లాట్ / గట్ నంబర్",
