    "Tell us what you need help with…": "మీకు ఏ విషయంలో సాయం కావాలో చెప్పండి…",
    "The percentage shows how much of the site is translated. Untranslated text falls back to English.": "సైట్‌లో ఎంత భాగం అనువాదం అయిందో ఈ శాతం చూపిస్తుంది. అనువాదం కాని భాగం ఇంగ్లిష్‌లోనే కనిపిస్తుంది.",
    "These contacts were compiled by the project owner for this academic project, not published by any government department. Details can go out of date — please confirm before relying on them.": "ఈ సంప్రదింపు వివరాలను ఈ అకడమిక్ ప్రాజెక్ట్ కోసం ప్రాజెక్ట్ యజమాని సేకరించారు; వీటిని ఏ ప్రభుత్వ శాఖా ప్రచురించలేదు. వివరాలు పాతవి అయిపోయే అవకాశం ఉంది — వాటిపై ఆధారపడే ముందు ఒకసారి నిర్ధారించుకోండి.",
    "This is an academic prototype built as a final-year project. Contact details are placeholders and messages are not actually delivered anywhere.": "ఇది ఫైనల్ ఇయర్ ప్రాజెక్ట్‌గా తయారుచేసిన అకడమిక్ ప్రోటోటైప్. ఇందులోని సంప్రదింపు వివరాలు నమూనా మాత్రమే, సందేశాలు నిజంగా ఎక్కడికీ చేరవు.",
    "This removes your profile, saved documents and verification history. It cannot be undone. In this prototype it simply signs you out and clears the session.": "ఇది మీ ప్రొఫైల్, సేవ్ చేసిన పత్రాలు, ధృవీకరణ చరిత్రను తొలగిస్తుంది. దీన్ని తిరిగి పొందలేరు. ఈ ప్రోటోటైప్‌లో మాత్రం ఇది మిమ్మల్ని సైన్ అవుట్ చేసి సెషన్‌ను క్లియర్ చేస్తుంది అంతే.",
    "This taluka": "ఈ మండలం",
    "Tick a document once you physically have it. The count follows you across the site.": "పత్రం మీ చేతికి వచ్చాక దాన్ని టిక్ చేయండి. ఆ లెక్క సైట్ అంతటా మీతోనే ఉంటుంది.",
    "Tick documents on the Documents page as you collect them.": "పత్రాలు సేకరిస్తున్న కొద్దీ డాక్యుమెంట్స్ పేజీలో వాటిని టిక్ చేయండి.",
    "Time:": "సమయం:",
    "Total estimated amount": "అంచనా వేసిన మొత్తం",
    "Try a shorter word, or clear the mandatory filter.": "కొంచెం చిన్న పదంతో ప్రయత్నించండి, లేదా 'తప్పనిసరివి' ఫిల్టర్ తీసేయండి.",
    "Try another tab or a shorter search word.": "వేరే ట్యాబ్ చూడండి లేదా చిన్న పదంతో వెతకండి.",
    "Try document readiness check": "పత్రాల సంసిద్ధత తనిఖీని ప్రయత్నించండి",
    "Two buyers in the same district can need different steps. Inherited land needs heir consent. A shop on farmland needs conversion. A company buyer needs a board resolution. The Smart Procedure Generator asks five questions and rewrites the checklist around your answers.": "ఒకే జిల్లాలో ఇద్దరు కొనుగోలుదారులకు వేర్వేరు దశలు అవసరం కావచ్చు. వారసత్వంగా వచ్చిన భూమికి వారసుల సమ్మతి కావాలి. వ్యవసాయ భూమిలో దుకాణం పెట్టాలంటే భూమి మార్పిడి (కన్వర్షన్) కావాలి. కంపెనీ కొనుగోలు చేస్తుంటే బోర్డు తీర్మానం కావాలి. స్మార్ట్ ప్రొసీజర్ జనరేటర్ ఐదు ప్రశ్నలు అడిగి, మీ సమాధానాల ప్రకారం చెక్‌లిస్ట్‌ను తిరిగి తయారు చేస్తుంది.",
    "Type your question here…": "మీ ప్రశ్నను ఇక్కడ టైప్ చేయండి…",
    "Updates on land laws and processes.": "భూ చట్టాలు, విధానాల్లో వచ్చే మార్పుల సమాచారం.",
    "Used across the site and in AI answers": "సైట్ అంతటా, AI సమాధానాల్లోనూ ఇది వాడతారు",
    "Verification progress": "ధృవీకరణ పురోగతి",
    "What each document is, why it is needed, where to get it and roughly what it costs.": "ప్రతి పత్రం ఏమిటి, అది ఎందుకు కావాలి, ఎక్కడ దొరుకుతుంది, సుమారు ఎంత ఖర్చవుతుంది.",
    "What makes this different": "ఇది ఎందుకు ప్రత్యేకం",
