    "Where you are in the land buying process right now.": "భూమి కొనుగోలు ప్రక్రియలో మీరు ప్రస్తుతం ఏ దశలో ఉన్నారు.",
    "Whole district": "జిల్లా మొత్తం",
    "Why this step matters": "ఈ దశ ఎందుకు ముఖ్యం",
    "Your account, progress and uploaded documents are saved to the backend database.": "మీ ఖాతా, పురోగతి, అప్‌లోడ్ చేసిన పత్రాలు బ్యాక్‌ఎండ్ డేటాబేస్‌లో సేవ్ అవుతాయి.",
    "Your document checklist": "మీ పత్రాల చెక్‌లిస్ట్",
    "Your estimate appears here": "మీ అంచనా ఇక్కడ కనిపిస్తుంది",
    "Your full name": "మీ పూర్తి పేరు",
    "Your intelligent companion for safe, secure and informed land decisions.": "సురక్షితమైన, సరైన అవగాహనతో కూడిన భూమి నిర్ణయాలకు మీ తెలివైన తోడు.",
    "Your name": "మీ పేరు",
    "Your progress": "మీ పురోగతి",
