    "Activity history": "ಚಟುವಟಿಕೆ ಇತಿಹಾಸ",
    "Add your documents. The checker identifies each one, flags anything expired or unreadable, and lists what is still missing.": "ನಿಮ್ಮ ದಾಖಲೆಗಳನ್ನು ಸೇರಿಸಿ. ಪರಿಶೀಲಕವು ಪ್ರತಿಯೊಂದನ್ನೂ ಗುರುತಿಸುತ್ತದೆ, ಅವಧಿ ಮುಗಿದ ಅಥವಾ ಓದಲಾಗದ ದಾಖಲೆಗಳನ್ನು ಸೂಚಿಸುತ್ತದೆ, ಮತ್ತು ಇನ್ನೂ ಯಾವುವು ಬಾಕಿ ಇವೆ ಎಂದು ಪಟ್ಟಿ ಮಾಡುತ್ತದೆ.",
    "Agricultural": "ಕೃಷಿ",
    "All checks completed": "ಎಲ್ಲಾ ಪರಿಶೀಲನೆಗಳು ಪೂರ್ಣಗೊಂಡಿವೆ",
    "All states (general list)": "ಎಲ್ಲಾ ರಾಜ್ಯಗಳು (ಸಾಮಾನ್ಯ ಪಟ್ಟಿ)",
    "An indicative estimate of stamp duty, registration fee and the smaller charges around them.": "ಮುದ್ರಾಂಕ ಶುಲ್ಕ, ನೋಂದಣಿ ಶುಲ್ಕ ಮತ್ತು ಅವುಗಳ ಜೊತೆಗಿನ ಸಣ್ಣಪುಟ್ಟ ಶುಲ್ಕಗಳ ಒಂದು ಅಂದಾಜು ಲೆಕ್ಕಾಚಾರ.",
    "Answering for": "ಇದಕ್ಕಾಗಿ ಉತ್ತರ",
    "Answers are for general guidance in an academic prototype. Confirm anything that affects your money with a lawyer or the concerned government office.": "ಉತ್ತರಗಳು ಈ ಶೈಕ್ಷಣಿಕ ಮಾದರಿಯಲ್ಲಿ ಸಾಮಾನ್ಯ ಮಾರ್ಗದರ್ಶನಕ್ಕಾಗಿ ಮಾತ್ರ. ನಿಮ್ಮ ಹಣಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಯಾವುದೇ ವಿಷಯವನ್ನು ವಕೀಲರ ಬಳಿ ಅಥವಾ ಸಂಬಂಧಪಟ್ಟ ಸರ್ಕಾರಿ ಕಚೇರಿಯಲ್ಲಿ ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
    "Ask AI": "AI ಅನ್ನು ಕೇಳಿ",
    "Ask about this step": "ಈ ಹಂತದ ಬಗ್ಗೆ ಕೇಳಿ",
    "Ask in plain language. Answers use your selected district and your Smart Procedure answers.": "ಸರಳ ಭಾಷೆಯಲ್ಲಿ ಕೇಳಿ. ನೀವು ಆಯ್ಕೆ ಮಾಡಿದ ಜಿಲ್ಲೆ ಮತ್ತು ನಿಮ್ಮ ಸ್ಮಾರ್ಟ್ ಕಾರ್ಯವಿಧಾನದ ಉತ್ತರಗಳ ಆಧಾರದ ಮೇಲೆ ಉತ್ತರ ಸಿಗುತ್ತದೆ.",
    "Ask the AI Assistant": "AI ಸಹಾಯಕರನ್ನು ಕೇಳಿ",
    "At least 6 characters": "ಕನಿಷ್ಠ 6 ಅಕ್ಷರಗಳು",
    "BhumiGuide AI": "BhumiGuide AI",
    "Calculate charges": "ಶುಲ್ಕ ಲೆಕ್ಕ ಹಾಕಿ",
    "Call office": "ಕಚೇರಿಗೆ ಕರೆ ಮಾಡಿ",
    "Charge type": "ಶುಲ್ಕದ ಪ್ರಕಾರ",
    "Checks are running. A real verification takes 24 to 48 hours.": "ಪರಿಶೀಲನೆಗಳು ನಡೆಯುತ್ತಿವೆ. ನಿಜವಾದ ಪರಿಶೀಲನೆಗೆ 24 ರಿಂದ 48 ಗಂಟೆ ಬೇಕಾಗುತ್ತದೆ.",
    "Choose files to check": "ಪರಿಶೀಲಿಸಲು ಫೈಲ್‌ಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಿ",
    "Choose what BhumiGuide tells you about.": "BhumiGuide ನಿಮಗೆ ಯಾವ ವಿಷಯಗಳ ಬಗ್ಗೆ ತಿಳಿಸಬೇಕು ಎಂದು ಆಯ್ಕೆ ಮಾಡಿ.",
    "Clear and show general procedure": "ತೆರವುಗೊಳಿಸಿ ಸಾಮಾನ್ಯ ಕಾರ್ಯವಿಧಾನ ತೋರಿಸಿ",
    "Collected so far": "ಇಲ್ಲಿಯವರೆಗೆ ಸಂಗ್ರಹಿಸಿದ್ದು",
