    "Delete account": "ಖಾತೆ ಅಳಿಸಿ",
    "Delete your account": "ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಅಳಿಸಿ",
    "District-aware answers, not generic ones.": "ಸಾಮಾನ್ಯ ಉತ್ತರಗಳಲ್ಲ — ನಿಮ್ಮ ಜಿಲ್ಲೆಗೆ ತಕ್ಕ ಉತ್ತರಗಳು.",
    "Do this": "ಇದನ್ನು ಮಾಡಿ",
    "Document help": "ದಾಖಲೆ ಸಹಾಯ",
    "Document requirements change with state and property type. Pick a state on the left to see its own rules, and confirm the final list with your Sub-Registrar office.": "ಬೇಕಾಗುವ ದಾಖಲೆಗಳು ರಾಜ್ಯ ಮತ್ತು ಆಸ್ತಿಯ ಪ್ರಕಾರಕ್ಕೆ ತಕ್ಕಂತೆ ಬದಲಾಗುತ್ತವೆ. ಎಡಭಾಗದಲ್ಲಿ ಒಂದು ರಾಜ್ಯವನ್ನು ಆಯ್ಕೆ ಮಾಡಿ ಅದರ ಸ್ವಂತ ನಿಯಮಗಳನ್ನು ನೋಡಿ, ಮತ್ತು ಅಂತಿಮ ಪಟ್ಟಿಯನ್ನು ನಿಮ್ಮ ಉಪ-ನೋಂದಣಾಧಿಕಾರಿ ಕಚೇರಿಯಲ್ಲಿ ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
