    "Fill in the location and property value, then calculate. Rates differ by state, so the state field matters most.": "ಸ್ಥಳ ಮತ್ತು ಆಸ್ತಿಯ ಮೌಲ್ಯವನ್ನು ಭರ್ತಿ ಮಾಡಿ, ನಂತರ ಲೆಕ್ಕ ಹಾಕಿ. ದರಗಳು ರಾಜ್ಯದಿಂದ ರಾಜ್ಯಕ್ಕೆ ಬೇರೆಯಾಗಿರುತ್ತವೆ, ಆದ್ದರಿಂದ ರಾಜ್ಯದ ಆಯ್ಕೆಯೇ ಅತಿ ಮುಖ್ಯ.",
