    "The percentage shows how much of the site is translated. Untranslated text falls back to English.": "ಸೈಟ್‌ನ ಎಷ್ಟು ಭಾಗ ಅನುವಾದವಾಗಿದೆ ಎಂಬುದನ್ನು ಈ ಶೇಕಡಾವಾರು ತೋರಿಸುತ್ತದೆ. ಅನುವಾದವಾಗದ ಪಠ್ಯ ಇಂಗ್ಲಿಷ್‌ನಲ್ಲೇ ಕಾಣಿಸುತ್ತದೆ.",
    "These contacts were compiled by the project owner for this academic project, not published by any government department. Details can go out of date — please confirm before relying on them.": "ಈ ಸಂಪರ್ಕ ವಿವರಗಳನ್ನು ಈ ಶೈಕ್ಷಣಿಕ ಯೋಜನೆಗಾಗಿ ಯೋಜನೆಯ ಮಾಲೀಕರು ಸಂಗ್ರಹಿಸಿದ್ದಾರೆ; ಇವನ್ನು ಯಾವುದೇ ಸರ್ಕಾರಿ ಇಲಾಖೆ ಪ್ರಕಟಿಸಿಲ್ಲ. ವಿವರಗಳು ಹಳೆಯದಾಗಿರಬಹುದು — ನಂಬುವ ಮೊದಲು ದಯವಿಟ್ಟು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
    "This is an academic prototype built as a final-year project. Contact details are placeholders and messages are not actually delivered anywhere.": "ಇದು ಅಂತಿಮ ವರ್ಷದ ಯೋಜನೆಯಾಗಿ ತಯಾರಿಸಿದ ಶೈಕ್ಷಣಿಕ ಮಾದರಿ. ಸಂಪರ್ಕ ವಿವರಗಳು ಕೇವಲ ಮಾದರಿಯವು ಮತ್ತು ಸಂದೇಶಗಳು ನಿಜವಾಗಿ ಎಲ್ಲಿಗೂ ತಲುಪುವುದಿಲ್ಲ.",
    "This removes your profile, saved documents and verification history. It cannot be undone. In this prototype it simply signs you out and clears the session.": "ಇದು ನಿಮ್ಮ ಪ್ರೊಫೈಲ್, ಉಳಿಸಿದ ದಾಖಲೆಗಳು ಮತ್ತು ಪರಿಶೀಲನೆ ಇತಿಹಾಸವನ್ನು ಅಳಿಸುತ್ತದೆ. ಅಳಿಸಿದ ಮೇಲೆ ಮತ್ತೆ ಹಿಂಪಡೆಯಲು ಆಗುವುದಿಲ್ಲ. ಈ ಮಾದರಿಯಲ್ಲಿ ಇದು ಸರಳವಾಗಿ ನಿಮ್ಮನ್ನು ಸೈನ್ ಔಟ್ ಮಾಡಿ ಸೆಷನ್ ಅನ್ನು ತೆರವುಗೊಳಿಸುತ್ತದೆ.",
    "This taluka": "ಈ ತಾಲೂಕು",
    "Tick a document once you physically have it. The count follows you across the site.": "ದಾಖಲೆ ನಿಮ್ಮ ಕೈಗೆ ಸಿಕ್ಕ ಮೇಲೆ ಅದಕ್ಕೆ ಗುರುತು ಹಾಕಿ. ಈ ಎಣಿಕೆ ಸೈಟ್‌ನ ಎಲ್ಲಾ ಪುಟಗಳಲ್ಲಿಯೂ ಕಾಣಿಸುತ್ತದೆ.",
    "Tick documents on the Documents page as you collect them.": "ದಾಖಲೆಗಳನ್ನು ಸಂಗ್ರಹಿಸಿದಂತೆ ದಾಖಲೆಗಳ ಪುಟದಲ್ಲಿ ಗುರುತು ಹಾಕುತ್ತಾ ಹೋಗಿ.",
    "Time:": "ಸಮಯ:",
    "Total estimated amount": "ಒಟ್ಟು ಅಂದಾಜು ಮೊತ್ತ",
    "Try a shorter word, or clear the mandatory filter.": "ಚಿಕ್ಕ ಪದದಿಂದ ಹುಡುಕಿ ನೋಡಿ, ಅಥವಾ ಕಡ್ಡಾಯ ಫಿಲ್ಟರ್ ತೆಗೆದುಹಾಕಿ.",
    "Try another tab or a shorter search word.": "ಇನ್ನೊಂದು ಟ್ಯಾಬ್ ನೋಡಿ ಅಥವಾ ಚಿಕ್ಕ ಪದದಿಂದ ಹುಡುಕಿ.",
    "Try document readiness check": "ದಾಖಲೆ ಸಿದ್ಧತೆ ಪರಿಶೀಲನೆ ಮಾಡಿ ನೋಡಿ",
    "Two buyers in the same district can need different steps. Inherited land needs heir consent. A shop on farmland needs conversion. A company buyer needs a board resolution. The Smart Procedure Generator asks five questions and rewrites the checklist around your answers.": "ಒಂದೇ ಜಿಲ್ಲೆಯ ಇಬ್ಬರು ಖರೀದಿದಾರರಿಗೆ ಬೇರೆ ಬೇರೆ ಹಂತಗಳು ಬೇಕಾಗಬಹುದು. ವಂಶಪಾರಂಪರ್ಯ ಭೂಮಿಗೆ ವಾರಸುದಾರರ ಒಪ್ಪಿಗೆ ಬೇಕು. ಕೃಷಿ ಭೂಮಿಯಲ್ಲಿ ಅಂಗಡಿ ಕಟ್ಟಬೇಕಾದರೆ ಭೂಪರಿವರ್ತನೆ ಬೇಕು. ಕಂಪನಿ ಖರೀದಿದಾರರಿಗೆ ಮಂಡಳಿಯ ನಿರ್ಣಯ ಬೇಕು. ಸ್ಮಾರ್ಟ್ ಕಾರ್ಯವಿಧಾನ ಜನರೇಟರ್ ಐದು ಪ್ರಶ್ನೆಗಳನ್ನು ಕೇಳಿ ನಿಮ್ಮ ಉತ್ತರಗಳಿಗೆ ತಕ್ಕಂತೆ ಪರಿಶೀಲನಾ ಪಟ್ಟಿಯನ್ನು ಮತ್ತೆ ರಚಿಸುತ್ತದೆ.",
    "Type your question here…": "ನಿಮ್ಮ ಪ್ರಶ್ನೆಯನ್ನು ಇಲ್ಲಿ ಬರೆಯಿರಿ…",
    "Updates on land laws and processes.": "ಭೂ ಕಾನೂನುಗಳು ಮತ್ತು ಪ್ರಕ್ರಿಯೆಗಳ ಕುರಿತ ಹೊಸ ಮಾಹಿತಿ.",
    "Used across the site and in AI answers": "ಸೈಟ್‌ನ ಎಲ್ಲೆಡೆ ಮತ್ತು AI ಉತ್ತರಗಳಲ್ಲಿ ಬಳಸಲಾಗುತ್ತದೆ",
    "Verification progress": "ಪರಿಶೀಲನೆಯ ಪ್ರಗತಿ",
    "What each document is, why it is needed, where to get it and roughly what it costs.": "ಪ್ರತಿ ದಾಖಲೆ ಏನು, ಅದು ಏಕೆ ಬೇಕು, ಎಲ್ಲಿ ಸಿಗುತ್ತದೆ ಮತ್ತು ಸುಮಾರು ಎಷ್ಟು ಖರ್ಚಾಗುತ್ತದೆ.",
    "What makes this different": "ಇದು ಹೇಗೆ ಭಿನ್ನ",
    "What you should double-check": "ನೀವು ಮತ್ತೊಮ್ಮೆ ಪರಿಶೀಲಿಸಬೇಕಾದ ವಿಷಯಗಳು",
    "Where you are in the land buying process right now.": "ಭೂಮಿ ಖರೀದಿ ಪ್ರಕ್ರಿಯೆಯಲ್ಲಿ ನೀವು ಈಗ ಯಾವ ಹಂತದಲ್ಲಿದ್ದೀರಿ.",
    "Whole district": "ಇಡೀ ಜಿಲ್ಲೆ",
    "Why this step matters": "ಈ ಹಂತ ಏಕೆ ಮುಖ್ಯ",
    "Your account, progress and uploaded documents are saved to the backend database.": "ನಿಮ್ಮ ಖಾತೆ, ಪ್ರಗತಿ ಮತ್ತು ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ದಾಖಲೆಗಳು ಬ್ಯಾಕೆಂಡ್ ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಉಳಿಯುತ್ತವೆ.",
    "Your document checklist": "ನಿಮ್ಮ ದಾಖಲೆಗಳ ಪರಿಶೀಲನಾ ಪಟ್ಟಿ",
