    "Answering for": "જવાબ આના માટે",
    "Answers are for general guidance in an academic prototype. Confirm anything that affects your money with a lawyer or the concerned government office.": "આ જવાબો શૈક્ષણિક પ્રોટોટાઇપમાં સામાન્ય માર્ગદર્શન માટે છે. તમારા પૈસાને અસર કરે તેવી કોઈ પણ બાબત વકીલ અથવા સંબંધિત સરકારી કચેરીમાં ચકાસી લો.",
