    "Document requirements change with state and property type. Pick a state on the left to see its own rules, and confirm the final list with your Sub-Registrar office.": "કયા દસ્તાવેજ જોઈએ તે રાજ્ય અને મિલકતના પ્રકાર પ્રમાણે બદલાય છે. ડાબી બાજુથી રાજ્ય પસંદ કરીને તેના પોતાના નિયમો જુઓ, અને આખરી યાદી તમારી સબ-રજિસ્ટ્રાર કચેરીમાં ચકાસી લો.",
