    "Fill in the location and property value, then calculate. Rates differ by state, so the state field matters most.": "સ્થળ અને મિલકતની કિંમત ભરો, પછી ગણતરી કરો. દર દરેક રાજ્યમાં અલગ હોય છે, એટલે રાજ્યનું ખાનું સૌથી વધુ મહત્ત્વનું છે.",
    "Fill the form and start a verification to see the checks run.": "ફોર્મ ભરો અને ચકાસણી શરૂ કરો, જેથી તપાસ ચાલતી જોઈ શકો.",
