    "In this prototype the assistant runs on a local rule base built from verified government guidance. In production it would be an LLM with retrieval over district-wise documents.": "આ પ્રોટોટાઇપમાં આસિસ્ટન્ટ ચકાસાયેલ સરકારી માર્ગદર્શનમાંથી બનાવેલા સ્થાનિક નિયમોના આધારે ચાલે છે. ખરેખરના ઉપયોગમાં તે જિલ્લાવાર દસ્તાવેજો શોધીને જવાબ આપતું LLM હોત.",
