    "Tell us what you need help with…": "તમને શેમાં મદદ જોઈએ છે તે જણાવો…",
    "The percentage shows how much of the site is translated. Untranslated text falls back to English.": "ટકાવારી બતાવે છે કે સાઇટનો કેટલો ભાગ અનુવાદ થયો છે. જેનો અનુવાદ ન થયો હોય તે લખાણ અંગ્રેજીમાં દેખાશે.",
    "These contacts were compiled by the project owner for this academic project, not published by any government department. Details can go out of date — please confirm before relying on them.": "આ સંપર્કો આ શૈક્ષણિક પ્રોજેક્ટ માટે પ્રોજેક્ટના માલિકે ભેગા કર્યા છે, કોઈ સરકારી વિભાગે પ્રસિદ્ધ કર્યા નથી. વિગતો જૂની થઈ શકે છે — તેના પર ભરોસો કરતાં પહેલાં ચકાસી લેવા વિનંતી.",
    "This is an academic prototype built as a final-year project. Contact details are placeholders and messages are not actually delivered anywhere.": "આ છેલ્લા વર્ષના પ્રોજેક્ટ તરીકે બનાવેલો શૈક્ષણિક પ્રોટોટાઇપ છે. સંપર્કની વિગતો ફક્ત નમૂનારૂપ છે અને સંદેશા ખરેખર ક્યાંય પહોંચતા નથી.",
    "This removes your profile, saved documents and verification history. It cannot be undone. In this prototype it simply signs you out and clears the session.": "આનાથી તમારી પ્રોફાઇલ, સાચવેલા દસ્તાવેજો અને ચકાસણીનો ઇતિહાસ કાઢી નાખવામાં આવશે. આ પાછું લાવી શકાતું નથી. આ પ્રોટોટાઇપમાં તે માત્ર તમને સાઇન આઉટ કરે છે અને સત્ર સાફ કરે છે.",
    "This taluka": "આ તાલુકો",
    "Tick a document once you physically have it. The count follows you across the site.": "દસ્તાવેજ ખરેખર તમારા હાથમાં આવે પછી તેના પર નિશાની કરો. આ ગણતરી આખી સાઇટ પર તમારી સાથે રહે છે.",
    "Tick documents on the Documents page as you collect them.": "દસ્તાવેજો ભેગા થતા જાય તેમ 'દસ્તાવેજો' પાના પર તેમના પર નિશાની કરતા જાઓ.",
    "Time:": "સમય:",
    "Total estimated amount": "કુલ અંદાજિત રકમ",
    "Try a shorter word, or clear the mandatory filter.": "ટૂંકો શબ્દ અજમાવો, અથવા 'ફરજિયાત' ફિલ્ટર કાઢી નાખો.",
    "Try another tab or a shorter search word.": "બીજું ટૅબ અજમાવો અથવા ટૂંકો શબ્દ શોધો.",
    "Try document readiness check": "દસ્તાવેજ તૈયારી ચકાસણી અજમાવો",
    "Two buyers in the same district can need different steps. Inherited land needs heir consent. A shop on farmland needs conversion. A company buyer needs a board resolution. The Smart Procedure Generator asks five questions and rewrites the checklist around your answers.": "એક જ જિલ્લાના બે ખરીદનારને અલગ અલગ પગલાં ભરવાં પડી શકે છે. વારસાઈ જમીન માટે વારસદારોની સંમતિ જોઈએ. ખેતીની જમીન પર દુકાન બનાવવી હોય તો બિનખેતી કરાવવી પડે. કંપની ખરીદનાર હોય તો બોર્ડ ઠરાવ જોઈએ. સ્માર્ટ પ્રોસિજર જનરેટર પાંચ પ્રશ્નો પૂછે છે અને તમારા જવાબો પ્રમાણે આખું ચેકલિસ્ટ ફરીથી બનાવે છે.",
    "Type your question here…": "તમારો પ્રશ્ન અહીં લખો…",
    "Updates on land laws and processes.": "જમીનના કાયદા અને પ્રક્રિયાઓ અંગેની તાજી માહિતી.",
    "Used across the site and in AI answers": "આખી સાઇટ પર અને AI ના જવાબોમાં વપરાય છે",
    "Verification progress": "ચકાસણીની પ્રગતિ",
    "What each document is, why it is needed, where to get it and roughly what it costs.": "દરેક દસ્તાવેજ શું છે, શા માટે જરૂરી છે, ક્યાંથી મળે છે અને આશરે કેટલો ખર્ચ થાય છે.",
