    "The percentage shows how much of the site is translated. Untranslated text falls back to English.": "শতাংশটি দেখাচ্ছে সাইটের কতটা অনুবাদ হয়েছে। যেটুকু অনুবাদ হয়নি, সেটুকু ইংরেজিতেই দেখানো হবে।",
    "These contacts were compiled by the project owner for this academic project, not published by any government department. Details can go out of date — please confirm before relying on them.": "এই যোগাযোগের তথ্যগুলো এই শিক্ষামূলক প্রোজেক্টের জন্য প্রোজেক্টের মালিক নিজে জোগাড় করেছেন, কোনো সরকারি দপ্তর প্রকাশ করেনি। তথ্য পুরনো হয়ে যেতে পারে — ভরসা করার আগে যাচাই করে নিন।",
    "This is an academic prototype built as a final-year project. Contact details are placeholders and messages are not actually delivered anywhere.": "এটি ফাইনাল ইয়ার প্রোজেক্ট হিসেবে বানানো একটি শিক্ষামূলক প্রোটোটাইপ। যোগাযোগের তথ্যগুলো নমুনামাত্র, আর পাঠানো বার্তা আসলে কোথাও পৌঁছয় না।",
    "This removes your profile, saved documents and verification history. It cannot be undone. In this prototype it simply signs you out and clears the session.": "এতে আপনার প্রোফাইল, সেভ করা নথি আর যাচাইয়ের ইতিহাস মুছে যাবে। এটি আর ফেরানো যাবে না। এই প্রোটোটাইপে এটি শুধু আপনাকে সাইন আউট করে সেশনটি মুছে দেয়।",
