    "Rates here are indicative demo values for a college project. Confirm the exact figure with the Sub-Registrar office before paying.": "ਇੱਥੇ ਦਿੱਤੀਆਂ ਦਰਾਂ ਕਾਲਜ ਪ੍ਰੋਜੈਕਟ ਲਈ ਸਿਰਫ਼ ਨਮੂਨੇ ਦੀਆਂ ਹਨ। ਪੈਸੇ ਭਰਨ ਤੋਂ ਪਹਿਲਾਂ ਸਹੀ ਰਕਮ ਸਬ-ਰਜਿਸਟਰਾਰ ਦਫ਼ਤਰ ਤੋਂ ਪੱਕੀ ਕਰ ਲਵੋ।",
