    "Seven quick questions. Inherited land, joint owners, urban plots and company buyers each add their own steps.": "ਸੱਤ ਛੋਟੇ ਸਵਾਲ। ਵਿਰਾਸਤੀ ਜ਼ਮੀਨ, ਸਾਂਝੇ ਮਾਲਕ, ਸ਼ਹਿਰੀ ਪਲਾਟ ਅਤੇ ਕੰਪਨੀ ਖ਼ਰੀਦਦਾਰ — ਹਰ ਇੱਕ ਨਾਲ ਕੁਝ ਵਾਧੂ ਪੜਾਅ ਜੁੜ ਜਾਂਦੇ ਹਨ।",
