    "The percentage shows how much of the site is translated. Untranslated text falls back to English.": "ਫ਼ੀਸਦੀ ਦੱਸਦੀ ਹੈ ਕਿ ਸਾਈਟ ਦਾ ਕਿੰਨਾ ਹਿੱਸਾ ਅਨੁਵਾਦ ਹੋ ਚੁੱਕਾ ਹੈ। ਜਿਹੜਾ ਹਿੱਸਾ ਅਨੁਵਾਦ ਨਹੀਂ ਹੋਇਆ, ਉਹ ਅੰਗਰੇਜ਼ੀ ਵਿੱਚ ਹੀ ਦਿਸੇਗਾ।",
    "These contacts were compiled by the project owner for this academic project, not published by any government department. Details can go out of date — please confirm before relying on them.": "ਇਹ ਸੰਪਰਕ ਇਸ ਵਿੱਦਿਅਕ ਪ੍ਰੋਜੈਕਟ ਲਈ ਪ੍ਰੋਜੈਕਟ ਬਣਾਉਣ ਵਾਲੇ ਨੇ ਇਕੱਠੇ ਕੀਤੇ ਹਨ, ਇਹ ਕਿਸੇ ਸਰਕਾਰੀ ਮਹਿਕਮੇ ਵੱਲੋਂ ਜਾਰੀ ਨਹੀਂ ਕੀਤੇ ਗਏ। ਵੇਰਵੇ ਪੁਰਾਣੇ ਹੋ ਸਕਦੇ ਹਨ — ਇਹਨਾਂ 'ਤੇ ਭਰੋਸਾ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਪੱਕਾ ਕਰ ਲਵੋ।",
    "This is an academic prototype built as a final-year project. Contact details are placeholders and messages are not actually delivered anywhere.": "ਇਹ ਆਖ਼ਰੀ ਸਾਲ ਦੇ ਪ੍ਰੋਜੈਕਟ ਵਜੋਂ ਬਣਾਇਆ ਵਿੱਦਿਅਕ ਨਮੂਨਾ ਹੈ। ਸੰਪਰਕ ਵੇਰਵੇ ਸਿਰਫ਼ ਵਿਖਾਵੇ ਲਈ ਹਨ ਅਤੇ ਸੁਨੇਹੇ ਅਸਲ ਵਿੱਚ ਕਿਤੇ ਨਹੀਂ ਪਹੁੰਚਦੇ।",
    "This removes your profile, saved documents and verification history. It cannot be undone. In this prototype it simply signs you out and clears the session.": "ਇਸ ਨਾਲ ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ, ਸੰਭਾਲੇ ਦਸਤਾਵੇਜ਼ ਅਤੇ ਤਸਦੀਕ ਦਾ ਇਤਿਹਾਸ ਮਿਟ ਜਾਵੇਗਾ। ਇਹ ਵਾਪਸ ਨਹੀਂ ਲਿਆਂਦਾ ਜਾ ਸਕਦਾ। ਇਸ ਨਮੂਨੇ ਵਿੱਚ ਇਹ ਸਿਰਫ਼ ਤੁਹਾਨੂੰ ਸਾਈਨ ਆਊਟ ਕਰ ਕੇ ਸੈਸ਼ਨ ਖ਼ਤਮ ਕਰ ਦਿੰਦਾ ਹੈ।",
    "This taluka": "ਇਹ ਤਹਿਸੀਲ",
    "Tick a document once you physically have it. The count follows you across the site.": "ਜਦੋਂ ਦਸਤਾਵੇਜ਼ ਸੱਚਮੁੱਚ ਤੁਹਾਡੇ ਹੱਥ ਆ ਜਾਵੇ, ਉਦੋਂ ਉਸ 'ਤੇ ਨਿਸ਼ਾਨ ਲਾ ਦਿਓ। ਇਹ ਗਿਣਤੀ ਪੂਰੀ ਸਾਈਟ 'ਤੇ ਤੁਹਾਡੇ ਨਾਲ ਚੱਲਦੀ ਹੈ।",
    "Tick documents on the Documents page as you collect them.": "ਜਿਵੇਂ-ਜਿਵੇਂ ਦਸਤਾਵੇਜ਼ ਇਕੱਠੇ ਹੁੰਦੇ ਜਾਣ, ਦਸਤਾਵੇਜ਼ ਵਾਲੇ ਪੰਨੇ 'ਤੇ ਉਹਨਾਂ ਉੱਤੇ ਨਿਸ਼ਾਨ ਲਾਉਂਦੇ ਜਾਓ।",
    "Time:": "ਸਮਾਂ:",
    "Total estimated amount": "ਕੁੱਲ ਅੰਦਾਜ਼ਨ ਰਕਮ",
    "Try a shorter word, or clear the mandatory filter.": "ਕੋਈ ਛੋਟਾ ਸ਼ਬਦ ਵਰਤ ਕੇ ਵੇਖੋ, ਜਾਂ ਲਾਜ਼ਮੀ ਵਾਲਾ ਫ਼ਿਲਟਰ ਹਟਾ ਦਿਓ।",
    "Try another tab or a shorter search word.": "ਕੋਈ ਹੋਰ ਟੈਬ ਵੇਖੋ ਜਾਂ ਛੋਟਾ ਸ਼ਬਦ ਲਿਖ ਕੇ ਲੱਭੋ।",
    "Try document readiness check": "ਦਸਤਾਵੇਜ਼ ਤਿਆਰੀ ਜਾਂਚ ਵਰਤ ਕੇ ਵੇਖੋ",
    "Two buyers in the same district can need different steps. Inherited land needs heir consent. A shop on farmland needs conversion. A company buyer needs a board resolution. The Smart Procedure Generator asks five questions and rewrites the checklist around your answers.": "ਇੱਕੋ ਜ਼ਿਲ੍ਹੇ ਦੇ ਦੋ ਖ਼ਰੀਦਦਾਰਾਂ ਲਈ ਪੜਾਅ ਵੱਖਰੇ ਹੋ ਸਕਦੇ ਹਨ। ਵਿਰਾਸਤੀ ਜ਼ਮੀਨ ਲਈ ਵਾਰਸਾਂ ਦੀ ਸਹਿਮਤੀ ਚਾਹੀਦੀ ਹੈ। ਖੇਤੀ ਵਾਲੀ ਜ਼ਮੀਨ 'ਤੇ ਦੁਕਾਨ ਲਈ ਜ਼ਮੀਨ ਦੀ ਵਰਤੋਂ ਬਦਲਵਾਉਣੀ ਪੈਂਦੀ ਹੈ। ਕੰਪਨੀ ਖ਼ਰੀਦਦਾਰ ਲਈ ਬੋਰਡ ਦਾ ਮਤਾ ਚਾਹੀਦਾ ਹੈ। ਸਮਾਰਟ ਵਿਧੀ ਜਨਰੇਟਰ ਪੰਜ ਸਵਾਲ ਪੁੱਛਦਾ ਹੈ ਅਤੇ ਤੁਹਾਡੇ ਜਵਾਬਾਂ ਮੁਤਾਬਕ ਸੂਚੀ ਨਵੇਂ ਸਿਰਿਓਂ ਬਣਾ ਦਿੰਦਾ ਹੈ।",
    "Type your question here…": "ਆਪਣਾ ਸਵਾਲ ਇੱਥੇ ਲਿਖੋ…",
    "Updates on land laws and processes.": "ਜ਼ਮੀਨੀ ਕਾਨੂੰਨਾਂ ਅਤੇ ਕਾਰਵਾਈਆਂ ਬਾਰੇ ਤਾਜ਼ਾ ਜਾਣਕਾਰੀ।",
    "Used across the site and in AI answers": "ਪੂਰੀ ਸਾਈਟ ਅਤੇ AI ਦੇ ਜਵਾਬਾਂ ਵਿੱਚ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ",
    "Verification progress": "ਤਸਦੀਕ ਦੀ ਪ੍ਰਗਤੀ",
    "What each document is, why it is needed, where to get it and roughly what it costs.": "ਹਰ ਦਸਤਾਵੇਜ਼ ਕੀ ਹੈ, ਕਿਉਂ ਚਾਹੀਦਾ ਹੈ, ਕਿੱਥੋਂ ਮਿਲਦਾ ਹੈ ਅਤੇ ਮੋਟੇ ਤੌਰ 'ਤੇ ਕਿੰਨਾ ਖ਼ਰਚ ਆਉਂਦਾ ਹੈ।",
