    "Registration is what transfers legal title. An unregistered sale deed does not give you ownership, whatever the seller says.": "कानूनी मालिकाना हक रजिस्ट्रेशन से ही मिलता है। बिना रजिस्टर हुआ बिक्री विलेख आपको मालिकाना हक नहीं देता, विक्रेता चाहे कुछ भी कहे।",
    "Registration transfers title; mutation updates the government's revenue record. Until mutation is done, tax bills and future sales stay in the seller's name.": "रजिस्ट्रेशन से मालिकाना हक मिलता है; नामांतरण से सरकारी राजस्व रिकॉर्ड अपडेट होता है। जब तक नामांतरण नहीं होता, टैक्स के बिल और आगे की बिक्री विक्रेता के नाम पर ही रहती है।",
