    "Thanks": "धन्यवाद",
    "The Collector's order permitting the land to be used for residential, commercial or industrial purposes.": "कलेक्टर का वह आदेश जो ज़मीन को रिहायशी, व्यावसायिक या औद्योगिक उपयोग की इजाज़त देता है।",
    "The Sub-Registrar captures biometrics against Aadhaar at registration. Both buyer and seller need it.": "रजिस्ट्रेशन के समय सब-रजिस्ट्रार Aadhaar से जोड़कर बायोमेट्रिक लेता है। खरीदार और विक्रेता, दोनों को इसकी ज़रूरत होती है।",
    "The Sub-Registrar will ask who is authorised to sign for the company. Without a board resolution, registration stops at the counter.": "सब-रजिस्ट्रार पूछेगा कि कंपनी की ओर से हस्ताक्षर करने का अधिकार किसे है। बोर्ड प्रस्ताव के बिना रजिस्ट्रेशन काउंटर पर ही रुक जाता है।",
    "The account maintained by the local body that links the property to its tax record.": "स्थानीय निकाय का वह खाता जो संपत्ति को उसके टैक्स रिकॉर्ड से जोड़ता है।",
    "The agreement fixes the price and the deadline, and records the advance you paid. Without it, an advance is very hard to recover.": "करार में कीमत और समय-सीमा तय होती है, और आपने जो अग्रिम रकम दी है वह भी दर्ज होती है। इसके बिना अग्रिम रकम वापस पाना बहुत मुश्किल है।",
    "The bank's legal opinion is a free second review of your title. If the bank refuses the property, treat that as a serious warning.": "बैंक की कानूनी राय आपके मालिकाना हक की मुफ्त दूसरी जाँच होती है। अगर बैंक इस संपत्ति से मना कर दे, तो इसे गंभीर चेतावनी मानें।",
    "The circle / ready reckoner rate for that exact survey number": "उसी सर्वे नंबर का सर्कल / रेडी रेकनर रेट",
    "The core legal document that records the transfer of ownership from seller to buyer.": "वह मुख्य कानूनी दस्तावेज़ जिसमें विक्रेता से खरीदार को मालिकाना हक मिलने की बात दर्ज होती है।",
    "The extract shows the current holder, the land area, tenure type and any loan or court entry noted in the 'other rights' column.": "उतारे में मौजूदा धारक, ज़मीन का क्षेत्रफल, धारणा-अधिकार का प्रकार और 'अन्य अधिकार' कॉलम में दर्ज कोई भी लोन या कोर्ट एंट्री दिखती है।",
    "The mutation entry showing when the current holder's name was added to the revenue record.": "नामांतरण की वह एंट्री जो बताती है कि मौजूदा धारक का नाम राजस्व रिकॉर्ड में कब जोड़ा गया।",
    "The receipt from the local body showing property tax has been paid up to date.": "स्थानीय निकाय की वह रसीद जो बताती है कि संपत्ति कर आज तक भरा जा चुका है।",
    "The registered deed transferring ownership.": "मालिकाना हक ट्रांसफर करने वाला रजिस्टर्ड विलेख।",
    "The registration form records the present address of both parties.": "रजिस्ट्रेशन फॉर्म में दोनों पक्षों का मौजूदा पता दर्ज होता है।",
    "The set of earlier registered deeds showing how the property moved from owner to owner.": "पहले के रजिस्टर्ड विलेखों का समूह, जो बताता है कि संपत्ति एक मालिक से दूसरे मालिक तक कैसे पहुँची।",
    "The state revenue record showing the current holder, area, tenure and any registered charge on the land.": "राज्य का राजस्व रिकॉर्ड, जिसमें मौजूदा धारक, क्षेत्रफल, धारणा-अधिकार और ज़मीन पर दर्ज कोई भी भार दिखता है।",
    "The tax identification number issued by the Income Tax Department.": "आयकर विभाग द्वारा जारी कर पहचान संख्या।",
    "The whole process end to end, written for a first-time buyer.": "शुरू से आखिर तक पूरी प्रक्रिया, पहली बार ज़मीन खरीदने वालों के लिए।",
    "This is the document that actually makes you the owner. Everything else supports it.": "असल में यही दस्तावेज़ आपको मालिक बनाता है। बाकी सब इसी का सहारा हैं।",
    "This is the government's own statement of who holds the land. It should be dated within the last 3 months.": "यह सरकार का अपना कथन है कि ज़मीन किसके पास है। इसकी तारीख पिछले 3 महीने के भीतर की होनी चाहिए।",
    "Tool": "टूल",
    "Track the objection period — usually 15 to 30 days": "आपत्ति की अवधि पर नज़र रखें — आम तौर पर 15 से 30 दिन",
    "Two-factor authentication": "दो-चरणीय सत्यापन",
