    "Unapproved layouts cannot get building permission or a water and power connection, and resale value stays low.": "बिना मंज़ूरी वाले लेआउट में न निर्माण की इजाज़त मिलती है, न पानी और बिजली का कनेक्शन, और दोबारा बेचने पर कीमत भी कम रहती है।",
