    "Terms & Conditions": "अटी व शर्ती",
    "Thanks": "धन्यवाद",
    "The Collector's order permitting the land to be used for residential, commercial or industrial purposes.": "जमीन रहिवासी, व्यापारी किंवा औद्योगिक कारणांसाठी वापरण्यास परवानगी देणारा जिल्हाधिकाऱ्यांचा आदेश.",
    "The Sub-Registrar captures biometrics against Aadhaar at registration. Both buyer and seller need it.": "नोंदणीच्या वेळी दुय्यम निबंधक Aadhaar शी जोडून बायोमेट्रिक घेतात. खरेदीदार व विक्रेता दोघांनाही ते आवश्यक आहे.",
    "The Sub-Registrar will ask who is authorised to sign for the company. Without a board resolution, registration stops at the counter.": "कंपनीच्या वतीने सही करण्याचा अधिकार कोणाला आहे हे दुय्यम निबंधक विचारतील. संचालक मंडळाच्या ठरावाशिवाय नोंदणी काउंटरवरच थांबते.",
    "The account maintained by the local body that links the property to its tax record.": "मालमत्तेचा कराच्या नोंदीशी संबंध जोडणारे, स्थानिक संस्थेकडे ठेवले जाणारे खाते.",
    "The agreement fixes the price and the deadline, and records the advance you paid. Without it, an advance is very hard to recover.": "करारनाम्यात किंमत व मुदत ठरते आणि तुम्ही दिलेली आगाऊ रक्कम नोंदली जाते. तो नसेल तर आगाऊ रक्कम परत मिळवणे फार अवघड होते.",
    "The bank's legal opinion is a free second review of your title. If the bank refuses the property, treat that as a serious warning.": "बँकेचे कायदेशीर मत म्हणजे तुमच्या मालकी हक्कांची मोफत दुसरी तपासणी. बँकेने मालमत्ता नाकारली तर तो गंभीर इशारा समजा.",
    "The circle / ready reckoner rate for that exact survey number": "नेमक्या त्या सर्वे नंबरचा सर्कल / रेडी रेकनर दर",
    "The core legal document that records the transfer of ownership from seller to buyer.": "विक्रेत्याकडून खरेदीदाराकडे मालकी हस्तांतरित झाल्याची नोंद करणारे मुख्य कायदेशीर कागदपत्र.",
    "The extract shows the current holder, the land area, tenure type and any loan or court entry noted in the 'other rights' column.": "उताऱ्यावर सध्याचा धारक, जमिनीचे क्षेत्रफळ, भोगवटादार वर्ग आणि 'इतर हक्क' रकान्यातील कर्ज किंवा न्यायालयीन नोंद दिसते.",
    "The mutation entry showing when the current holder's name was added to the revenue record.": "सध्याच्या धारकाचे नाव महसूल अभिलेखात कधी नोंदले गेले हे दाखवणारी फेरफार नोंद.",
    "The receipt from the local body showing property tax has been paid up to date.": "मालमत्ता कर आजपर्यंत भरला असल्याचे दाखवणारी स्थानिक संस्थेची पावती.",
    "The registered deed transferring ownership.": "मालकी हस्तांतरित करणारे नोंदणीकृत खरेदीखत.",
    "The registration form records the present address of both parties.": "नोंदणी अर्जात दोन्ही पक्षांचा सध्याचा पत्ता नोंदवला जातो.",
    "The set of earlier registered deeds showing how the property moved from owner to owner.": "मालमत्ता एका मालकाकडून दुसऱ्याकडे कशी गेली हे दाखवणारी पूर्वीची नोंदणीकृत कागदपत्रे.",
    "The state revenue record showing the current holder, area, tenure and any registered charge on the land.": "सध्याचा धारक, क्षेत्रफळ, भोगवटादार वर्ग व जमिनीवरील नोंदणीकृत बोजा दाखवणारा राज्याचा महसूल अभिलेख.",
    "The tax identification number issued by the Income Tax Department.": "आयकर विभागाने दिलेला कर ओळख क्रमांक.",
    "The whole process end to end, written for a first-time buyer.": "पहिल्यांदाच जमीन घेणाऱ्यासाठी लिहिलेली सुरुवातीपासून शेवटपर्यंतची संपूर्ण प्रक्रिया.",
    "This is the document that actually makes you the owner. Everything else supports it.": "याच कागदपत्रामुळे तुम्ही खरे मालक होता. बाकीची सर्व कागदपत्रे त्याला पूरक असतात.",
    "This is the government's own statement of who holds the land. It should be dated within the last 3 months.": "जमीन कोणाच्या ताब्यात आहे हे सांगणारा हा सरकारचाच अभिलेख आहे. तो मागील 3 महिन्यांतील असावा.",
    "Tool": "साधन",
    "Track the objection period — usually 15 to 30 days": "हरकतीचा कालावधी लक्षात ठेवा — सहसा 15 ते 30 दिवस",
    "Two-factor authentication": "दोन टप्प्यांतील पडताळणी",
    "UIDAI portal or any Aadhaar Seva Kendra": "UIDAI पोर्टल किंवा कोणतेही Aadhaar सेवा केंद्र",
    "Unapproved layouts cannot get building permission or a water and power connection, and resale value stays low.": "मंजुरी नसलेल्या लेआउटला बांधकाम परवानगी किंवा पाणी व वीज जोडणी मिळत नाही आणि पुनर्विक्रीची किंमतही कमी राहते.",
    "Understanding the encumbrance certificate": "बोजा प्रमाणपत्र कसे समजून घ्यावे",
    "Unmark": "खूण काढा",
    "Unpaid tax becomes your liability after purchase, and the municipal record also confirms possession.": "न भरलेला कर खरेदीनंतर तुमची जबाबदारी होतो, शिवाय पालिकेच्या नोंदीवरून ताबाही सिद्ध होतो.",
    "Unrecognised document": "न ओळखता आलेले कागदपत्र",
    "Upload failed.": "अपलोड होऊ शकले नाही.",
    "Uploading…": "अपलोड होत आहे…",
    "Urban": "शहरी",
