    "No active charge found": "செயலில் உள்ள சுமை எதுவும் கண்டறியப்படவில்லை",
    "No case found in the searched records": "தேடப்பட்ட பதிவேடுகளில் வழக்கு எதுவும் கண்டறியப்படவில்லை",
    "No contact is listed for": "தொடர்பு விவரம் எதுவும் பட்டியலிடப்படவில்லை —",
    "No contacts are on file for": "தொடர்பு விவரங்கள் எதுவும் பதிவில் இல்லை —",
    "No location selected yet": "இன்னும் எந்த இடமும் தேர்ந்தெடுக்கப்படவில்லை",
    "Non-Agricultural (NA) Conversion": "விவசாயமற்ற (NA) நிலமாற்றம்",
    "Not selected": "தேர்ந்தெடுக்கப்படவில்லை",
