    "Office": "அலுவலகம்",
    "Official survey map of the plot.": "மனையின் அதிகாரப்பூர்வ நில அளவை வரைபடம்.",
    "Only for important account updates": "முக்கியமான கணக்குப் புதுப்பிப்புகளுக்கு மட்டும்",
    "Open now": "இப்போது திறந்துள்ளது",
    "Order converting agricultural land to non-agricultural use.": "விவசாய நிலத்தை விவசாயமற்ற பயன்பாட்டுக்கு மாற்றும் ஆணை.",
    "Owner verification": "உரிமையாளர் சரிபார்ப்பு",
    "Ownership count unconfirmed — check it": "உரிமையாளர்களின் எண்ணிக்கை உறுதிப்படுத்தப்படவில்லை — சரிபாருங்கள்",
