    "Paid to the state government on the property value.": "சொத்து மதிப்பின் மீது மாநில அரசுக்குச் செலுத்தப்படுகிறது.",
    "Partnership firm": "கூட்டாண்மை நிறுவனம்",
    "Pass a board resolution approving the purchase": "கொள்முதலுக்கு ஒப்புதல் அளிக்கும் இயக்குநர் குழுத் தீர்மானத்தை நிறைவேற்றுங்கள்",
    "Passport Size Photographs": "பாஸ்போர்ட் அளவு புகைப்படங்கள்",
    "Pay Stamp Duty": "முத்திரைத் தீர்வையைச் செலுத்துங்கள்",
    "Pay state stamp duty on the higher of market value or ready reckoner value.": "சந்தை மதிப்பு அல்லது வழிகாட்டி மதிப்பு — எது அதிகமோ அதன் மீது மாநில முத்திரைத் தீர்வையைச் செலுத்துங்கள்.",
    "Pay the conversion premium once sanctioned": "அனுமதி கிடைத்ததும் நிலமாற்றக் கட்டணத்தைச் செலுத்துங்கள்",
    "Percentage of property value": "சொத்து மதிப்பின் சதவீதம்",
    "Permanent Account Number card.": "நிரந்தரக் கணக்கு எண் (PAN) அட்டை.",
