    "Build a house or shop": "ఇల్లు లేదా దుకాణం కట్టడానికి",
    "Building on agricultural land without conversion is unauthorised construction, and banks will refuse a loan on it.": "మార్పిడి చేయించకుండా వ్యవసాయ భూమిపై కట్టడం అనధికార నిర్మాణం అవుతుంది, దానిపై బ్యాంకులు రుణం ఇవ్వవు.",
    "Carry the company PAN, incorporation certificate and resolution copy": "కంపెనీ PAN, ఇన్‌కార్పొరేషన్ సర్టిఫికేట్, తీర్మానం కాపీ తీసుకెళ్లండి",
