    "Already have an account? ": "ಈಗಾಗಲೇ ಖಾತೆ ಇದೆಯೇ? ",
    "An encumbrance certificate lists every registered transaction on the property. A blank certificate for the search period is what you want to see.": "ಋಣಭಾರ ಪ್ರಮಾಣಪತ್ರವು ಆಸ್ತಿಯ ಮೇಲಿನ ಪ್ರತಿ ನೋಂದಾಯಿತ ವ್ಯವಹಾರವನ್ನು ಪಟ್ಟಿ ಮಾಡುತ್ತದೆ. ಹುಡುಕಿದ ಅವಧಿಗೆ ಖಾಲಿ ಪ್ರಮಾಣಪತ್ರ ಸಿಕ್ಕರೆ ಅದೇ ನಿಮಗೆ ಬೇಕಾದದ್ದು.",
    "Any concession scheme running this financial year": "ಈ ಆರ್ಥಿಕ ವರ್ಷದಲ್ಲಿ ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಯಾವುದೇ ರಿಯಾಯಿತಿ ಯೋಜನೆ",
    "Any government-accepted document showing your current residential address.": "ನಿಮ್ಮ ಪ್ರಸ್ತುತ ವಾಸದ ವಿಳಾಸ ತೋರಿಸುವ ಯಾವುದೇ ಸರ್ಕಾರಿ-ಮಾನ್ಯ ದಾಖಲೆ.",
    "Any photo studio": "ಯಾವುದೇ ಫೋಟೋ ಸ್ಟುಡಿಯೋ",
    "Apply for Mutation": "ಖಾತಾ ಬದಲಾವಣೆಗೆ (ಮ್ಯುಟೇಶನ್) ಅರ್ಜಿ ಸಲ್ಲಿಸಿ",
    "Apply for a 13-year search period at minimum (30 years is safer)": "ಕನಿಷ್ಠ 13 ವರ್ಷಗಳ ಶೋಧನಾ ಅವಧಿಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ (30 ವರ್ಷ ಇನ್ನೂ ಸುರಕ್ಷಿತ)",
    "Apply to the Collector with the layout plan": "ವಿನ್ಯಾಸ ನಕ್ಷೆಯೊಂದಿಗೆ ಜಿಲ್ಲಾಧಿಕಾರಿಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ",
