    "Arrange the technical valuation site visit": "ತಾಂತ್ರಿಕ ಮೌಲ್ಯಮಾಪನದ ಸ್ಥಳ ಭೇಟಿಯನ್ನು ಏರ್ಪಡಿಸಿ",
