    "As per agreement value": "ಒಪ್ಪಂದದ ಮೌಲ್ಯದ ಪ್ರಕಾರ",
    "As per conversion premium": "ಪರಿವರ್ತನಾ ಶುಲ್ಕದ ಪ್ರಕಾರ",
    "As per conversion rules": "ಪರಿವರ್ತನಾ ನಿಯಮಗಳ ಪ್ರಕಾರ",
    "Ask for the chain of previous title deeds (last 30 years is standard)": "ಹಿಂದಿನ ಹಕ್ಕುಪತ್ರಗಳ ಸರಪಳಿ ಕೇಳಿ (ಕೊನೆಯ 30 ವರ್ಷ ಸಾಮಾನ್ಯ)",
    "Ask for the sanctioned layout plan number": "ಮಂಜೂರಾದ ವಿನ್ಯಾಸ ನಕ್ಷೆಯ ಸಂಖ್ಯೆ ಕೇಳಿ",
    "Ask whether a rebate applies for a female buyer in your state": "ನಿಮ್ಮ ರಾಜ್ಯದಲ್ಲಿ ಮಹಿಳಾ ಖರೀದಿದಾರರಿಗೆ ರಿಯಾಯಿತಿ ಇದೆಯೇ ಎಂದು ಕೇಳಿ",
    "Attach the land record extract and title chain": "ಭೂ ದಾಖಲೆ ಉತಾರ ಮತ್ತು ಹಕ್ಕು ಸರಪಳಿಯನ್ನು ಲಗತ್ತಿಸಿ",
    "Authorisation when someone signs on another's behalf.": "ಬೇರೊಬ್ಬರ ಪರವಾಗಿ ಸಹಿ ಮಾಡುವಾಗ ಬೇಕಾದ ಅಧಿಕಾರ ಪತ್ರ.",
    "Authorise one director or officer to sign": "ಸಹಿ ಮಾಡಲು ಒಬ್ಬ ನಿರ್ದೇಶಕ ಅಥವಾ ಅಧಿಕಾರಿಗೆ ಅಧಿಕಾರ ನೀಡಿ",
    "Authorised bank / e-stamping counter": "ಅಧಿಕೃತ ಬ್ಯಾಂಕ್ / ಇ-ಸ್ಟಾಂಪಿಂಗ್ ಕೌಂಟರ್",
    "Automated checks narrow the field; a lawyer confirms the title.": "ಸ್ವಯಂಚಾಲಿತ ಪರಿಶೀಲನೆಗಳು ವ್ಯಾಪ್ತಿಯನ್ನು ಕಿರಿದಾಗಿಸುತ್ತವೆ; ಹಕ್ಕನ್ನು ವಕೀಲರು ಖಚಿತಪಡಿಸುತ್ತಾರೆ.",
    "Bank Legal & Technical Valuation": "ಬ್ಯಾಂಕ್ ಕಾನೂನು ಮತ್ತು ತಾಂತ್ರಿಕ ಮೌಲ್ಯಮಾಪನ",
    "BhumiGuide Intelligence home": "BhumiGuide Intelligence ಮುಖಪುಟ",
    "BhumiGuide Intelligence — Land Buying Procedure": "BhumiGuide Intelligence — ಭೂಮಿ ಖರೀದಿ ಕಾರ್ಯವಿಧಾನ",
    "Biometrics and photographs are captured at the office": "ಕಚೇರಿಯಲ್ಲಿ ಬಯೋಮೆಟ್ರಿಕ್ಸ್ ಮತ್ತು ಛಾಯಾಚಿತ್ರಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಲಾಗುತ್ತದೆ",
    "Both parties plus two witnesses must attend with original ID": "ಎರಡೂ ಪಕ್ಷಗಳು ಮತ್ತು ಇಬ್ಬರು ಸಾಕ್ಷಿಗಳು ಮೂಲ ಗುರುತಿನ ಚೀಟಿಯೊಂದಿಗೆ ಹಾಜರಾಗಬೇಕು",
    "Boundary disputes with neighbours are common. A fresh survey map settles what you are actually buying.": "ನೆರೆಹೊರೆಯವರೊಂದಿಗೆ ಗಡಿ ವಿವಾದಗಳು ಸಾಮಾನ್ಯ. ಹೊಸ ಸರ್ವೆ ನಕ್ಷೆ ನೀವು ನಿಜವಾಗಿ ಏನನ್ನು ಖರೀದಿಸುತ್ತಿದ್ದೀರಿ ಎಂಬುದನ್ನು ಸ್ಪಷ್ಟಪಡಿಸುತ್ತದೆ.",
    "Browse resources": "ಸಂಪನ್ಮೂಲಗಳನ್ನು ನೋಡಿ",
    "Browser notifications": "ಬ್ರೌಸರ್ ಅಧಿಸೂಚನೆಗಳು",
    "Build a house or shop": "ಮನೆ ಅಥವಾ ಅಂಗಡಿ ಕಟ್ಟುವುದು",
    "Building on agricultural land without conversion is unauthorised construction, and banks will refuse a loan on it.": "ಪರಿವರ್ತನೆ ಇಲ್ಲದೆ ಕೃಷಿ ಭೂಮಿಯಲ್ಲಿ ಕಟ್ಟಡ ಕಟ್ಟುವುದು ಅನಧಿಕೃತ ನಿರ್ಮಾಣ, ಮತ್ತು ಬ್ಯಾಂಕುಗಳು ಅದಕ್ಕೆ ಸಾಲ ನಿರಾಕರಿಸುತ್ತವೆ.",
