    "Guide": "ಮಾರ್ಗದರ್ಶಿ",
    "Hello, I am the BhumiGuide Assistant. Ask me anything about buying land — documents, procedure, charges or offices.": "ನಮಸ್ಕಾರ, ನಾನು BhumiGuide ಸಹಾಯಕ. ಭೂಮಿ ಖರೀದಿಯ ಬಗ್ಗೆ — ದಾಖಲೆಗಳು, ಕಾರ್ಯವಿಧಾನ, ಶುಲ್ಕ ಅಥವಾ ಕಚೇರಿಗಳು — ಏನನ್ನಾದರೂ ಕೇಳಿ.",
    "Hide": "ಮರೆಮಾಡಿ",
    "Hold as investment": "ಹೂಡಿಕೆಯಾಗಿ ಇಟ್ಟುಕೊಳ್ಳುವುದು",
    "Home": "ಮುಖಪುಟ",
    "How do I check land ownership online?": "ಭೂ ಮಾಲೀಕತ್ವವನ್ನು ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಹೇಗೆ ಪರಿಶೀಲಿಸುವುದು?",
    "How to read an EC and what a suspicious entry looks like.": "EC ಅನ್ನು ಹೇಗೆ ಓದುವುದು ಮತ್ತು ಅನುಮಾನಾಸ್ಪದ ನಮೂದು ಹೇಗಿರುತ್ತದೆ.",
    "How to verify land ownership online": "ಭೂ ಮಾಲೀಕತ್ವವನ್ನು ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಪರಿಶೀಲಿಸುವುದು ಹೇಗೆ",
    "I have this document": "ಈ ದಾಖಲೆ ನನ್ನ ಬಳಿ ಇದೆ",
    "Identity proof of buyer and seller.": "ಖರೀದಿದಾರ ಮತ್ತು ಮಾರಾಟಗಾರರ ಗುರುತಿನ ಪುರಾವೆ.",
    "If the seller is an agent, ask for a registered Power of Attorney": "ಮಾರಾಟಗಾರರು ಏಜೆಂಟ್ ಆಗಿದ್ದರೆ, ನೋಂದಾಯಿತ ಮುಖ್ತ್ಯಾರ್ ನಾಮೆ ಕೇಳಿ",
    "If the seller is not signing personally, the POA must be registered and still valid on the date of sale.": "ಮಾರಾಟಗಾರರು ಸ್ವತಃ ಸಹಿ ಮಾಡದಿದ್ದರೆ, ಮುಖ್ತ್ಯಾರ್ ನಾಮೆ ನೋಂದಾಯಿತವಾಗಿರಬೇಕು ಮತ್ತು ಮಾರಾಟದ ದಿನಾಂಕದಂದು ಚಾಲ್ತಿಯಲ್ಲಿರಬೇಕು.",
    "If the seller is not the recorded owner, every later step collapses. This is the cheapest step and the one that prevents the biggest losses.": "ಮಾರಾಟಗಾರರು ದಾಖಲೆಯಲ್ಲಿನ ಮಾಲೀಕರಲ್ಲದಿದ್ದರೆ, ಮುಂದಿನ ಪ್ರತಿ ಹಂತವೂ ಕುಸಿಯುತ್ತದೆ. ಇದು ಅತಿ ಕಡಿಮೆ ಖರ್ಚಿನ ಹಂತ, ಆದರೆ ಅತಿ ದೊಡ್ಡ ನಷ್ಟವನ್ನು ತಡೆಯುವ ಹಂತ.",
    "If the seller never completed mutation after their own purchase, their record is incomplete.": "ಮಾರಾಟಗಾರರು ತಮ್ಮ ಖರೀದಿಯ ನಂತರ ಖಾತಾ ಬದಲಾವಣೆ ಮಾಡಿಸದಿದ್ದರೆ, ಅವರ ದಾಖಲೆ ಅಪೂರ್ಣವಾಗಿರುತ್ತದೆ.",
    "Individual": "ವೈಯಕ್ತಿಕ",
    "Inheritance status unconfirmed — check it": "ಪಿತ್ರಾರ್ಜಿತ ಸ್ಥಿತಿ ಖಚಿತವಾಗಿಲ್ಲ — ಪರಿಶೀಲಿಸಿ",
    "Inherited land needs every legal heir on record.": "ಪಿತ್ರಾರ್ಜಿತ ಭೂಮಿಗೆ ಪ್ರತಿಯೊಬ್ಬ ಕಾನೂನುಬದ್ಧ ವಾರಸುದಾರರ ಹೆಸರೂ ದಾಖಲೆಯಲ್ಲಿ ಇರಬೇಕು.",
    "Instant alerts while the site is open": "ಸೈಟ್ ತೆರೆದಿರುವಾಗ ತಕ್ಷಣದ ಎಚ್ಚರಿಕೆಗಳು",
    "Instant answers, any time": "ಯಾವಾಗ ಬೇಕಾದರೂ ತಕ್ಷಣದ ಉತ್ತರಗಳು",
    "Interactive": "ಸಂವಾದಾತ್ಮಕ",
    "Is it jointly owned by more than one person?": "ಇದು ಒಬ್ಬರಿಗಿಂತ ಹೆಚ್ಚು ಜನರ ಜಂಟಿ ಮಾಲೀಕತ್ವದಲ್ಲಿದೆಯೇ?",
