    "Without it, any construction is unauthorised and no bank will fund the purchase.": "ಅದಿಲ್ಲದೆ ಯಾವುದೇ ನಿರ್ಮಾಣ ಅನಧಿಕೃತ, ಮತ್ತು ಯಾವ ಬ್ಯಾಂಕೂ ಖರೀದಿಗೆ ಹಣ ನೀಡುವುದಿಲ್ಲ.",
