    "7 – 21 days": "7 – 21 દિવસ",
    "A 12-digit identity number issued by UIDAI, used for identity and address verification at the registration office.": "UIDAI દ્વારા જારી કરાયેલ 12 અંકનો ઓળખ નંબર, જે નોંધણી કચેરીમાં ઓળખ અને સરનામાની ચકાસણી માટે વપરાય છે.",
    "A broken chain is the classic sign of a disputed title. Ask for at least 30 years of history.": "તૂટેલી શૃંખલા વિવાદિત માલિકી હકનું જાણીતું લક્ષણ છે. ઓછામાં ઓછા 30 વર્ષનો ઇતિહાસ માગો.",
    "A certificate listing every registered transaction on the property during a chosen period.": "પસંદ કરેલા સમયગાળા દરમિયાન મિલકત પર થયેલા દરેક નોંધાયેલા વ્યવહારની યાદી આપતું પ્રમાણપત્ર.",
    "A certificate naming the legal heirs of a deceased owner.": "મૃત માલિકના કાયદેસર વારસદારોનાં નામ જણાવતું પ્રમાણપત્ર.",
    "A company buyer needs documented internal approval.": "કંપની ખરીદનાર હોય તો લેખિત આંતરિક મંજૂરી જરૂરી છે.",
    "A deed missing one co-owner's signature transfers only that seller's share, not the whole property.": "એક સહમાલિકની સહી વગરનો દસ્તાવેજ ફક્ત તે વેચનારનો હિસ્સો જ તબદીલ કરે છે, આખી મિલકત નહીં.",
    "A measured plan of the plot issued by the survey department, showing boundaries and area.": "સર્વે વિભાગ દ્વારા જારી કરાયેલ પ્લોટનો માપ સાથેનો નકશો, જેમાં હદ અને ક્ષેત્રફળ દર્શાવેલાં હોય છે.",
    "A printable checklist you can carry to the office.": "કચેરીએ સાથે લઈ જઈ શકાય એવી પ્રિન્ટ કરવા યોગ્ય ચેકલિસ્ટ.",
    "A registered document authorising a named person to act for the owner.": "માલિક વતી કામ કરવા માટે નામ દર્શાવેલ વ્યક્તિને અધિકાર આપતો નોંધાયેલ દસ્તાવેજ.",
    "A sale signed by one heir alone can be challenged by the others years later. This is the single most common source of land litigation.": "એકલા એક વારસદારે કરેલું વેચાણ વર્ષો પછી બીજા વારસદારો પડકારી શકે છે. જમીનના મુકદ્દમાનું આ સૌથી સામાન્ય કારણ છે.",
    "A written confirmation from a society, planning authority or department that they do not object to the transfer.": "સોસાયટી, આયોજન સત્તામંડળ કે વિભાગ તરફથી લેખિત પુષ્ટિ કે તેમને તબદીલી સામે કોઈ વાંધો નથી.",
