    "If the seller is not signing personally, the POA must be registered and still valid on the date of sale.": "જો વેચનાર જાતે સહી ન કરતા હોય, તો POA નોંધાયેલ હોવો જોઈએ અને વેચાણની તારીખે માન્ય હોવો જોઈએ.",
    "If the seller is not the recorded owner, every later step collapses. This is the cheapest step and the one that prevents the biggest losses.": "જો વેચનાર રેકોર્ડ પરના માલિક ન હોય, તો પછીનું દરેક પગલું નકામું બને છે. આ સૌથી સસ્તું પગલું છે અને સૌથી મોટું નુકસાન એ જ અટકાવે છે.",
    "If the seller never completed mutation after their own purchase, their record is incomplete.": "જો વેચનારે પોતાની ખરીદી પછી નોંધ (મ્યુટેશન) પૂરી ન કરાવી હોય, તો તેમનો રેકોર્ડ અધૂરો છે.",
