    "A sale signed by one heir alone can be challenged by the others years later. This is the single most common source of land litigation.": "একজন উত্তরাধিকারী একা সই করে বিক্রি করলে বাকিরা বহু বছর পরেও তা চ্যালেঞ্জ করতে পারেন। জমি নিয়ে মামলার সবচেয়ে সাধারণ কারণ এটিই।",
