    "Registration is what transfers legal title. An unregistered sale deed does not give you ownership, whatever the seller says.": "রেজিস্ট্রেশনই আইনি স্বত্ব হস্তান্তর করে। বিক্রেতা যা-ই বলুন, অরেজিস্টার্ড বিক্রয় দলিল আপনাকে মালিকানা দেয় না।",
    "Registration transfers title; mutation updates the government's revenue record. Until mutation is done, tax bills and future sales stay in the seller's name.": "রেজিস্ট্রেশন স্বত্ব হস্তান্তর করে; মিউটেশন সরকারি রাজস্ব রেকর্ড হালনাগাদ করে। মিউটেশন না হওয়া পর্যন্ত করের বিল ও পরবর্তী বিক্রি বিক্রেতার নামেই থেকে যায়।",
