    "The Collector's order permitting the land to be used for residential, commercial or industrial purposes.": "আবাসিক, বাণিজ্যিক বা শিল্প কাজে জমি ব্যবহারের অনুমতি দেওয়া কালেক্টরের আদেশ।",
    "The Sub-Registrar captures biometrics against Aadhaar at registration. Both buyer and seller need it.": "রেজিস্ট্রেশনের সময় সাব-রেজিস্ট্রার Aadhaar-এর সঙ্গে মিলিয়ে বায়োমেট্রিক নেন। ক্রেতা ও বিক্রেতা দুজনেরই লাগে।",
    "The Sub-Registrar will ask who is authorised to sign for the company. Without a board resolution, registration stops at the counter.": "সাব-রেজিস্ট্রার জানতে চাইবেন কোম্পানির হয়ে সই করার ক্ষমতা কার। বোর্ড রেজোলিউশন ছাড়া কাউন্টারেই রেজিস্ট্রেশন আটকে যায়।",
    "The account maintained by the local body that links the property to its tax record.": "স্থানীয় সংস্থার রাখা হিসাব, যা সম্পত্তিকে তার কর রেকর্ডের সঙ্গে যুক্ত করে।",
    "The agreement fixes the price and the deadline, and records the advance you paid. Without it, an advance is very hard to recover.": "চুক্তিপত্র দাম ও সময়সীমা নির্দিষ্ট করে এবং আপনার দেওয়া অগ্রিম লিপিবদ্ধ করে। এটি না থাকলে অগ্রিম ফেরত পাওয়া খুবই কঠিন।",
    "The bank's legal opinion is a free second review of your title. If the bank refuses the property, treat that as a serious warning.": "ব্যাঙ্কের আইনি মতামত আপনার স্বত্বের একটি বিনামূল্যের দ্বিতীয় পর্যালোচনা। ব্যাঙ্ক সম্পত্তিটি বাতিল করলে সেটিকে গুরুতর সতর্কবার্তা হিসেবে নিন।",
    "The circle / ready reckoner rate for that exact survey number": "ঠিক সেই সার্ভে নম্বরের সার্কেল / রেডি রেকনার রেট",
    "The core legal document that records the transfer of ownership from seller to buyer.": "বিক্রেতা থেকে ক্রেতার কাছে মালিকানা হস্তান্তরের মূল আইনি দলিল।",
    "The extract shows the current holder, the land area, tenure type and any loan or court entry noted in the 'other rights' column.": "নকলে বর্তমান দখলদার, জমির আয়তন, স্বত্বের ধরন এবং 'অন্যান্য অধিকার' কলামে লেখা যেকোনও ঋণ বা আদালতের এন্ট্রি দেখা যায়।",
    "The mutation entry showing when the current holder's name was added to the revenue record.": "বর্তমান দখলদারের নাম কবে রাজস্ব রেকর্ডে যুক্ত হয়েছে তা দেখানো মিউটেশন এন্ট্রি।",
    "The receipt from the local body showing property tax has been paid up to date.": "সম্পত্তি কর হালনাগাদ মেটানো হয়েছে দেখিয়ে স্থানীয় সংস্থার দেওয়া রসিদ।",
    "The registered deed transferring ownership.": "মালিকানা হস্তান্তরকারী রেজিস্টার্ড দলিল।",
    "The registration form records the present address of both parties.": "রেজিস্ট্রেশন ফর্মে দুই পক্ষের বর্তমান ঠিকানা লেখা থাকে।",
    "The set of earlier registered deeds showing how the property moved from owner to owner.": "সম্পত্তি এক মালিক থেকে আর এক মালিকের কাছে কীভাবে গেছে তা দেখানো আগের রেজিস্টার্ড দলিলগুলির সেট।",
    "The state revenue record showing the current holder, area, tenure and any registered charge on the land.": "রাজ্যের রাজস্ব রেকর্ড, যাতে বর্তমান দখলদার, আয়তন, স্বত্ব এবং জমির উপর নথিভুক্ত যেকোনও দায় থাকে।",
    "The tax identification number issued by the Income Tax Department.": "আয়কর দপ্তরের দেওয়া কর শনাক্তকরণ নম্বর।",
    "The whole process end to end, written for a first-time buyer.": "প্রথমবারের ক্রেতার জন্য লেখা, শুরু থেকে শেষ পর্যন্ত পুরো প্রক্রিয়া।",
    "This is the document that actually makes you the owner. Everything else supports it.": "এই দলিলই আপনাকে আসলে মালিক বানায়। বাকি সবকিছু এর সহায়ক।",
    "This is the government's own statement of who holds the land. It should be dated within the last 3 months.": "জমি কার দখলে, তা নিয়ে সরকারের নিজস্ব বিবৃতি এটি। তারিখ শেষ 3 মাসের মধ্যে হওয়া উচিত।",
    "Tool": "টুল",
    "Track the objection period — usually 15 to 30 days": "আপত্তির সময়সীমার দিকে নজর রাখুন — সাধারণত 15 থেকে 30 দিন",
    "Two-factor authentication": "দুই-স্তরের প্রমাণীকরণ",
    "UIDAI portal or any Aadhaar Seva Kendra": "UIDAI পোর্টাল বা যেকোনও Aadhaar সেবা কেন্দ্র",
    "Unapproved layouts cannot get building permission or a water and power connection, and resale value stays low.": "অনুমোদনহীন লেআউটে নির্মাণের অনুমতি বা জল ও বিদ্যুতের সংযোগ মেলে না, আর পুনর্বিক্রয় মূল্যও কম থাকে।",
    "Understanding the encumbrance certificate": "এনকাম্ব্রেন্স সার্টিফিকেট বোঝা",
    "Unmark": "চিহ্ন সরান",
