    "A 12-digit identity number issued by UIDAI, used for identity and address verification at the registration office.": "UIDAI ਵੱਲੋਂ ਜਾਰੀ 12 ਅੰਕਾਂ ਦਾ ਪਛਾਣ ਨੰਬਰ, ਜੋ ਰਜਿਸਟਰੀ ਦਫ਼ਤਰ ਵਿੱਚ ਪਛਾਣ ਅਤੇ ਪਤੇ ਦੀ ਤਸਦੀਕ ਲਈ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ।",
    "A broken chain is the classic sign of a disputed title. Ask for at least 30 years of history.": "ਟੁੱਟੀ ਹੋਈ ਲੜੀ ਵਿਵਾਦਿਤ ਮਾਲਕੀ ਦੀ ਪੱਕੀ ਨਿਸ਼ਾਨੀ ਹੈ। ਘੱਟੋ-ਘੱਟ 30 ਸਾਲਾਂ ਦਾ ਇਤਿਹਾਸ ਮੰਗੋ।",
    "A certificate listing every registered transaction on the property during a chosen period.": "ਚੁਣੇ ਹੋਏ ਸਮੇਂ ਦੌਰਾਨ ਜਾਇਦਾਦ 'ਤੇ ਹੋਏ ਹਰ ਰਜਿਸਟਰਡ ਲੈਣ-ਦੇਣ ਦੀ ਸੂਚੀ ਦੇਣ ਵਾਲਾ ਸਰਟੀਫਿਕੇਟ।",
    "A certificate naming the legal heirs of a deceased owner.": "ਮਰ ਚੁੱਕੇ ਮਾਲਕ ਦੇ ਕਾਨੂੰਨੀ ਵਾਰਸਾਂ ਦੇ ਨਾਂ ਦੱਸਣ ਵਾਲਾ ਸਰਟੀਫਿਕੇਟ।",
    "A company buyer needs documented internal approval.": "ਕੰਪਨੀ ਖਰੀਦਦਾਰ ਲਈ ਲਿਖਤੀ ਅੰਦਰੂਨੀ ਮਨਜ਼ੂਰੀ ਜ਼ਰੂਰੀ ਹੈ।",
    "A deed missing one co-owner's signature transfers only that seller's share, not the whole property.": "ਜਿਸ ਦਸਤਾਵੇਜ਼ 'ਤੇ ਕਿਸੇ ਇੱਕ ਸਹਿ-ਮਾਲਕ ਦੇ ਦਸਤਖ਼ਤ ਨਾ ਹੋਣ, ਉਹ ਸਿਰਫ਼ ਉਸ ਵੇਚਣ ਵਾਲੇ ਦਾ ਹਿੱਸਾ ਤਬਦੀਲ ਕਰਦਾ ਹੈ, ਪੂਰੀ ਜਾਇਦਾਦ ਨਹੀਂ।",
    "A measured plan of the plot issued by the survey department, showing boundaries and area.": "ਮਾਲ ਮਹਿਕਮੇ ਦੇ ਸਰਵੇ ਵਿਭਾਗ ਵੱਲੋਂ ਜਾਰੀ ਪਲਾਟ ਦਾ ਮਿਣਿਆ ਹੋਇਆ ਨਕਸ਼ਾ, ਜਿਸ ਵਿੱਚ ਹੱਦਾਂ ਤੇ ਰਕਬਾ ਦਿਖਾਇਆ ਹੁੰਦਾ ਹੈ।",
    "A printable checklist you can carry to the office.": "ਛਪਵਾਉਣ ਯੋਗ ਸੂਚੀ, ਜੋ ਤੁਸੀਂ ਦਫ਼ਤਰ ਨਾਲ ਲੈ ਜਾ ਸਕਦੇ ਹੋ।",
    "A registered document authorising a named person to act for the owner.": "ਰਜਿਸਟਰਡ ਦਸਤਾਵੇਜ਼ ਜੋ ਕਿਸੇ ਨਾਮਜ਼ਦ ਵਿਅਕਤੀ ਨੂੰ ਮਾਲਕ ਵੱਲੋਂ ਕੰਮ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਦਿੰਦਾ ਹੈ।",
    "A sale signed by one heir alone can be challenged by the others years later. This is the single most common source of land litigation.": "ਇੱਕ ਹੀ ਵਾਰਸ ਦੇ ਦਸਤਖ਼ਤਾਂ ਨਾਲ ਕੀਤੀ ਵਿਕਰੀ ਨੂੰ ਬਾਕੀ ਵਾਰਸ ਸਾਲਾਂ ਬਾਅਦ ਵੀ ਚੁਣੌਤੀ ਦੇ ਸਕਦੇ ਹਨ। ਜ਼ਮੀਨੀ ਮੁਕੱਦਮਿਆਂ ਦਾ ਇਹੀ ਸਭ ਤੋਂ ਆਮ ਕਾਰਨ ਹੈ।",
