    "If the seller is not the recorded owner, every later step collapses. This is the cheapest step and the one that prevents the biggest losses.": "ਜੇ ਵੇਚਣ ਵਾਲਾ ਰਿਕਾਰਡ ਵਿੱਚ ਦਰਜ ਮਾਲਕ ਨਹੀਂ, ਤਾਂ ਅੱਗੇ ਦੇ ਸਾਰੇ ਕਦਮ ਬੇਕਾਰ ਹੋ ਜਾਂਦੇ ਹਨ। ਇਹ ਸਭ ਤੋਂ ਸਸਤਾ ਕਦਮ ਹੈ ਤੇ ਸਭ ਤੋਂ ਵੱਡੇ ਨੁਕਸਾਨ ਰੋਕਦਾ ਹੈ।",
