    "Registration fee": "ਰਜਿਸਟਰੀ ਫ਼ੀਸ",
    "Registration fee as per state": "ਰਾਜ ਅਨੁਸਾਰ ਰਜਿਸਟਰੀ ਫ਼ੀਸ",
    "Registration is what transfers legal title. An unregistered sale deed does not give you ownership, whatever the seller says.": "ਕਾਨੂੰਨੀ ਮਾਲਕੀ ਰਜਿਸਟਰੀ ਨਾਲ ਹੀ ਤਬਦੀਲ ਹੁੰਦੀ ਹੈ। ਬਿਨਾਂ ਰਜਿਸਟਰੀ ਵਾਲਾ ਵਿਕਰੀ ਨਾਮਾ ਤੁਹਾਨੂੰ ਮਾਲਕੀ ਨਹੀਂ ਦਿੰਦਾ, ਵੇਚਣ ਵਾਲਾ ਭਾਵੇਂ ਕੁਝ ਵੀ ਕਹੇ।",
    "Registration transfers title; mutation updates the government's revenue record. Until mutation is done, tax bills and future sales stay in the seller's name.": "ਰਜਿਸਟਰੀ ਮਾਲਕੀ ਤਬਦੀਲ ਕਰਦੀ ਹੈ; ਇੰਤਕਾਲ ਸਰਕਾਰ ਦੇ ਮਾਲ ਰਿਕਾਰਡ ਨੂੰ ਅੱਪਡੇਟ ਕਰਦਾ ਹੈ। ਜਦੋਂ ਤੱਕ ਇੰਤਕਾਲ ਨਹੀਂ ਹੁੰਦਾ, ਟੈਕਸ ਬਿੱਲ ਤੇ ਅਗਲੀਆਂ ਵਿਕਰੀਆਂ ਵੇਚਣ ਵਾਲੇ ਦੇ ਨਾਂ ਹੀ ਰਹਿੰਦੀਆਂ ਹਨ।",
    "Remaining": "ਬਾਕੀ",
    "Report": "ਰਿਪੋਰਟ",
    "Required in states like Karnataka for tax payment, building permission and loan approval.": "ਕਰਨਾਟਕ ਵਰਗੇ ਰਾਜਾਂ ਵਿੱਚ ਟੈਕਸ ਅਦਾਇਗੀ, ਉਸਾਰੀ ਦੀ ਮਨਜ਼ੂਰੀ ਤੇ ਕਰਜ਼ਾ ਮਨਜ਼ੂਰੀ ਲਈ ਲੋੜੀਂਦਾ।",
