    "No Madhya Pradesh source uses a municipal khata. MP's records are the Khasra, the Khatauni and the Adhikar Abhilekh — the Khasra is a land record, not a municipal property account like Karnataka's khata.": "मध्य प्रदेश का कोई स्रोत नगरपालिका खाते का उपयोग नहीं करता। MP के अभिलेख हैं खसरा, खतौनी और Adhikar Abhilekh — खसरा एक भू-अभिलेख है, कर्नाटक के खाते जैसा नगरपालिका संपत्ति खाता नहीं।",
    "No contact is listed for {0} — showing all {1} contacts across {2} district instead, each with its own taluka.": "{0} के लिए कोई संपर्क दर्ज नहीं है — इसके बजाय {2} ज़िले भर के सभी {1} संपर्क दिखाए जा रहे हैं, हर एक अपने तालुका के साथ।",
    "No contacts are on file for {0}, {1} yet. This list only covers the areas the project owner has collected so far — it is not a complete directory.": "{1} के {0} के लिए अभी कोई संपर्क दर्ज नहीं है। यह सूची केवल उन क्षेत्रों को शामिल करती है जिन्हें प्रोजेक्ट स्वामी ने अब तक एकत्र किया है — यह पूरी निर्देशिका नहीं है।",
    "Not on the registration checklist, but BBMP requires a Form 15 encumbrance certificate for khata transfer after the sale — so you will need one anyway.": "रजिस्ट्रेशन की चेकलिस्ट में नहीं है, लेकिन बिक्री के बाद खाता हस्तांतरण के लिए BBMP Form 15 भार प्रमाणपत्र मांगता है — इसलिए यह आपको लेना ही पड़ेगा।",
    "Not on the registration checklist, which asks instead for the assessment register extract. BBMP does require the current year's tax paid receipt for khata transfer.": "रजिस्ट्रेशन की चेकलिस्ट में नहीं है; उसमें इसके बजाय कर-निर्धारण पंजी का उद्धरण मांगा जाता है। खाता हस्तांतरण के लिए BBMP चालू वर्ष की कर-भुगतान रसीद अवश्य मांगता है।",
    "PTCL NOC / Permission Order": "PTCL NOC / अनुमति आदेश",
    "Policies": "नीतियाँ",
