    "RERA Madhya Pradesh": "RERA मध्य प्रदेश",
    "RTC (Record of Rights)": "RTC (अधिकार अभिलेख)",
    "RTC / Pahani": "RTC / पहाणी",
    "Registration charges": "रजिस्ट्रेशन शुल्क",
    "Required documents": "ज़रूरी दस्तावेज़",
    "Required for converted land in all three non-agricultural categories, alongside the khata and assessment extract.": "तीनों गैर-कृषि श्रेणियों में परिवर्तित भूमि के लिए, खाता और कर-निर्धारण उद्धरण के साथ यह आवश्यक है।",
    "Required for every non-agricultural property. Gram panchayat property needs the khata plus Form 9 and 11A (or computerised 11B); municipal property needs the khata and assessment register extract; BBMP property needs A-Khata and the assessment extract.": "हर गैर-कृषि संपत्ति के लिए आवश्यक। ग्राम पंचायत की संपत्ति के लिए खाता तथा Form 9 और 11A (या कंप्यूटरीकृत 11B) चाहिए; नगरपालिका संपत्ति के लिए खाता और कर-निर्धारण पंजी का उद्धरण; BBMP संपत्ति के लिए A-खाता और कर-निर्धारण उद्धरण।",
    "Required for transfers of agricultural land, under s.131(c) of the Karnataka Land Revenue Act and Rule 46H of the Karnataka Land Revenue Rules.": "कृषि भूमि के हस्तांतरण के लिए, Karnataka Land Revenue Act की s.131(c) और Karnataka Land Revenue Rules के Rule 46H के अंतर्गत आवश्यक।",
    "Revenue Department (Kandaya), Karnataka": "राजस्व विभाग (कंदाय), कर्नाटक",
    "Revenue Department, Madhya Pradesh": "राजस्व विभाग, मध्य प्रदेश",
    "Revenue Department, Maharashtra": "राजस्व विभाग, महाराष्ट्र",
    "Run the legal checks before you release payment.": "भुगतान करने से पहले कानूनी जाँच पूरी करें।",
    "Search your location": "अपनी जगह खोजें",
    "See the steps, documents, offices and charges that apply to you.": "आप पर लागू होने वाले चरण, दस्तावेज़, कार्यालय और शुल्क देखें।",
    "Stamp duty and registration fee estimated for your state.": "आपके राज्य के लिए स्टांप ड्यूटी और रजिस्ट्रेशन शुल्क का अनुमान।",
    "States covered": "शामिल राज्य",
    "Step-by-step guidance": "चरण-दर-चरण मार्गदर्शन",
    "Survey No. {0} in {1}, {2} passed the automated checks. This is a prototype result — a real verification also needs a lawyer's title opinion.": "{2} के {1} में सर्वे नं. {0} स्वचालित जाँचों में उत्तीर्ण हुआ। यह एक प्रोटोटाइप परिणाम है — वास्तविक सत्यापन के लिए वकील की टाइटल राय भी आवश्यक है।",
    "Survey Sketch (Form 11E)": "सर्वे स्केच (Form 11E)",
    "Taluk Office": "तालुक कार्यालय",
    "Talukas": "तहसीलें",
    "Tehsil Office": "तहसील कार्यालय",
    "Tehsildar Office": "तहसीलदार कार्यालय",
    "Thanks {0} — we will reply to {1} within two working days.": "धन्यवाद {0} — हम दो कार्य दिवसों के भीतर {1} पर उत्तर देंगे।",
    "The full land buying procedure for your district, in order.": "आपके ज़िले के लिए ज़मीन खरीदने की पूरी प्रक्रिया, क्रम से।",
    "The official checklist requires PAN, or a declaration in Form 60 or 61, for sale transactions of Rs. 5 lakh and above.": "आधिकारिक चेकलिस्ट के अनुसार 5 लाख रुपये और उससे अधिक की बिक्री लेन-देन के लिए PAN, या Form 60 अथवा 61 में घोषणा आवश्यक है।",
    "The official checklist requires a copy of the RTC issued within the last 15 days, for transfers of agricultural land.": "आधिकारिक चेकलिस्ट के अनुसार कृषि भूमि के हस्तांतरण के लिए पिछले 15 दिनों में जारी RTC की प्रति आवश्यक है।",
    "The official checklist requires title deeds, the allotment letter or a possession certificate where the property was granted by the Government or one of its departments.": "जहाँ संपत्ति सरकार या उसके किसी विभाग द्वारा प्रदान की गई हो, वहाँ आधिकारिक चेकलिस्ट के अनुसार टाइटल डीड, आवंटन पत्र या कब्ज़ा प्रमाणपत्र आवश्यक है।",
    "Under the Maharashtra Land Revenue Code s.44 the Collector grants permission and issues a sanad. Later amendments (s.42B/42C/42D) created deemed non-agricultural status in several situations, so a separate order is not always needed.": "Maharashtra Land Revenue Code की s.44 के अंतर्गत कलेक्टर अनुमति देता है और सनद जारी करता है। बाद के संशोधनों (s.42B/42C/42D) ने कई स्थितियों में मानित गैर-कृषि दर्जा दे दिया है, इसलिए अलग आदेश हमेशा आवश्यक नहीं होता।",
    "What each document is, why it is needed and where to get it.": "हर दस्तावेज़ क्या है, वह क्यों ज़रूरी है और कहाँ से मिलेगा।",
    "Where a power of attorney is used, the IGR Citizen's Charter requires the original POA for verification, a certified copy for the record, and a declaration in the prescribed form that the POA still subsists.": "जहाँ मुख्तारनामा उपयोग होता है, वहाँ IGR Citizen's Charter के अनुसार सत्यापन के लिए मूल POA, अभिलेख के लिए प्रमाणित प्रति, और निर्धारित प्रपत्र में यह घोषणा आवश्यक है कि POA अब भी प्रभावी है।",
    "and is issued by the": "और इसे जारी करता है",
    "contacts across": "संपर्क, पूरे",
    "district instead, each with its own taluka.": "के बजाय ज़िला, और हर ज़िले की अपनी तहसील होती है।",
