    "passed the automated checks. This is a prototype result — a real verification also needs a lawyer's title opinion.": "अपने आप होने वाली जाँच में पास हो गया। यह प्रोटोटाइप का नतीजा है — असली पुष्टि के लिए वकील की मालिकाना हक पर राय भी ज़रूरी है।",
