    "Agricultural land concession {0}%": "शेतजमीन सवलत {0}%",
    "Ask a question in plain language and get a district-aware answer.": "सोप्या भाषेत प्रश्न विचारा आणि तुमच्या जिल्ह्यानुसार उत्तर मिळवा.",
    "Back": "मागे",
