    "Required documents": "आवश्यक कागदपत्रे",
    "Required for converted land in all three non-agricultural categories, alongside the khata and assessment extract.": "तिन्ही अकृषिक प्रवर्गांतील रूपांतरित जमिनीसाठी, खाता व आकारणी उताऱ्यासोबत हे आवश्यक आहे.",
    "Required for every non-agricultural property. Gram panchayat property needs the khata plus Form 9 and 11A (or computerised 11B); municipal property needs the khata and assessment register extract; BBMP property needs A-Khata and the assessment extract.": "प्रत्येक अकृषिक मालमत्तेसाठी आवश्यक. ग्राम पंचायतीच्या मालमत्तेसाठी खाता आणि Form 9 व 11A (किंवा संगणकीकृत 11B) लागते; नगरपालिका मालमत्तेसाठी खाता व आकारणी नोंदवहीचा उतारा; BBMP मालमत्तेसाठी A-खाता व आकारणी उतारा लागतो.",
    "Required for transfers of agricultural land, under s.131(c) of the Karnataka Land Revenue Act and Rule 46H of the Karnataka Land Revenue Rules.": "शेतजमिनीच्या हस्तांतरणासाठी, Karnataka Land Revenue Act च्या s.131(c) आणि Karnataka Land Revenue Rules च्या Rule 46H अंतर्गत आवश्यक.",
    "Revenue Department (Kandaya), Karnataka": "महसूल विभाग (कंदाय), कर्नाटक",
