    "Run the legal checks before you release payment.": "पैसे देण्यापूर्वी कायदेशीर तपासण्या पूर्ण करा.",
    "Search your location": "तुमचे ठिकाण शोधा",
    "See the steps, documents, offices and charges that apply to you.": "तुम्हाला लागू होणाऱ्या पायऱ्या, कागदपत्रे, कार्यालये व शुल्क पाहा.",
    "Stamp duty and registration fee estimated for your state.": "तुमच्या राज्यासाठी मुद्रांक शुल्क व नोंदणी शुल्काचा अंदाज.",
