    "Survey No. {0} in {1}, {2} passed the automated checks. This is a prototype result — a real verification also needs a lawyer's title opinion.": "{2} मधील {1} येथील सर्व्हे नं. {0} स्वयंचलित तपासण्यांमध्ये उत्तीर्ण झाला. हा प्रोटोटाइप निकाल आहे — खऱ्या पडताळणीसाठी वकिलाचे टायटल मत देखील आवश्यक असते.",
    "Survey Sketch (Form 11E)": "सर्व्हे स्केच (Form 11E)",
