    "Thanks {0} — we will reply to {1} within two working days.": "धन्यवाद {0} — आम्ही दोन कामकाजाच्या दिवसांत {1} वर उत्तर देऊ.",
    "The full land buying procedure for your district, in order.": "तुमच्या जिल्ह्यासाठी जमीन खरेदीची संपूर्ण प्रक्रिया, क्रमाने.",
    "The official checklist requires PAN, or a declaration in Form 60 or 61, for sale transactions of Rs. 5 lakh and above.": "अधिकृत चेकलिस्टनुसार 5 लाख रुपये व त्याहून अधिक रकमेच्या विक्री व्यवहारांसाठी PAN, किंवा Form 60 अथवा 61 मधील घोषणापत्र आवश्यक आहे.",
    "The official checklist requires a copy of the RTC issued within the last 15 days, for transfers of agricultural land.": "अधिकृत चेकलिस्टनुसार शेतजमिनीच्या हस्तांतरणासाठी गेल्या 15 दिवसांत दिलेल्या RTC ची प्रत आवश्यक आहे.",
    "The official checklist requires title deeds, the allotment letter or a possession certificate where the property was granted by the Government or one of its departments.": "जिथे मालमत्ता शासनाने किंवा त्याच्या कोणत्याही विभागाने दिली आहे, तिथे अधिकृत चेकलिस्टनुसार मालकी हक्काचे दस्तऐवज, वाटप पत्र किंवा ताबा प्रमाणपत्र आवश्यक आहे.",
    "Under the Maharashtra Land Revenue Code s.44 the Collector grants permission and issues a sanad. Later amendments (s.42B/42C/42D) created deemed non-agricultural status in several situations, so a separate order is not always needed.": "Maharashtra Land Revenue Code च्या s.44 अंतर्गत जिल्हाधिकारी परवानगी देतात आणि सनद देतात. नंतरच्या सुधारणांनी (s.42B/42C/42D) अनेक परिस्थितींत अभिप्रेत अकृषिक दर्जा निर्माण केला आहे, त्यामुळे स्वतंत्र आदेश नेहमी लागत नाही.",
    "What each document is, why it is needed and where to get it.": "प्रत्येक कागदपत्र काय आहे, ते का लागते व कुठे मिळते.",
    "Where a power of attorney is used, the IGR Citizen's Charter requires the original POA for verification, a certified copy for the record, and a declaration in the prescribed form that the POA still subsists.": "जिथे कुलमुखत्यारपत्र वापरले जाते, तिथे IGR Citizen's Charter नुसार पडताळणीसाठी मूळ POA, अभिलेखासाठी प्रमाणित प्रत, आणि POA अद्याप अस्तित्वात आहे असे विहित नमुन्यातील घोषणापत्र आवश्यक आहे.",
    "and is issued by the": "आणि ते जारी करते",
    "contacts across": "संपर्क, संपूर्ण",
    "district instead, each with its own taluka.": "ऐवजी जिल्हा, आणि प्रत्येक जिल्ह्याचा स्वतःचा तालुका असतो.",
