    "For agricultural transfers: an NOC or permission order under s.6 of the Karnataka Scheduled Castes and Scheduled Tribes (Prohibition of Transfer of Certain Lands) Act 1978. A declaration under s.81A of the Karnataka Land Reforms Act 1961 is required alongside it.": "விவசாய நில மாற்றங்களுக்கு: Karnataka Scheduled Castes and Scheduled Tribes (Prohibition of Transfer of Certain Lands) Act 1978 இன் s.6 இன் கீழ் NOC அல்லது அனுமதி ஆணை. இதனுடன் Karnataka Land Reforms Act 1961 இன் s.81A இன் கீழ் ஒரு பிரகடனமும் தேவை.",
    "Four steps from \"I have no idea where to start\" to a checked, documented purchase.": "\"எங்கிருந்து தொடங்குவது என்றே தெரியவில்லை\" என்ற நிலையிலிருந்து சரிபார்க்கப்பட்ட, ஆவணப்படுத்தப்பட்ட வாங்குதல் வரை — நான்கு படிகள்.",
