    "of {0} steps done": "/ {0} படிகள் முடிந்தன",
    "passed the automated checks. This is a prototype result — a real verification also needs a lawyer's title opinion.": "தானியங்கிச் சரிபார்ப்புகளில் தேர்ச்சி பெற்றது. இது ஒரு மாதிரி முடிவு — உண்மையான சரிபார்ப்புக்கு வழக்கறிஞரின் உரிமை பற்றிய கருத்தும் தேவை.",
    "showing all": "காட்டப்படுகிறது: அனைத்து",
