    "this record is called the": "இந்தப் பதிவேட்டின் பெயர்",
    "we will reply to": "நாங்கள் பதில் அளிப்போம்",
    "within two working days.": "இரு வேலை நாட்களுக்குள்.",
    "yet. This list only covers the areas the project owner has collected so far — it is not a complete directory.": "இன்னும் இல்லை. இந்தப் பட்டியல் திட்ட உரிமையாளர் இதுவரை சேர்த்த பகுதிகளை மட்டுமே கொண்டது — இது முழுமையான விவரப் பட்டியல் அல்ல.",
    "{0} contact listed in {1}, {2}.": "{1}, {2} இல் {0} தொடர்பு பட்டியலிடப்பட்டுள்ளது.",
    "{0} contacts listed in {1}, {2}.": "{1}, {2} இல் {0} தொடர்புகள் பட்டியலிடப்பட்டுள்ளன.",
    "{0} — base stamp duty in {1} is {2}%, you are being charged {3}%.": "{0} — {1} இல் அடிப்படை முத்திரைக் கட்டணம் {2}%, உங்களிடம் {3}% வசூலிக்கப்படுகிறது.",
