    "Ask a question in plain language and get a district-aware answer.": "సాధారణ భాషలో ప్రశ్న అడగండి, మీ జిల్లాకు సరిపోయే సమాధానం పొందండి.",
    "Back": "వెనుకకు",
    "Bhoomi portal or the Nadakacheri / Taluk office": "Bhoomi పోర్టల్ లేదా Nadakacheri / తాలూకా కార్యాలయం",
    "Bhoomi — RTC & land records": "Bhoomi — RTC మరియు భూ రికార్డులు",
