    "Required documents": "అవసరమైన పత్రాలు",
    "Required for converted land in all three non-agricultural categories, alongside the khata and assessment extract.": "మూడు వ్యవసాయేతర విభాగాల్లోనూ మార్పిడి చేసిన భూమికి, ఖాతా మరియు అసెస్‌మెంట్ నకలుతో పాటు ఇది అవసరం.",
    "Required for every non-agricultural property. Gram panchayat property needs the khata plus Form 9 and 11A (or computerised 11B); municipal property needs the khata and assessment register extract; BBMP property needs A-Khata and the assessment extract.": "ప్రతి వ్యవసాయేతర ఆస్తికి అవసరం. గ్రామ పంచాయతీ ఆస్తికి ఖాతాతో పాటు Form 9 మరియు 11A (లేదా కంప్యూటరీకృత 11B) కావాలి; మున్సిపల్ ఆస్తికి ఖాతా మరియు అసెస్‌మెంట్ రిజిస్టర్ నకలు; BBMP ఆస్తికి A-ఖాతా మరియు అసెస్‌మెంట్ నకలు కావాలి.",
    "Required for transfers of agricultural land, under s.131(c) of the Karnataka Land Revenue Act and Rule 46H of the Karnataka Land Revenue Rules.": "వ్యవసాయ భూమి బదిలీలకు, Karnataka Land Revenue Act లోని s.131(c) మరియు Karnataka Land Revenue Rules లోని Rule 46H కింద అవసరం.",
    "Revenue Department (Kandaya), Karnataka": "రెవెన్యూ శాఖ (కందాయ), కర్ణాటక",
