    "Run the legal checks before you release payment.": "డబ్బు చెల్లించే ముందు చట్టపరమైన తనిఖీలు పూర్తి చేయండి.",
    "Search your location": "మీ ప్రాంతాన్ని వెతకండి",
    "See the steps, documents, offices and charges that apply to you.": "మీకు వర్తించే దశలు, పత్రాలు, కార్యాలయాలు, రుసుములు చూడండి.",
    "Stamp duty and registration fee estimated for your state.": "మీ రాష్ట్రానికి స్టాంప్ డ్యూటీ, రిజిస్ట్రేషన్ రుసుము అంచనా.",
    "States covered": "చేర్చిన రాష్ట్రాలు",
    "Step-by-step guidance": "దశల వారీ మార్గదర్శకత్వం",
    "Survey No. {0} in {1}, {2} passed the automated checks. This is a prototype result — a real verification also needs a lawyer's title opinion.": "{2} రాష్ట్రంలోని {1}లో ఉన్న సర్వే నంబర్ {0} స్వయంచాలక తనిఖీలలో ఉత్తీర్ణమైంది. ఇది ప్రోటోటైప్ ఫలితం — నిజమైన ధృవీకరణకు న్యాయవాది హక్కు అభిప్రాయం కూడా అవసరం.",
    "Survey Sketch (Form 11E)": "సర్వే స్కెచ్ (Form 11E)",
