    "Talukas": "మండలాలు",
    "Tehsil Office": "తహసీల్ కార్యాలయం",
    "Tehsildar Office": "తహసీల్దార్ కార్యాలయం",
    "Thanks {0} — we will reply to {1} within two working days.": "ధన్యవాదాలు {0} — రెండు పని దినాల్లో {1}కి సమాధానం ఇస్తాము.",
    "The full land buying procedure for your district, in order.": "మీ జిల్లాకు భూమి కొనుగోలు పూర్తి విధానం, వరుస క్రమంలో.",
    "The official checklist requires PAN, or a declaration in Form 60 or 61, for sale transactions of Rs. 5 lakh and above.": "అధికారిక చెక్‌లిస్ట్ ప్రకారం 5 లక్షల రూపాయలు మరియు అంతకు మించిన అమ్మకపు లావాదేవీలకు PAN, లేదా Form 60 లేక 61 లో ప్రకటన అవసరం.",
    "The official checklist requires a copy of the RTC issued within the last 15 days, for transfers of agricultural land.": "అధికారిక చెక్‌లిస్ట్ ప్రకారం వ్యవసాయ భూమి బదిలీలకు, గత 15 రోజుల్లో జారీ అయిన RTC నకలు అవసరం.",
    "The official checklist requires title deeds, the allotment letter or a possession certificate where the property was granted by the Government or one of its departments.": "ఆస్తిని ప్రభుత్వం లేదా దాని ఏదైనా శాఖ మంజూరు చేసిన సందర్భంలో, అధికారిక చెక్‌లిస్ట్ టైటిల్ డీడ్‌లు, కేటాయింపు పత్రం లేదా స్వాధీన ధ్రువపత్రాన్ని అడుగుతుంది.",
    "Under the Maharashtra Land Revenue Code s.44 the Collector grants permission and issues a sanad. Later amendments (s.42B/42C/42D) created deemed non-agricultural status in several situations, so a separate order is not always needed.": "Maharashtra Land Revenue Code లోని s.44 కింద కలెక్టర్ అనుమతి ఇచ్చి సనద్ జారీ చేస్తారు. తరువాత వచ్చిన సవరణలు (s.42B/42C/42D) అనేక సందర్భాల్లో వ్యవసాయేతర హోదా స్వతహాగా వర్తించేలా చేశాయి, కాబట్టి ప్రత్యేక ఉత్తర్వు ఎప్పుడూ అవసరం కాదు.",
    "What each document is, why it is needed and where to get it.": "ప్రతి పత్రం ఏమిటి, అది ఎందుకు అవసరం, ఎక్కడ దొరుకుతుంది.",
    "Where a power of attorney is used, the IGR Citizen's Charter requires the original POA for verification, a certified copy for the record, and a declaration in the prescribed form that the POA still subsists.": "పవర్ ఆఫ్ అటార్నీ వాడిన సందర్భంలో, ధృవీకరణ కోసం అసలు POA, రికార్డు కోసం ధ్రువీకృత నకలు, మరియు POA ఇప్పటికీ అమలులో ఉందని నిర్దేశిత ఫారంలో ప్రకటన — ఇవి IGR Citizen's Charter అడుగుతుంది.",
    "and is issued by the": "మరియు దీన్ని జారీ చేసేది",
