    "Ask a question in plain language and get a district-aware answer.": "ಸರಳ ಭಾಷೆಯಲ್ಲಿ ಪ್ರಶ್ನೆ ಕೇಳಿ, ನಿಮ್ಮ ಜಿಲ್ಲೆಗೆ ಹೊಂದುವ ಉತ್ತರ ಪಡೆಯಿರಿ.",
