    "For agricultural transfers: an NOC or permission order under s.6 of the Karnataka Scheduled Castes and Scheduled Tribes (Prohibition of Transfer of Certain Lands) Act 1978. A declaration under s.81A of the Karnataka Land Reforms Act 1961 is required alongside it.": "ખેતીની જમીનના હસ્તાંતરણ માટે: Karnataka Scheduled Castes and Scheduled Tribes (Prohibition of Transfer of Certain Lands) Act 1978 ની s.6 હેઠળ NOC અથવા પરવાનગીનો હુકમ. તેની સાથે Karnataka Land Reforms Act 1961 ની s.81A હેઠળ ઘોષણા પણ જરૂરી છે.",
    "Four steps from \"I have no idea where to start\" to a checked, documented purchase.": "\"ક્યાંથી શરૂ કરવું એ જ ખબર નથી\" એ સ્થિતિથી ચકાસાયેલી, દસ્તાવેજ સહિતની ખરીદી સુધીનાં ચાર પગલાં.",
