    "Survey No. {0} in {1}, {2} passed the automated checks. This is a prototype result — a real verification also needs a lawyer's title opinion.": "{2}-এর {1}-এ সার্ভে নং {0} স্বয়ংক্রিয় যাচাইয়ে উত্তীর্ণ হয়েছে। এটি একটি প্রোটোটাইপ ফলাফল — প্রকৃত যাচাইয়ের জন্য আইনজীবীর স্বত্ব-মতামতও প্রয়োজন।",
    "Survey Sketch (Form 11E)": "সার্ভে স্কেচ (Form 11E)",
