    "Thanks {0} — we will reply to {1} within two working days.": "ধন্যবাদ {0} — আমরা দুই কর্মদিবসের মধ্যে {1}-এ উত্তর দেব।",
    "The full land buying procedure for your district, in order.": "আপনার জেলার জন্য জমি কেনার সম্পূর্ণ পদ্ধতি, ধাপের ক্রমে।",
    "The official checklist requires PAN, or a declaration in Form 60 or 61, for sale transactions of Rs. 5 lakh and above.": "সরকারি চেকলিস্ট অনুযায়ী 5 লক্ষ টাকা ও তার বেশি মূল্যের বিক্রয় লেনদেনের জন্য PAN, বা Form 60 বা 61-এ একটি ঘোষণাপত্র লাগে।",
    "The official checklist requires a copy of the RTC issued within the last 15 days, for transfers of agricultural land.": "সরকারি চেকলিস্ট অনুযায়ী কৃষিজমি হস্তান্তরের জন্য গত 15 দিনের মধ্যে ইস্যু করা RTC-র একটি অনুলিপি লাগে।",
    "The official checklist requires title deeds, the allotment letter or a possession certificate where the property was granted by the Government or one of its departments.": "সম্পত্তি সরকার বা তার কোনো বিভাগ মঞ্জুর করে থাকলে সরকারি চেকলিস্ট অনুযায়ী স্বত্বের দলিল, বরাদ্দপত্র বা দখল সনদ লাগে।",
    "Under the Maharashtra Land Revenue Code s.44 the Collector grants permission and issues a sanad. Later amendments (s.42B/42C/42D) created deemed non-agricultural status in several situations, so a separate order is not always needed.": "Maharashtra Land Revenue Code এর s.44 অনুসারে কলেক্টর অনুমতি দেন এবং একটি সনদ ইস্যু করেন। পরবর্তী সংশোধনীগুলি (s.42B/42C/42D) কয়েকটি ক্ষেত্রে স্বতঃসিদ্ধ অকৃষি মর্যাদা তৈরি করেছে, তাই আলাদা আদেশ সব সময় দরকার হয় না।",
    "What each document is, why it is needed and where to get it.": "প্রতিটি নথি কী, কেন দরকার আর কোথায় পাবেন।",
    "Where a power of attorney is used, the IGR Citizen's Charter requires the original POA for verification, a certified copy for the record, and a declaration in the prescribed form that the POA still subsists.": "পাওয়ার অফ অ্যাটর্নি ব্যবহার করা হলে IGR Citizen's Charter অনুযায়ী যাচাইয়ের জন্য মূল POA, নথির জন্য একটি প্রত্যয়িত অনুলিপি, এবং POA এখনও বলবৎ আছে মর্মে নির্ধারিত ফর্মে একটি ঘোষণাপত্র লাগে।",
