    "Question {0} of {1}": "{1} ਵਿੱਚੋਂ ਸਵਾਲ {0}",
    "Quick Links": "ਤੇਜ਼ ਲਿੰਕ",
    "RERA Madhya Pradesh": "RERA ਮੱਧ ਪ੍ਰਦੇਸ਼",
    "RTC (Record of Rights)": "RTC (ਹੱਕਾਂ ਦਾ ਰਿਕਾਰਡ)",
    "RTC / Pahani": "RTC / ਪਹਾਣੀ",
    "Registration charges": "ਰਜਿਸਟਰੀ ਖਰਚੇ",
    "Required documents": "ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼",
    "Required for converted land in all three non-agricultural categories, alongside the khata and assessment extract.": "ਤਿੰਨਾਂ ਗੈਰ-ਖੇਤੀ ਸ਼੍ਰੇਣੀਆਂ ਵਿੱਚ ਤਬਦੀਲ ਹੋਈ ਜ਼ਮੀਨ ਲਈ, ਖਾਤਾ ਅਤੇ ਕਰ-ਨਿਰਧਾਰਨ ਉਤਾਰੇ ਦੇ ਨਾਲ ਇਹ ਲੋੜੀਂਦਾ ਹੈ।",
    "Required for every non-agricultural property. Gram panchayat property needs the khata plus Form 9 and 11A (or computerised 11B); municipal property needs the khata and assessment register extract; BBMP property needs A-Khata and the assessment extract.": "ਹਰ ਗੈਰ-ਖੇਤੀ ਜਾਇਦਾਦ ਲਈ ਲੋੜੀਂਦਾ। ਗ੍ਰਾਮ ਪੰਚਾਇਤ ਦੀ ਜਾਇਦਾਦ ਲਈ ਖਾਤਾ ਦੇ ਨਾਲ Form 9 ਅਤੇ 11A (ਜਾਂ ਕੰਪਿਊਟਰਾਈਜ਼ਡ 11B) ਚਾਹੀਦਾ ਹੈ; ਨਗਰ ਪਾਲਿਕਾ ਦੀ ਜਾਇਦਾਦ ਲਈ ਖਾਤਾ ਅਤੇ ਕਰ-ਨਿਰਧਾਰਨ ਰਜਿਸਟਰ ਦਾ ਉਤਾਰਾ ਚਾਹੀਦਾ ਹੈ; BBMP ਦੀ ਜਾਇਦਾਦ ਲਈ A-ਖਾਤਾ ਅਤੇ ਕਰ-ਨਿਰਧਾਰਨ ਉਤਾਰਾ ਚਾਹੀਦਾ ਹੈ।",
    "Required for transfers of agricultural land, under s.131(c) of the Karnataka Land Revenue Act and Rule 46H of the Karnataka Land Revenue Rules.": "ਖੇਤੀ ਵਾਲੀ ਜ਼ਮੀਨ ਦੇ ਤਬਾਦਲਿਆਂ ਲਈ Karnataka Land Revenue Act ਦੀ s.131(c) ਅਤੇ Karnataka Land Revenue Rules ਦੇ Rule 46H ਅਧੀਨ ਇਹ ਲੋੜੀਂਦਾ ਹੈ।",
    "Revenue Department (Kandaya), Karnataka": "ਮਾਲ ਮਹਿਕਮਾ (Kandaya), ਕਰਨਾਟਕ",
    "Revenue Department, Madhya Pradesh": "ਮਾਲ ਮਹਿਕਮਾ, ਮੱਧ ਪ੍ਰਦੇਸ਼",
    "Revenue Department, Maharashtra": "ਮਾਲ ਮਹਿਕਮਾ, ਮਹਾਰਾਸ਼ਟਰ",
    "Run the legal checks before you release payment.": "ਪੈਸੇ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਕਾਨੂੰਨੀ ਜਾਂਚਾਂ ਕਰ ਲਓ।",
    "Search your location": "ਆਪਣੀ ਥਾਂ ਲੱਭੋ",
    "See the steps, documents, offices and charges that apply to you.": "ਤੁਹਾਡੇ ਉੱਤੇ ਲਾਗੂ ਹੁੰਦੇ ਕਦਮ, ਦਸਤਾਵੇਜ਼, ਦਫ਼ਤਰ ਤੇ ਖਰਚੇ ਦੇਖੋ।",
    "Stamp duty and registration fee estimated for your state.": "ਤੁਹਾਡੇ ਰਾਜ ਲਈ ਸਟੈਂਪ ਡਿਊਟੀ ਤੇ ਰਜਿਸਟਰੀ ਫ਼ੀਸ ਦਾ ਅੰਦਾਜ਼ਾ।",
    "States covered": "ਸ਼ਾਮਲ ਰਾਜ",
    "Step-by-step guidance": "ਕਦਮ-ਦਰ-ਕਦਮ ਮਾਰਗਦਰਸ਼ਨ",
    "Survey No. {0} in {1}, {2} passed the automated checks. This is a prototype result — a real verification also needs a lawyer's title opinion.": "{2} ਦੇ {1} ਵਿੱਚ ਸਰਵੇ ਨੰ. {0} ਸਵੈਚਾਲਿਤ ਜਾਂਚਾਂ ਵਿੱਚ ਪਾਸ ਹੋ ਗਿਆ। ਇਹ ਪ੍ਰੋਟੋਟਾਈਪ ਨਤੀਜਾ ਹੈ — ਅਸਲ ਤਸਦੀਕ ਲਈ ਵਕੀਲ ਦੀ ਟਾਈਟਲ ਰਾਇ ਵੀ ਲੋੜੀਂਦੀ ਹੈ।",
    "Survey Sketch (Form 11E)": "ਸਰਵੇ ਸਕੈਚ (Form 11E)",
    "Taluk Office": "ਤਾਲੁਕ ਦਫ਼ਤਰ",
    "Talukas": "ਤਹਸੀਲਾਂ",
    "Tehsil Office": "ਤਹਸੀਲ ਦਫ਼ਤਰ",
    "Tehsildar Office": "ਤਹਸੀਲਦਾਰ ਦਫ਼ਤਰ",
    "Thanks {0} — we will reply to {1} within two working days.": "ਧੰਨਵਾਦ {0} — ਅਸੀਂ ਦੋ ਕੰਮ-ਦਿਨਾਂ ਵਿੱਚ {1} 'ਤੇ ਜਵਾਬ ਦੇਵਾਂਗੇ।",
    "The full land buying procedure for your district, in order.": "ਤੁਹਾਡੇ ਜ਼ਿਲ੍ਹੇ ਲਈ ਜ਼ਮੀਨ ਖਰੀਦਣ ਦੀ ਪੂਰੀ ਪ੍ਰਕਿਰਿਆ, ਤਰਤੀਬ ਨਾਲ।",
    "The official checklist requires PAN, or a declaration in Form 60 or 61, for sale transactions of Rs. 5 lakh and above.": "ਸਰਕਾਰੀ ਚੈੱਕਲਿਸਟ ਮੁਤਾਬਕ 5 ਲੱਖ ਰੁਪਏ ਅਤੇ ਇਸ ਤੋਂ ਵੱਧ ਦੇ ਵਿਕਰੀ ਸੌਦਿਆਂ ਲਈ PAN, ਜਾਂ Form 60 ਜਾਂ 61 ਵਿੱਚ ਐਲਾਨਨਾਮਾ ਲੋੜੀਂਦਾ ਹੈ।",
    "The official checklist requires a copy of the RTC issued within the last 15 days, for transfers of agricultural land.": "ਸਰਕਾਰੀ ਚੈੱਕਲਿਸਟ ਮੁਤਾਬਕ ਖੇਤੀ ਵਾਲੀ ਜ਼ਮੀਨ ਦੇ ਤਬਾਦਲਿਆਂ ਲਈ ਪਿਛਲੇ 15 ਦਿਨਾਂ ਵਿੱਚ ਜਾਰੀ ਹੋਈ RTC ਦੀ ਨਕਲ ਲੋੜੀਂਦੀ ਹੈ।",
    "The official checklist requires title deeds, the allotment letter or a possession certificate where the property was granted by the Government or one of its departments.": "ਜਿੱਥੇ ਜਾਇਦਾਦ ਸਰਕਾਰ ਜਾਂ ਉਸ ਦੇ ਕਿਸੇ ਵਿਭਾਗ ਵੱਲੋਂ ਦਿੱਤੀ ਗਈ ਹੋਵੇ, ਉੱਥੇ ਸਰਕਾਰੀ ਚੈੱਕਲਿਸਟ ਮੁਤਾਬਕ ਮਾਲਕੀ ਦੇ ਦਸਤਾਵੇਜ਼, ਅਲਾਟਮੈਂਟ ਪੱਤਰ ਜਾਂ ਕਬਜ਼ਾ ਸਰਟੀਫਿਕੇਟ ਲੋੜੀਂਦੇ ਹਨ।",
    "Under the Maharashtra Land Revenue Code s.44 the Collector grants permission and issues a sanad. Later amendments (s.42B/42C/42D) created deemed non-agricultural status in several situations, so a separate order is not always needed.": "Maharashtra Land Revenue Code ਦੀ s.44 ਅਧੀਨ ਕਲੈਕਟਰ ਮਨਜ਼ੂਰੀ ਦਿੰਦਾ ਹੈ ਅਤੇ ਸਨਦ ਜਾਰੀ ਕਰਦਾ ਹੈ। ਬਾਅਦ ਦੀਆਂ ਸੋਧਾਂ (s.42B/42C/42D) ਨੇ ਕਈ ਹਾਲਤਾਂ ਵਿੱਚ ਮੰਨਿਆ ਹੋਇਆ ਗੈਰ-ਖੇਤੀ ਦਰਜਾ ਬਣਾ ਦਿੱਤਾ, ਸੋ ਵੱਖਰਾ ਹੁਕਮ ਹਮੇਸ਼ਾ ਲੋੜੀਂਦਾ ਨਹੀਂ ਹੁੰਦਾ।",
    "What each document is, why it is needed and where to get it.": "ਹਰ ਦਸਤਾਵੇਜ਼ ਕੀ ਹੈ, ਇਸ ਦੀ ਲੋੜ ਕਿਉਂ ਹੈ ਤੇ ਇਹ ਕਿੱਥੋਂ ਮਿਲਦਾ ਹੈ।",
    "Where a power of attorney is used, the IGR Citizen's Charter requires the original POA for verification, a certified copy for the record, and a declaration in the prescribed form that the POA still subsists.": "ਜਿੱਥੇ ਪਾਵਰ ਆਫ਼ ਅਟਾਰਨੀ ਵਰਤੀ ਜਾਂਦੀ ਹੈ, ਉੱਥੇ IGR Citizen's Charter ਮੁਤਾਬਕ ਪੜਤਾਲ ਲਈ ਅਸਲ POA, ਰਿਕਾਰਡ ਲਈ ਤਸਦੀਕਸ਼ੁਦਾ ਨਕਲ, ਅਤੇ ਇਹ ਐਲਾਨਨਾਮਾ ਕਿ POA ਹਾਲੇ ਵੀ ਕਾਇਮ ਹੈ, ਨਿਰਧਾਰਤ ਫਾਰਮ ਵਿੱਚ ਲੋੜੀਂਦੇ ਹਨ।",
    "and is issued by the": "ਅਤੇ ਇਸਨੂੰ ਜਾਰੀ ਕਰਦਾ ਹੈ",
    "contacts across": "ਸੰਪਰਕ, ਖੇਤਰ",
    "district instead, each with its own taluka.": "ਜ਼ਿਲ੍ਹੇ ਹਨ, ਹਰੇਕ ਦੀ ਆਪਣੀ ਤਹਸੀਲ ਹੈ।",
