    "passed the automated checks. This is a prototype result — a real verification also needs a lawyer's title opinion.": "ਆਪਣੇ-ਆਪ ਹੋਣ ਵਾਲੀਆਂ ਜਾਂਚਾਂ ਪਾਸ ਕੀਤੀਆਂ ਹਨ। ਇਹ ਪ੍ਰੋਟੋਟਾਈਪ ਦਾ ਨਤੀਜਾ ਹੈ — ਅਸਲ ਤਸਦੀਕ ਲਈ ਵਕੀਲ ਦੀ ਮਾਲਕੀ ਬਾਰੇ ਰਾਇ ਵੀ ਲੋੜੀਂਦੀ ਹੈ।",
