/* ── Fourth pass: strings reached through a constant ─────────────────────
 * The literal scan could not see these, because the call site passes a
 * variable rather than a quoted string: the Resources page article reader
 * (data/resourceContent.js — every heading and paragraph of the guides),
 * the office cards (what an office handles, its hours and closed days) and
 * the logo tagline, which arrives as BRAND_TAGLINE from theme.js. A second
 * scanner (scan/content_gap.mjs) now walks those data files directly, so
 * adding an article tomorrow shows up in the coverage figure.
 *
 * This block also carries three office-card templates and, for Tamil and
 * Bengali, the Smart Procedure Generator name — those two had kept it in
 * Latin while the other six languages translated it. */
