    "Agricultural land is regulated more strictly than residential or commercial property in most Indian states, and the rules vary significantly by state.": "भारत के ज़्यादातर राज्यों में खेती की ज़मीन पर रिहायशी या व्यावसायिक संपत्ति के मुकाबले कहीं सख़्त नियम लागू होते हैं, और ये नियम राज्य-दर-राज्य काफ़ी अलग होते हैं।",
    "Always required": "हमेशा ज़रूरी",
    "An Encumbrance Certificate (EC) is a record of every registered transaction against a property over a chosen period — sales, mortgages, gifts, leases, and legal claims. It's the single most important document for catching a hidden loan or a property sold twice.": "भार प्रमाणपत्र (EC) किसी चुनी हुई अवधि में ज़मीन पर हुए हर रजिस्टर्ड लेन-देन का ब्योरा होता है — बिक्री, गिरवी, दान, लीज़ और कानूनी दावे। छिपे हुए कर्ज़ या दो बार बेची गई ज़मीन को पकड़ने के लिए यही सबसे अहम दस्तावेज़ है।",
    "An entry showing the same survey number sold to a different buyer, with no matching sale-to-you in between, means someone may be trying to sell it twice.": "अगर किसी प्रविष्टि में वही सर्वे नंबर किसी दूसरे खरीदार को बिका दिखे और बीच में आपको हुई बिक्री की कोई मेल खाती प्रविष्टि न हो, तो हो सकता है कोई उसे दो बार बेचने की कोशिश कर रहा हो।",
    "Any entry showing a mortgage or loan that hasn't been marked as released is a red flag — it means a bank or lender may have a claim on the property.": "ऐसी कोई भी प्रविष्टि जिसमें गिरवी या कर्ज़ दर्ज हो और उसे छोड़ा गया (released) न दिखाया गया हो, खतरे की घंटी है — इसका मतलब किसी बैंक या कर्ज़दाता का ज़मीन पर दावा हो सकता है।",
    "Apply at the Sub-Registrar office where the property is registered, or through your state's online registration portal if it offers this service. Ask for at least 13 years of coverage as a minimum; 30 years is safer for older properties.": "जिस सब-रजिस्ट्रार कार्यालय में ज़मीन रजिस्टर्ड है, वहाँ आवेदन करें, या अगर आपके राज्य का ऑनलाइन रजिस्ट्रेशन पोर्टल यह सुविधा देता है तो उसके ज़रिए आवेदन करें। कम से कम 13 साल की अवधि ज़रूर मांगें; पुरानी संपत्तियों के लिए 30 साल ज़्यादा सुरक्षित है।",
    "Area — should match what you're being told you're buying.": "क्षेत्रफल — जितनी ज़मीन खरीदने की बात कही जा रही है, उतना ही होना चाहिए।",
    "Board resolution and company documents — if the buyer or seller is a company rather than an individual.": "बोर्ड प्रस्ताव और कंपनी के दस्तावेज़ — अगर खरीदार या विक्रेता कोई व्यक्ति नहीं, बल्कि कंपनी है।",
    "Building on agricultural land": "खेती की ज़मीन पर निर्माण",
    "Buying land in India is a longer process than buying a flat, mainly because you are responsible for confirming the seller actually owns what they're selling — no bank or builder does that verification for you. This guide walks through the process end to end, in the order most buyers actually go through it.": "भारत में ज़मीन खरीदना फ्लैट खरीदने से लंबी प्रक्रिया है, मुख्य रूप से इसलिए कि विक्रेता वाकई उस ज़मीन का मालिक है या नहीं, यह पक्का करने की ज़िम्मेदारी आपकी अपनी होती है — कोई बैंक या बिल्डर आपके लिए यह जाँच नहीं करता। यह गाइड पूरी प्रक्रिया को शुरू से आख़िर तक उसी क्रम में समझाती है, जिस क्रम में ज़्यादातर खरीदार उससे गुज़रते हैं।",
    "Ceiling limits": "ज़मीन रखने की अधिकतम सीमा",
    "Collector Office": "कलेक्टर कार्यालय",
