    "Encumbrance Certificate (EC) — usually for 13 to 30 years, showing every registered transaction or claim.": "भार प्रमाणपत्र (EC) — आम तौर पर 13 से 30 साल की अवधि का, जिसमें हर रजिस्टर्ड लेन-देन या दावा दर्ज होता है।",
    "Exactly which documents you need depends on the type of land and how the seller acquired it, but almost every purchase needs the following core set.": "आपको ठीक-ठीक कौन-से दस्तावेज़ चाहिए, यह ज़मीन के प्रकार और विक्रेता को वह ज़मीन कैसे मिली, इस पर निर्भर करता है, लेकिन लगभग हर सौदे में नीचे दिए गए बुनियादी दस्तावेज़ ज़रूरी होते हैं।",
    "How to get one": "यह कैसे मिलेगा",
    "How to read it": "इसे कैसे पढ़ें",
    "If you intend to construct a house, shop, or any non-agricultural structure, the land first needs an NA (non-agricultural) conversion order from the Collector's office. This is a separate process from the purchase itself and can take 30–90 days.": "अगर आप घर, दुकान या कोई भी गैर-कृषि निर्माण करना चाहते हैं, तो पहले कलेक्टर कार्यालय से ज़मीन का NA (गैर-कृषि) कन्वर्ज़न आदेश लेना होगा। यह खरीद से अलग एक स्वतंत्र प्रक्रिया है और इसमें 30–90 दिन लग सकते हैं।",
    "Land ceiling laws cap how much agricultural land one family can hold in aggregate across a state. Buying land that pushes a family over this limit can be legally contested later, so this is worth confirming for larger purchases.": "भू-सीमा कानून तय करते हैं कि एक परिवार पूरे राज्य में कुल मिलाकर कितनी खेती की ज़मीन रख सकता है। ऐसी ज़मीन खरीदना जिससे परिवार इस सीमा से ऊपर चला जाए, आगे चलकर कानूनी चुनौती का कारण बन सकता है, इसलिए बड़े सौदों में इसे पक्का कर लेना चाहिए।",
    "Land record extract (7/12 / RTC / Khasra-Khatauni, depending on your state) — shows the current recorded owner, area and tenure.": "ज़मीन के रिकॉर्ड का उतारा (आपके राज्य के अनुसार 7/12 / RTC / Khasra-Khatauni) — इसमें रिकॉर्ड में दर्ज मौजूदा मालिक, क्षेत्रफल और धारणा-अधिकार दिखता है।",
