    "Resend in {0}s": "{0} வினாடிகளில் மீண்டும் அனுப்பு",
    "Reset to defaults.": "இயல்பு நிலைக்கு மீட்டமைக்கப்பட்டது.",
    "Sample document set loaded.": "மாதிரி ஆவணத் தொகுப்பு ஏற்றப்பட்டது.",
    "Saved to your account. Readiness: {0}%.": "உங்கள் கணக்கில் சேமிக்கப்பட்டது. தயார்நிலை: {0}%.",
    "Security settings are not wired up in the prototype.": "பாதுகாப்பு அமைப்புகள் இந்த முன்மாதிரியில் இணைக்கப்படவில்லை.",
    "Select state and district first.": "முதலில் மாநிலமும் மாவட்டமும் தேர்ந்தெடுங்கள்.",
    "Select your state (Land Buying or Charges page) to get this state's direct official link.": "இந்த மாநிலத்தின் நேரடி அதிகாரப்பூர்வ இணைப்பைப் பெற உங்கள் மாநிலத்தைத் தேர்ந்தெடுங்கள் (நிலம் வாங்குதல் அல்லது கட்டணங்கள் பக்கத்தில்).",
    "Sending…": "அனுப்பப்படுகிறது…",
    "Signed in as {0}": "{0} ஆக உள்நுழைந்துள்ளீர்கள்",
    "Signed out.": "வெளியேறிவிட்டீர்கள்.",
    "Skip for now": "இப்போதைக்குத் தவிர்",
    "Sorry, I couldn't reach the assistant right now ({0}).": "மன்னிக்கவும், இப்போது உதவியாளரைத் தொடர்பு கொள்ள முடியவில்லை ({0}).",
    "Subscribed. Check your inbox for a confirmation.": "சந்தா பதிவானது. உறுதிப்படுத்தலுக்கு உங்கள் இன்பாக்ஸைப் பாருங்கள்.",
    "Survey No. {0} — all checks finished": "சர்வே எண். {0} — அனைத்துச் சரிபார்ப்புகளும் முடிந்தன",
    "Survey number and owner name are both required.": "சர்வே எண்ணும் உரிமையாளர் பெயரும் இரண்டும் தேவை.",
    "That email address does not look right.": "அந்த மின்னஞ்சல் முகவரி சரியாகத் தெரியவில்லை.",
    "The legal process to buy land in {0}, in the order you should do it.": "{0} இல் நிலம் வாங்குவதற்கான சட்ட நடைமுறை, நீங்கள் செய்ய வேண்டிய வரிசையில்.",
    "The legal process to buy land in {0}, {1}, in the order you should do it.": "{0}, {1} இல் நிலம் வாங்குவதற்கான சட்ட நடைமுறை, நீங்கள் செய்ய வேண்டிய வரிசையில்.",
    "This file is about {0} days old. {1} should be issued within the last 3 to 6 months.": "இந்தக் கோப்பு சுமார் {0} நாட்கள் பழையது. {1} கடந்த 3 முதல் 6 மாதங்களுக்குள் வழங்கப்பட்டிருக்க வேண்டும்.",
    "This is an academic prototype using a free email service (Resend's sandbox sender). It can only guarantee delivery to the project owner's own inbox unless a real domain is verified — if your code doesn't arrive, the same code is also printed to the backend server's terminal.": "இது இலவச மின்னஞ்சல் சேவையை (Resend இன் சாண்ட்பாக்ஸ் அனுப்புநர்) பயன்படுத்தும் ஒரு கல்வி முன்மாதிரி. உண்மையான டொமைன் சரிபார்க்கப்படாத வரை, திட்ட உரிமையாளரின் சொந்த இன்பாக்ஸுக்கு மட்டுமே சேர்வதை உறுதி செய்ய முடியும் — உங்கள் குறியீடு வரவில்லை என்றால், அதே குறியீடு பின்தள சேவையகத்தின் டெர்மினலிலும் அச்சாகும்.",
    "This resource is not written yet in the prototype.": "இந்த வளம் இன்னும் முன்மாதிரியில் எழுதப்படவில்லை.",
    "Unmarked document: {0}": "குறி நீக்கப்பட்ட ஆவணம்: {0}",
    "Verification complete. Review the results below.": "சரிபார்ப்பு முடிந்தது. கீழே உள்ள முடிவுகளைப் பாருங்கள்.",
    "Verification started.": "சரிபார்ப்பு தொடங்கியது.",
    "Verify": "சரிபார்",
    "Verify your email": "உங்கள் மின்னஞ்சலைச் சரிபாருங்கள்",
    "Verifying…": "சரிபார்க்கப்படுகிறது…",
