    "Welcome, {0}.": "வரவேற்கிறோம், {0}.",
    "Your progress is now saved to your account.": "உங்கள் முன்னேற்றம் இப்போது உங்கள் கணக்கில் சேமிக்கப்பட்டுள்ளது.",
