    "Enter your name.": "మీ పేరు నమోదు చేయండి.",
    "In {0}": "{0} లో",
    "Load real files first — the sample set can't be uploaded.": "ముందుగా నిజమైన ఫైళ్లు లోడ్ చేయండి — నమూనా సెట్‌ను అప్‌లోడ్ చేయలేరు.",
    "Log in to save these documents to your account.": "ఈ పత్రాలను మీ ఖాతాలో సేవ్ చేయడానికి లాగిన్ చేయండి.",
    "Measured against the {0} documents {1} requires.": "{1} అడిగే {0} పత్రాల ఆధారంగా లెక్కించాం.",
    "Names and notes above are {0}'s own, taken from that state's official portals — open \"Explain this\" to see the source. Where a state publishes nothing on a document, the general entry is shown unchanged. Requirements also vary with property type, so confirm the final list with your Sub-Registrar office.": "పైన ఉన్న పేర్లు, గమనికలు {0} సొంతవి; ఆ రాష్ట్ర అధికారిక పోర్టళ్ల నుంచి తీసుకున్నవి — మూలం చూడటానికి \"దీన్ని వివరించు\" తెరవండి. ఒక పత్రం గురించి రాష్ట్రం ఏమీ ప్రచురించని చోట, సాధారణ వివరం అలాగే చూపిస్తాం. అవసరాలు ఆస్తి రకాన్ని బట్టి కూడా మారతాయి, కాబట్టి తుది జాబితాను మీ సబ్-రిజిస్ట్రార్ కార్యాలయంలో నిర్ధారించుకోండి.",
    "Password needs at least 6 characters.": "పాస్‌వర్డ్‌లో కనీసం 6 అక్షరాలు ఉండాలి.",
    "Pick a subject so the message reaches the right person.": "సందేశం సరైన వ్యక్తికి చేరేలా ఒక విషయాన్ని ఎంచుకోండి.",
    "Preferences saved.": "ప్రాధాన్యతలు సేవ్ అయ్యాయి.",
    "Procedure downloaded.": "విధానం డౌన్‌లోడ్ అయింది.",
