    "Security settings are not wired up in the prototype.": "భద్రతా సెట్టింగ్‌లు ఈ ప్రోటోటైప్‌లో అనుసంధానం కాలేదు.",
    "Select state and district first.": "ముందుగా రాష్ట్రం, జిల్లా ఎంపిక చేయండి.",
    "Select your state (Land Buying or Charges page) to get this state's direct official link.": "ఈ రాష్ట్రపు నేరుగా అధికారిక లింక్ కోసం మీ రాష్ట్రాన్ని ఎంచుకోండి (భూమి కొనుగోలు లేదా రుసుములు పేజీలో).",
    "Sending…": "పంపుతోంది…",
