    "Subscribed. Check your inbox for a confirmation.": "సబ్‌స్క్రైబ్ అయ్యారు. నిర్ధారణ కోసం మీ ఇన్‌బాక్స్ చూడండి.",
    "Survey No. {0} — all checks finished": "సర్వే నం. {0} — అన్ని తనిఖీలు పూర్తయ్యాయి",
