    "That email address does not look right.": "ఆ ఇమెయిల్ చిరునామా సరిగా లేనట్టుంది.",
    "The legal process to buy land in {0}, in the order you should do it.": "{0} లో భూమి కొనడానికి చట్టపరమైన విధానం, మీరు చేయాల్సిన వరుసలో.",
    "The legal process to buy land in {0}, {1}, in the order you should do it.": "{0}, {1} లో భూమి కొనడానికి చట్టపరమైన విధానం, మీరు చేయాల్సిన వరుసలో.",
    "This file is about {0} days old. {1} should be issued within the last 3 to 6 months.": "ఈ ఫైల్ సుమారు {0} రోజుల పాతది. {1} గత 3 నుంచి 6 నెలల్లోపు జారీ అయినదై ఉండాలి.",
    "This is an academic prototype using a free email service (Resend's sandbox sender). It can only guarantee delivery to the project owner's own inbox unless a real domain is verified — if your code doesn't arrive, the same code is also printed to the backend server's terminal.": "ఇది ఉచిత ఇమెయిల్ సేవను (Resend సాండ్‌బాక్స్ సెండర్) వాడే విద్యాపరమైన ప్రోటోటైప్. నిజమైన డొమైన్ ధృవీకరించే వరకు ప్రాజెక్ట్ యజమాని సొంత ఇన్‌బాక్స్‌కు మాత్రమే చేరుతుందని హామీ ఇవ్వగలదు — మీ కోడ్ రాకపోతే, అదే కోడ్ బ్యాకెండ్ సర్వర్ టెర్మినల్‌లో కూడా కనిపిస్తుంది.",
    "This resource is not written yet in the prototype.": "ఈ వనరు ఇంకా ప్రోటోటైప్‌లో రాయలేదు.",
    "Unmarked document: {0}": "గుర్తు తీసేసిన పత్రం: {0}",
    "Verification complete. Review the results below.": "ధృవీకరణ పూర్తయింది. కింది ఫలితాలు చూడండి.",
    "Verification started.": "ధృవీకరణ మొదలైంది.",
    "Verify": "ధృవీకరించు",
    "Verify your email": "మీ ఇమెయిల్ ధృవీకరించండి",
