    "Completed step: {0}": "પૂર્ણ થયેલું પગલું: {0}",
    "Could not email the code (free-tier limit on this prototype) — ask whoever is running the backend to check its terminal, the code is printed there too.": "કોડ ઈમેલ કરી શકાયો નહીં (આ પ્રોટોટાઇપ પર મફત સેવાની મર્યાદા) — બેકએન્ડ ચલાવનારને તેનું ટર્મિનલ તપાસવા કહો, કોડ ત્યાં પણ છપાય છે.",
