    "Could not verify the code.": "કોડ ચકાસી શકાયો નહીં.",
    "Download blocked in preview. It works in a normal browser tab.": "પૂર્વદર્શનમાં ડાઉનલોડ બ્લૉક છે. સામાન્ય બ્રાઉઝર ટૅબમાં તે કામ કરે છે.",
    "Email verified.": "ઈમેલ ચકાસાયો.",
    "Enter a valid email address to subscribe.": "સબ્સ્ક્રાઇબ કરવા માન્ય ઈમેલ સરનામું દાખલ કરો.",
    "Enter the 6-digit code.": "6-digit કોડ દાખલ કરો.",
    "Enter the property value in rupees (at least ₹10,000).": "મિલકતનું મૂલ્ય રૂપિયામાં દાખલ કરો (ઓછામાં ઓછું ₹10,000).",
    "Enter your name.": "તમારું નામ દાખલ કરો.",
    "In {0}": "{0} માં",
    "Load real files first — the sample set can't be uploaded.": "પહેલાં અસલ ફાઇલો લોડ કરો — નમૂના સેટ અપલોડ કરી શકાતો નથી.",
    "Log in to save these documents to your account.": "આ દસ્તાવેજો તમારા ખાતામાં સાચવવા લૉગ ઇન કરો.",
    "Measured against the {0} documents {1} requires.": "{1} જે {0} દસ્તાવેજો માગે છે, તેની સામે માપ્યું.",
    "Names and notes above are {0}'s own, taken from that state's official portals — open \"Explain this\" to see the source. Where a state publishes nothing on a document, the general entry is shown unchanged. Requirements also vary with property type, so confirm the final list with your Sub-Registrar office.": "ઉપરનાં નામ અને નોંધ {0} નાં પોતાનાં છે, જે તે રાજ્યના સત્તાવાર પોર્ટલ પરથી લીધાં છે — સ્રોત જોવા \"આ સમજાવો\" ખોલો. જ્યાં રાજ્ય કોઈ દસ્તાવેજ વિશે કશું પ્રકાશિત ન કરતું હોય, ત્યાં સામાન્ય માહિતી જેમની તેમ બતાવાય છે. જરૂરિયાતો મિલકતના પ્રકાર પ્રમાણે પણ બદલાય છે, તેથી અંતિમ યાદી તમારી Sub-Registrar કચેરીમાં ખાતરી કરી લો.",
    "Password needs at least 6 characters.": "પાસવર્ડમાં ઓછામાં ઓછા 6 અક્ષર જોઈએ.",
    "Pick a subject so the message reaches the right person.": "વિષય પસંદ કરો, જેથી સંદેશ યોગ્ય વ્યક્તિ સુધી પહોંચે.",
    "Preferences saved.": "પસંદગીઓ સાચવી.",
    "Procedure downloaded.": "પ્રક્રિયા ડાઉનલોડ થઈ.",
    "Procedure loaded for your district.": "તમારા જિલ્લા માટે પ્રક્રિયા લોડ થઈ.",
    "Procedure rebuilt for your situation.": "તમારી પરિસ્થિતિ પ્રમાણે પ્રક્રિયા ફરી બનાવી.",
    "Profile editing is not part of this prototype.": "પ્રોફાઇલ સંપાદન આ પ્રોટોટાઇપનો ભાગ નથી.",
    "Reopened step: {0}": "ફરી ખોલેલું પગલું: {0}",
    "Report generation is not wired up in the prototype.": "પ્રોટોટાઇપમાં અહેવાલ બનાવવાની સુવિધા હજી જોડાયેલી નથી.",
    "Resend code": "કોડ ફરી મોકલો",
