/* ── Sixth pass: the AI Assistant's built-in answers ─────────────────────
 * When no Gemini key is configured (or the call fails) the assistant falls
 * back to its own rule engine. That engine runs on the server, which has no
 * dictionary, so it returns each answer as an English template plus the
 * values to drop in — see backend/src/utils/aiRuleBased.js. The templates
 * are translated here and rendered by the chat with fill(), which also
 * translates any value that is a name (a state, a district, "7/12 Extract",
 * "Tehsildar Office").
 *
 * The live model needs none of this: the request now carries the language
 * code and the system prompt asks it to answer in that language. */
const DICT_ADD6 = {
  hi: {
    "A clean purchase usually runs 30 to 45 days end to end:\n\n• Ownership and record checks — 2 to 5 days\n• Encumbrance certificate — 1 to 3 days\n• Agreement to sale — 1 day\n• Stamp duty payment — 1 day\n• Registration — 1 to 2 days\n• Mutation — 15 to 30 days\n\nMutation is the long tail. Registration makes you the owner; mutation just updates the revenue record afterwards.": "साफ-सुथरी खरीद में शुरू से आखिर तक आम तौर पर 30 से 45 दिन लगते हैं:\n\n• मालिकाना हक और रिकॉर्ड की जाँच — 2 से 5 दिन\n• भार प्रमाणपत्र — 1 से 3 दिन\n• बिक्री का करार — 1 दिन\n• स्टांप ड्यूटी का भुगतान — 1 दिन\n• रजिस्ट्रेशन — 1 से 2 दिन\n• नामांतरण — 15 से 30 दिन\n\nसबसे लंबा इंतज़ार नामांतरण का होता है। रजिस्ट्रेशन से आप मालिक बन जाते हैं; नामांतरण तो बाद में सिर्फ़ राजस्व रिकॉर्ड अपडेट करता है।",
    "A female buyer gets roughly {0}% less duty here.": "यहाँ महिला खरीदार को लगभग {0}% कम ड्यूटी देनी पड़ती है।",
    "Agricultural land has extra rules:\n\n• Several states allow only an existing farmer to buy farmland — check whether {0} restricts this.\n• The tenure class on the {1} matters. Restricted tenure needs Collector permission to sell.\n• To build a house or shop you need an NA (non-agricultural) conversion order from the Collector — 30 to 90 days.\n• Ceiling limits cap how much agricultural land one family can hold.\n\nRun the Smart Procedure Generator on the Land Buying page — it adds the conversion step automatically when you say you plan to build.": "खेती की ज़मीन पर अलग नियम लागू होते हैं:\n\n• कई राज्यों में खेती की ज़मीन सिर्फ़ पहले से किसान व्यक्ति ही खरीद सकता है — देख लें कि {0} में ऐसी पाबंदी है या नहीं।\n• {1} पर दर्ज धारणा-अधिकार की श्रेणी मायने रखती है। प्रतिबंधित श्रेणी की ज़मीन बेचने के लिए कलेक्टर की अनुमति चाहिए।\n• घर या दुकान बनानी हो तो कलेक्टर से NA (गैर-कृषि) रूपांतरण आदेश लेना पड़ता है — 30 से 90 दिन।\n• ज़मीन रखने की अधिकतम सीमा तय करती है कि एक परिवार कितनी खेती की ज़मीन रख सकता है।\n\nज़मीन खरीदना पेज पर स्मार्ट प्रक्रिया जनरेटर चलाएँ — जैसे ही आप बताते हैं कि निर्माण करना है, यह रूपांतरण का चरण अपने आप जोड़ देता है।",
    "Answering for {0}, {1}.": "जवाब {0}, {1} के लिए है।",
    "Answering for {0}.": "जवाब {0} के लिए है।",
    "Ask me something specific, like \"what documents do I need for agricultural land\" or \"how much is stamp duty here\".": "कुछ ठोस पूछिए, जैसे \"खेती की ज़मीन के लिए कौन-से दस्तावेज़ चाहिए\" या \"यहाँ स्टांप ड्यूटी कितनी है\"।",
    "For a straightforward purchase you need:\n1. Registered sale deed\n2. {0} — the land record extract\n3. Encumbrance certificate for 13 to 30 years\n4. Previous title deeds (chain of ownership)\n5. Property tax receipt, up to date\n6. Aadhaar and PAN of both buyer and seller\n7. Passport photos and address proof\n\nExtra documents depend on the case: inherited land needs a legal heir certificate, farmland used for construction needs an NA order, and a company buyer needs a board resolution.\n\nOpen the Documents page to tick these off as you collect them.": "सीधी-सादी खरीद के लिए आपको चाहिए:\n1. रजिस्टर्ड बिक्री विलेख\n2. {0} — ज़मीन के रिकॉर्ड का उतारा\n3. 13 से 30 साल का भार प्रमाणपत्र\n4. पिछले मालिकाना विलेख (मालिकी की कड़ी)\n5. संपत्ति कर की ताज़ा रसीद\n6. खरीदार और विक्रेता दोनों के Aadhaar और PAN\n7. पासपोर्ट साइज़ फोटो और पते का प्रमाण\n\nबाकी दस्तावेज़ मामले पर निर्भर करते हैं: विरासत में मिली ज़मीन के लिए वारिस प्रमाणपत्र, निर्माण के लिए इस्तेमाल होने वाली खेती की ज़मीन के लिए NA आदेश, और कंपनी खरीदार के लिए बोर्ड का प्रस्ताव ज़रूरी होता है।\n\nजैसे-जैसे ये जुटें, दस्तावेज़ पेज खोलकर उन पर निशान लगाते जाएँ।",
    "Hello. I can help with land buying procedure, required documents, stamp duty, government offices, and fraud checks.": "नमस्ते। मैं ज़मीन खरीदने की प्रक्रिया, ज़रूरी दस्तावेज़, स्टांप ड्यूटी, सरकारी दफ़्तरों और धोखाधड़ी की जाँच में मदद कर सकता हूँ।",
    "I also know your case: {0}.": "आपका मामला भी मुझे पता है: {0}।",
    "I can answer questions about:\n• The step-by-step buying procedure\n• Required documents and what each one means\n• Stamp duty and registration charges\n• Which government office handles what\n• Fraud warning signs and how to check them\n\nTry asking it in plain words — for example, \"who do I meet first\" or \"is my land record too old\".": "मैं इन सवालों के जवाब दे सकता हूँ:\n• खरीद की कदम-दर-कदम प्रक्रिया\n• ज़रूरी दस्तावेज़ और हर एक का मतलब\n• स्टांप ड्यूटी और रजिस्ट्रेशन शुल्क\n• कौन-सा सरकारी दफ़्तर क्या काम देखता है\n• धोखाधड़ी के संकेत और उन्हें कैसे परखें\n\nसीधे-सादे शब्दों में पूछिए — जैसे \"सबसे पहले किससे मिलूँ\" या \"क्या मेरा ज़मीन रिकॉर्ड बहुत पुराना है\"।",
    "In {0} the land record is called the {1}, issued by the {2}.\n\nIt tells you four things: who currently holds the land, the area, the tenure type, and — in the \"other rights\" column — any bank loan or dispute noted against it.\n\nHow to get it: download it from your state's land records portal, or apply at the {2}. It costs roughly ₹15 to ₹100.\n\nOne rule worth following: never accept an extract older than three months. Entries change.": "{0} में ज़मीन के रिकॉर्ड को {1} कहते हैं, जो {2} जारी करता है।\n\nइससे चार बातें पता चलती हैं: ज़मीन अभी किसके नाम है, क्षेत्रफल कितना है, धारणा-अधिकार किस तरह का है, और \"इतर अधिकार\" वाले खाने में दर्ज कोई बैंक कर्ज़ या विवाद।\n\nकैसे लें: अपने राज्य के भू-अभिलेख पोर्टल से डाउनलोड करें, या {2} में आवेदन दें। इसका खर्च लगभग ₹15 से ₹100 आता है।\n\nएक नियम ज़रूर मानें: तीन महीने से पुराना उतारा कभी न लें। दर्ज बातें बदलती रहती हैं।",
    "PAN is mandatory for property transactions above ₹5 lakh, for both parties.\n\nAadhaar is used for identity verification and biometrics at the Sub-Registrar office. In practice you will not get through registration without it, though the strict legal position varies by state.\n\nCarry originals plus two photocopies of each, for both buyer and seller.": "₹5 lakh से ऊपर के संपत्ति सौदों में दोनों पक्षों के लिए PAN अनिवार्य है।\n\nसब-रजिस्ट्रार कार्यालय में पहचान की पुष्टि और बायोमेट्रिक्स के लिए Aadhaar इस्तेमाल होता है। व्यवहार में इसके बिना रजिस्ट्रेशन पूरा नहीं होता, हालाँकि सख़्त कानूनी स्थिति हर राज्य में अलग है।\n\nखरीदार और विक्रेता — दोनों के असली कागज़ और हर एक की दो फोटोकॉपी साथ ले जाएँ।",
    "Partly. Most states let you download the land record extract and pay stamp duty online, and many publish encumbrance details on the registration portal.\n\nWhat still needs you in person: the registration appointment itself. Both parties and two witnesses have to appear at the Sub-Registrar office for biometrics and photographs.\n\nSo: do the research online, then book one office visit for registration.": "कुछ हद तक। ज़्यादातर राज्यों में ज़मीन के रिकॉर्ड का उतारा ऑनलाइन डाउनलोड हो जाता है और स्टांप ड्यूटी भी ऑनलाइन भरी जा सकती है; कई राज्य रजिस्ट्रेशन पोर्टल पर भार की जानकारी भी देते हैं।\n\nजिसके लिए ख़ुद जाना पड़ता है वह है रजिस्ट्रेशन की तारीख़। बायोमेट्रिक्स और फोटो के लिए दोनों पक्षों और दो गवाहों को सब-रजिस्ट्रार कार्यालय में हाज़िर होना पड़ता है।\n\nयानी: पड़ताल ऑनलाइन कर लें, और रजिस्ट्रेशन के लिए दफ़्तर का एक ही चक्कर तय करें।",
    "Stamp duty in most states is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "ज़्यादातर राज्यों में स्टांप ड्यूटी संपत्ति के मूल्य की लगभग {1}% होती है और रजिस्ट्रेशन शुल्क {2}%{3} होता है।\n\nतीन बातें लोग अक्सर गलत समझते हैं:\n1. ड्यूटी आपके करार की कीमत और सरकारी सर्कल रेट में से जो ज़्यादा हो, उस पर लगती है — इस पर नहीं कि आपने असल में कितना दिया।\n2. {4}\n3. इसे रजिस्ट्रेशन से पहले भरें और ई-स्टांप प्रमाणपत्र दफ़्तर साथ ले जाएँ।\n\nअपनी संपत्ति के मूल्य पर आँकड़ा पाने के लिए शुल्क पेज का इस्तेमाल करें।",
    "Stamp duty in {0} is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "{0} में स्टांप ड्यूटी संपत्ति के मूल्य की लगभग {1}% होती है और रजिस्ट्रेशन शुल्क {2}%{3} होता है।\n\nतीन बातें लोग अक्सर गलत समझते हैं:\n1. ड्यूटी आपके करार की कीमत और सरकारी सर्कल रेट में से जो ज़्यादा हो, उस पर लगती है — इस पर नहीं कि आपने असल में कितना दिया।\n2. {4}\n3. इसे रजिस्ट्रेशन से पहले भरें और ई-स्टांप प्रमाणपत्र दफ़्तर साथ ले जाएँ।\n\nअपनी संपत्ति के मूल्य पर आँकड़ा पाने के लिए शुल्क पेज का इस्तेमाल करें।",
    "Start with the {0} from the {1} — the name on that record is the legal holder. Then:\n\n• Match that name against the seller's Aadhaar or PAN, letter for letter.\n• Ask for the previous title deeds and read the chain backwards for at least 30 years.\n• Pull the encumbrance certificate from the Sub-Registrar office to see every registered transaction.\n• If someone is selling on the owner's behalf, ask for a registered power of attorney and check it is still valid.\n\nIf the seller resists any of this, treat it as a warning sign, not an inconvenience.": "शुरुआत {1} से मिलने वाले {0} से करें — उस रिकॉर्ड में दर्ज नाम ही कानूनी धारक है। इसके बाद:\n\n• उस नाम को विक्रेता के Aadhaar या PAN से अक्षर-दर-अक्षर मिलाएँ।\n• पिछले मालिकाना विलेख माँगें और कम से कम 30 साल पीछे तक की कड़ी पढ़ें।\n• हर रजिस्टर्ड लेन-देन देखने के लिए सब-रजिस्ट्रार कार्यालय से भार प्रमाणपत्र निकलवाएँ।\n• अगर कोई मालिक की ओर से बेच रहा है तो रजिस्टर्ड पावर ऑफ अटॉर्नी माँगें और जाँचें कि वह अब भी वैध है।\n\nविक्रेता इनमें से किसी बात पर आनाकानी करे तो इसे असुविधा नहीं, चेतावनी मानें।",
    "The patterns that catch most buyers:\n\n• The seller is not the recorded owner, or sells through an unregistered power of attorney.\n• The same land is sold to two buyers — visible in the encumbrance certificate.\n• A pending court case that never appears in the documents shown to you.\n• Farmland sold as plots without an NA conversion order.\n• Heavy pressure to pay in cash, quickly, \"before someone else takes it\".\n\nVerify the survey number through the official land records portal, and never pay in cash.": "ज़्यादातर खरीदार इन्हीं तरीकों में फँसते हैं:\n\n• विक्रेता रिकॉर्ड में दर्ज मालिक नहीं है, या बिना रजिस्टर्ड पावर ऑफ अटॉर्नी के बेच रहा है।\n• एक ही ज़मीन दो खरीदारों को बेच दी जाती है — यह भार प्रमाणपत्र में दिख जाता है।\n• अदालत में चल रहा कोई मुकदमा, जो आपको दिखाए गए दस्तावेज़ों में कहीं नहीं आता।\n• खेती की ज़मीन को बिना NA रूपांतरण आदेश के प्लॉट बनाकर बेचना।\n• नकद में, जल्दी-जल्दी, \"कोई और ले जाएगा\" कहकर भुगतान का भारी दबाव।\n\nसर्वे नंबर को सरकारी भू-अभिलेख पोर्टल पर जाँचें, और भुगतान कभी नकद में न करें।",
    "There is no female-buyer rebate in this state.": "इस राज्य में महिला खरीदार के लिए कोई छूट नहीं है।",
    "Tip: select your state and district at the top so I can answer for your district instead of generally.": "सुझाव: ऊपर अपना राज्य और ज़िला चुन लें, ताकि मैं आम जवाब की जगह आपके ज़िले के हिसाब से बता सकूँ।",
    "You will deal with these offices:\n\n• {0} — land record extract, mutation, heir certificates\n• Sub-Registrar Office — sale deed registration, encumbrance certificate\n• Collector Office — NA conversion and appeals\n• Municipal body or Gram Panchayat — property tax and layout approval\n\nThe Land Buying page shows the actual addresses, working hours and distance for {1}, so you do not travel to the wrong counter.": "आपका वास्ता इन दफ़्तरों से पड़ेगा:\n\n• {0} — ज़मीन के रिकॉर्ड का उतारा, नामांतरण, वारिस प्रमाणपत्र\n• सब-रजिस्ट्रार कार्यालय — बिक्री विलेख की रजिस्ट्री, भार प्रमाणपत्र\n• कलेक्टर कार्यालय — NA रूपांतरण और अपील\n• नगर निकाय या ग्राम पंचायत — संपत्ति कर और लेआउट मंज़ूरी\n\nज़मीन खरीदना पेज पर {1} के लिए असली पते, काम के घंटे और दूरी दी गई है, ताकि आप गलत काउंटर पर न पहुँचें।",
    "your state": "आपका राज्य",
    "your taluka": "आपकी तहसील",
  },
  mr: {
    "A clean purchase usually runs 30 to 45 days end to end:\n\n• Ownership and record checks — 2 to 5 days\n• Encumbrance certificate — 1 to 3 days\n• Agreement to sale — 1 day\n• Stamp duty payment — 1 day\n• Registration — 1 to 2 days\n• Mutation — 15 to 30 days\n\nMutation is the long tail. Registration makes you the owner; mutation just updates the revenue record afterwards.": "स्वच्छ व्यवहारात सुरुवातीपासून शेवटपर्यंत साधारण 30 ते 45 दिवस लागतात:\n\n• मालकी व अभिलेखांची तपासणी — 2 ते 5 दिवस\n• बोजा प्रमाणपत्र — 1 ते 3 दिवस\n• खरेदीचा करार — 1 दिवस\n• मुद्रांक शुल्क भरणे — 1 दिवस\n• नोंदणी — 1 ते 2 दिवस\n• फेरफार — 15 ते 30 दिवस\n\nसर्वात जास्त वेळ फेरफारला लागतो. नोंदणीमुळे तुम्ही मालक होता; फेरफार नंतर फक्त महसूल अभिलेख अद्ययावत करतो.",
    "A female buyer gets roughly {0}% less duty here.": "इथे महिला खरेदीदारास साधारण {0}% कमी शुल्क लागते.",
    "Agricultural land has extra rules:\n\n• Several states allow only an existing farmer to buy farmland — check whether {0} restricts this.\n• The tenure class on the {1} matters. Restricted tenure needs Collector permission to sell.\n• To build a house or shop you need an NA (non-agricultural) conversion order from the Collector — 30 to 90 days.\n• Ceiling limits cap how much agricultural land one family can hold.\n\nRun the Smart Procedure Generator on the Land Buying page — it adds the conversion step automatically when you say you plan to build.": "शेतजमिनीला वेगळे नियम लागू होतात:\n\n• अनेक राज्यांत शेतजमीन फक्त आधीपासून शेतकरी असलेल्या व्यक्तीलाच खरेदी करता येते — {0} मध्ये असे बंधन आहे का ते तपासा.\n• {1} वरील भोगवटादार वर्ग महत्त्वाचा असतो. निर्बंधित वर्गातील जमीन विकण्यासाठी जिल्हाधिकाऱ्यांची परवानगी लागते.\n• घर किंवा दुकान बांधायचे असल्यास जिल्हाधिकाऱ्यांकडून NA (अकृषिक) रूपांतर आदेश घ्यावा लागतो — 30 ते 90 दिवस.\n• कमाल जमीन मर्यादेमुळे एक कुटुंब किती शेतजमीन बाळगू शकते यावर बंधन येते.\n\nजमीन खरेदी पानावरील स्मार्ट प्रक्रिया जनरेटर चालवा — तुम्ही बांधकाम करणार असल्याचे सांगताच तो रूपांतराचा टप्पा आपोआप जोडतो.",
    "Answering for {0}, {1}.": "{0}, {1} साठीचे उत्तर.",
    "Answering for {0}.": "{0} साठीचे उत्तर.",
    "Ask me something specific, like \"what documents do I need for agricultural land\" or \"how much is stamp duty here\".": "काहीतरी नेमके विचारा, जसे \"शेतजमिनीसाठी कोणती कागदपत्रे लागतात\" किंवा \"इथे मुद्रांक शुल्क किती आहे\".",
    "For a straightforward purchase you need:\n1. Registered sale deed\n2. {0} — the land record extract\n3. Encumbrance certificate for 13 to 30 years\n4. Previous title deeds (chain of ownership)\n5. Property tax receipt, up to date\n6. Aadhaar and PAN of both buyer and seller\n7. Passport photos and address proof\n\nExtra documents depend on the case: inherited land needs a legal heir certificate, farmland used for construction needs an NA order, and a company buyer needs a board resolution.\n\nOpen the Documents page to tick these off as you collect them.": "साध्या खरेदीसाठी तुम्हाला हे लागते:\n1. नोंदणीकृत खरेदीखत\n2. {0} — जमिनीचा उतारा\n3. 13 ते 30 वर्षांचे बोजा प्रमाणपत्र\n4. जुनी मालकी कागदपत्रे (मालकीची साखळी)\n5. मालमत्ता कराची अद्ययावत पावती\n6. खरेदीदार व विक्रेता दोघांचे Aadhaar आणि PAN\n7. पासपोर्ट फोटो व पत्त्याचा पुरावा\n\nउरलेली कागदपत्रे प्रकरणावर अवलंबून असतात: वारसाहक्काने मिळालेल्या जमिनीसाठी वारस प्रमाणपत्र, बांधकामासाठी वापरायच्या शेतजमिनीसाठी NA आदेश, आणि कंपनी खरेदीदारासाठी संचालक मंडळाचा ठराव लागतो.\n\nही कागदपत्रे जमवत जाताना खूण करत राहण्यासाठी कागदपत्रे पान उघडा.",
    "Hello. I can help with land buying procedure, required documents, stamp duty, government offices, and fraud checks.": "नमस्कार. जमीन खरेदीची प्रक्रिया, लागणारी कागदपत्रे, मुद्रांक शुल्क, सरकारी कार्यालये आणि फसवणुकीची तपासणी — यात मी मदत करू शकतो.",
    "I also know your case: {0}.": "तुमचे प्रकरणही मला माहीत आहे: {0}.",
    "I can answer questions about:\n• The step-by-step buying procedure\n• Required documents and what each one means\n• Stamp duty and registration charges\n• Which government office handles what\n• Fraud warning signs and how to check them\n\nTry asking it in plain words — for example, \"who do I meet first\" or \"is my land record too old\".": "मी या प्रश्नांची उत्तरे देऊ शकतो:\n• खरेदीची टप्प्याटप्प्याने प्रक्रिया\n• लागणारी कागदपत्रे आणि प्रत्येकाचा अर्थ\n• मुद्रांक शुल्क व नोंदणी शुल्क\n• कोणते सरकारी कार्यालय काय पाहते\n• फसवणुकीच्या खुणा आणि त्या कशा तपासायच्या\n\nसोप्या शब्दांत विचारा — उदाहरणार्थ, \"आधी कोणाला भेटायचे\" किंवा \"माझा जमिनीचा उतारा फार जुना आहे का\".",
    "In {0} the land record is called the {1}, issued by the {2}.\n\nIt tells you four things: who currently holds the land, the area, the tenure type, and — in the \"other rights\" column — any bank loan or dispute noted against it.\n\nHow to get it: download it from your state's land records portal, or apply at the {2}. It costs roughly ₹15 to ₹100.\n\nOne rule worth following: never accept an extract older than three months. Entries change.": "{0} मध्ये जमिनीच्या अभिलेखाला {1} म्हणतात आणि तो {2} कडून दिला जातो.\n\nत्यातून चार गोष्टी कळतात: सध्या जमीन कोणाच्या नावावर आहे, क्षेत्र किती आहे, भोगवटादार वर्ग कोणता आहे, आणि \"इतर हक्क\" रकान्यात नोंदलेले बँक कर्ज किंवा वाद.\n\nकसा मिळवायचा: तुमच्या राज्याच्या जमीन अभिलेख पोर्टलवरून उतरवून घ्या, किंवा {2} कडे अर्ज करा. खर्च साधारण ₹15 ते ₹100 येतो.\n\nएक नियम पाळाच: तीन महिन्यांहून जुना उतारा कधीही स्वीकारू नका. नोंदी बदलत असतात.",
    "PAN is mandatory for property transactions above ₹5 lakh, for both parties.\n\nAadhaar is used for identity verification and biometrics at the Sub-Registrar office. In practice you will not get through registration without it, though the strict legal position varies by state.\n\nCarry originals plus two photocopies of each, for both buyer and seller.": "₹5 lakh वरील मालमत्ता व्यवहारांसाठी दोन्ही पक्षांना PAN अनिवार्य आहे.\n\nदुय्यम निबंधक कार्यालयात ओळख पडताळणी व बायोमेट्रिकसाठी Aadhaar वापरले जाते. प्रत्यक्षात त्याशिवाय नोंदणी होत नाही, मात्र कडक कायदेशीर स्थिती राज्यानुसार बदलते.\n\nखरेदीदार व विक्रेता दोघांचीही मूळ कागदपत्रे आणि प्रत्येकाच्या दोन छायाप्रती सोबत न्या.",
    "Partly. Most states let you download the land record extract and pay stamp duty online, and many publish encumbrance details on the registration portal.\n\nWhat still needs you in person: the registration appointment itself. Both parties and two witnesses have to appear at the Sub-Registrar office for biometrics and photographs.\n\nSo: do the research online, then book one office visit for registration.": "काही प्रमाणात. बहुतेक राज्यांत जमिनीचा उतारा ऑनलाइन उतरवता येतो आणि मुद्रांक शुल्कही ऑनलाइन भरता येते; अनेक राज्ये नोंदणी पोर्टलवर बोजाची माहितीही देतात.\n\nप्रत्यक्ष हजेरी लागते ती नोंदणीच्या वेळी. बायोमेट्रिक व छायाचित्रांसाठी दोन्ही पक्ष आणि दोन साक्षीदार दुय्यम निबंधक कार्यालयात हजर असावे लागतात.\n\nम्हणजे: शोधाशोध ऑनलाइन करा आणि नोंदणीसाठी कार्यालयाची एकच भेट ठरवा.",
    "Stamp duty in most states is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "बहुतेक राज्यांत मुद्रांक शुल्क मालमत्तेच्या किमतीच्या साधारण {1}% असते आणि नोंदणी शुल्क {2}%{3} असते.\n\nतीन गोष्टी लोकांच्या नेहमी चुकतात:\n1. करारातील किंमत आणि सरकारी सर्कल दर यापैकी जी जास्त असेल त्यावर शुल्क आकारले जाते — तुम्ही प्रत्यक्षात किती दिले यावर नाही.\n2. {4}\n3. ते नोंदणीपूर्वी भरा आणि ई-स्टॅम्प प्रमाणपत्र कार्यालयात सोबत न्या.\n\nतुमच्या मालमत्तेच्या किमतीनुसार आकडा मिळवण्यासाठी शुल्क पान वापरा.",
    "Stamp duty in {0} is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "{0} मध्ये मुद्रांक शुल्क मालमत्तेच्या किमतीच्या साधारण {1}% असते आणि नोंदणी शुल्क {2}%{3} असते.\n\nतीन गोष्टी लोकांच्या नेहमी चुकतात:\n1. करारातील किंमत आणि सरकारी सर्कल दर यापैकी जी जास्त असेल त्यावर शुल्क आकारले जाते — तुम्ही प्रत्यक्षात किती दिले यावर नाही.\n2. {4}\n3. ते नोंदणीपूर्वी भरा आणि ई-स्टॅम्प प्रमाणपत्र कार्यालयात सोबत न्या.\n\nतुमच्या मालमत्तेच्या किमतीनुसार आकडा मिळवण्यासाठी शुल्क पान वापरा.",
    "Start with the {0} from the {1} — the name on that record is the legal holder. Then:\n\n• Match that name against the seller's Aadhaar or PAN, letter for letter.\n• Ask for the previous title deeds and read the chain backwards for at least 30 years.\n• Pull the encumbrance certificate from the Sub-Registrar office to see every registered transaction.\n• If someone is selling on the owner's behalf, ask for a registered power of attorney and check it is still valid.\n\nIf the seller resists any of this, treat it as a warning sign, not an inconvenience.": "सुरुवात {1} कडून मिळणाऱ्या {0} पासून करा — त्या अभिलेखातील नावच कायदेशीर धारक असते. नंतर:\n\n• ते नाव विक्रेत्याच्या Aadhaar किंवा PAN शी अक्षरशः जुळवून पाहा.\n• जुनी मालकी कागदपत्रे मागा आणि किमान 30 वर्षे मागे जाऊन साखळी वाचा.\n• प्रत्येक नोंदणीकृत व्यवहार पाहण्यासाठी दुय्यम निबंधक कार्यालयातून बोजा प्रमाणपत्र काढा.\n• कोणी मालकाच्या वतीने विकत असेल तर नोंदणीकृत कुलमुखत्यारपत्र मागा आणि ते अजून वैध आहे का तपासा.\n\nविक्रेता यापैकी कशालाही टाळाटाळ करत असेल तर ती गैरसोय नव्हे, धोक्याची सूचना माना.",
    "The patterns that catch most buyers:\n\n• The seller is not the recorded owner, or sells through an unregistered power of attorney.\n• The same land is sold to two buyers — visible in the encumbrance certificate.\n• A pending court case that never appears in the documents shown to you.\n• Farmland sold as plots without an NA conversion order.\n• Heavy pressure to pay in cash, quickly, \"before someone else takes it\".\n\nVerify the survey number through the official land records portal, and never pay in cash.": "बहुतेक खरेदीदार याच जाळ्यात अडकतात:\n\n• विक्रेता अभिलेखात नोंद असलेला मालक नसतो, किंवा नोंदणी न केलेल्या कुलमुखत्यारपत्रावर विकतो.\n• तीच जमीन दोन खरेदीदारांना विकली जाते — हे बोजा प्रमाणपत्रात दिसते.\n• न्यायालयात प्रलंबित असलेला खटला, जो तुम्हाला दाखवलेल्या कागदपत्रांत कुठेच येत नाही.\n• NA रूपांतर आदेशाशिवाय शेतजमिनीचे प्लॉट पाडून विक्री.\n• \"दुसरा कोणी घेऊन जाईल\" म्हणत रोखीने, घाईघाईने पैसे देण्याचा जबरदस्त दबाव.\n\nसर्व्हे नंबर अधिकृत जमीन अभिलेख पोर्टलवर तपासा आणि रोखीने पैसे कधीही देऊ नका.",
    "There is no female-buyer rebate in this state.": "या राज्यात महिला खरेदीदारासाठी सवलत नाही.",
    "Tip: select your state and district at the top so I can answer for your district instead of generally.": "सूचना: वरती तुमचे राज्य व जिल्हा निवडा, म्हणजे मी सर्वसाधारण उत्तराऐवजी तुमच्या जिल्ह्यानुसार सांगू शकेन.",
    "You will deal with these offices:\n\n• {0} — land record extract, mutation, heir certificates\n• Sub-Registrar Office — sale deed registration, encumbrance certificate\n• Collector Office — NA conversion and appeals\n• Municipal body or Gram Panchayat — property tax and layout approval\n\nThe Land Buying page shows the actual addresses, working hours and distance for {1}, so you do not travel to the wrong counter.": "तुमचा संबंध या कार्यालयांशी येईल:\n\n• {0} — जमिनीचा उतारा, फेरफार, वारस प्रमाणपत्रे\n• दुय्यम निबंधक कार्यालय — खरेदीखताची नोंदणी, बोजा प्रमाणपत्र\n• जिल्हाधिकारी कार्यालय — NA रूपांतर व अपील\n• नगरपालिका किंवा ग्रामपंचायत — मालमत्ता कर व लेआउट मंजुरी\n\nजमीन खरेदी पानावर {1} साठीचे प्रत्यक्ष पत्ते, कामकाजाच्या वेळा व अंतर दिलेले आहे, म्हणजे तुम्ही चुकीच्या खिडकीवर जाणार नाही.",
    "your state": "तुमचे राज्य",
    "your taluka": "तुमचा तालुका",
  },
  ta: {
    "A clean purchase usually runs 30 to 45 days end to end:\n\n• Ownership and record checks — 2 to 5 days\n• Encumbrance certificate — 1 to 3 days\n• Agreement to sale — 1 day\n• Stamp duty payment — 1 day\n• Registration — 1 to 2 days\n• Mutation — 15 to 30 days\n\nMutation is the long tail. Registration makes you the owner; mutation just updates the revenue record afterwards.": "சுத்தமான ஒரு பரிவர்த்தனைக்குத் தொடக்கம் முதல் முடிவு வரை பொதுவாக 30 முதல் 45 நாட்கள் ஆகும்:\n\n• உரிமை மற்றும் பதிவேட்டுச் சரிபார்ப்பு — 2 முதல் 5 நாட்கள்\n• வில்லங்கச் சான்றிதழ் — 1 முதல் 3 நாட்கள்\n• விற்பனை ஒப்பந்தம் — 1 நாள்\n• முத்திரைத் தீர்வை செலுத்துதல் — 1 நாள்\n• பதிவு — 1 முதல் 2 நாட்கள்\n• பெயர் மாற்றம் — 15 முதல் 30 நாட்கள்\n\nநீண்ட காலம் எடுப்பது பெயர் மாற்றம்தான். பதிவு உங்களை உரிமையாளராக்குகிறது; பெயர் மாற்றம் அதன் பிறகு வருவாய்ப் பதிவேட்டைப் புதுப்பிக்கிறது, அவ்வளவுதான்.",
    "A female buyer gets roughly {0}% less duty here.": "இங்கு பெண் வாங்குபவருக்குச் சுமார் {0}% குறைவான தீர்வை விதிக்கப்படுகிறது.",
    "Agricultural land has extra rules:\n\n• Several states allow only an existing farmer to buy farmland — check whether {0} restricts this.\n• The tenure class on the {1} matters. Restricted tenure needs Collector permission to sell.\n• To build a house or shop you need an NA (non-agricultural) conversion order from the Collector — 30 to 90 days.\n• Ceiling limits cap how much agricultural land one family can hold.\n\nRun the Smart Procedure Generator on the Land Buying page — it adds the conversion step automatically when you say you plan to build.": "விவசாய நிலத்துக்குக் கூடுதல் விதிகள் உள்ளன:\n\n• பல மாநிலங்களில் ஏற்கெனவே விவசாயியாக இருப்பவர் மட்டுமே விவசாய நிலம் வாங்க முடியும் — {0} இதைக் கட்டுப்படுத்துகிறதா என்று பாருங்கள்.\n• {1}-ல் உள்ள நில உரிமை வகை முக்கியம். கட்டுப்படுத்தப்பட்ட வகை நிலத்தை விற்க ஆட்சியரின் அனுமதி தேவை.\n• வீடு அல்லது கடை கட்ட வேண்டுமானால் ஆட்சியரிடமிருந்து NA (விவசாயம் அல்லாத) மாற்று ஆணை பெற வேண்டும் — 30 முதல் 90 நாட்கள்.\n• ஒரு குடும்பம் எவ்வளவு விவசாய நிலம் வைத்திருக்கலாம் என்பதை உச்சவரம்புகள் நிர்ணயிக்கின்றன.\n\nநிலம் வாங்குதல் பக்கத்தில் ஸ்மார்ட் நடைமுறை உருவாக்கியை இயக்குங்கள் — கட்டுமானம் செய்யப் போவதாகச் சொன்னதும் அது மாற்று நடைமுறையைத் தானாகவே சேர்த்துக்கொள்ளும்.",
    "Answering for {0}, {1}.": "{0}, {1} சார்ந்த பதில்.",
    "Answering for {0}.": "{0} சார்ந்த பதில்.",
    "Ask me something specific, like \"what documents do I need for agricultural land\" or \"how much is stamp duty here\".": "குறிப்பிட்டு ஏதாவது கேளுங்கள் — உதாரணமாக, \"விவசாய நிலத்துக்கு என்ன ஆவணங்கள் தேவை\" அல்லது \"இங்கு முத்திரைத் தீர்வை எவ்வளவு\".",
    "For a straightforward purchase you need:\n1. Registered sale deed\n2. {0} — the land record extract\n3. Encumbrance certificate for 13 to 30 years\n4. Previous title deeds (chain of ownership)\n5. Property tax receipt, up to date\n6. Aadhaar and PAN of both buyer and seller\n7. Passport photos and address proof\n\nExtra documents depend on the case: inherited land needs a legal heir certificate, farmland used for construction needs an NA order, and a company buyer needs a board resolution.\n\nOpen the Documents page to tick these off as you collect them.": "நேரடியான ஒரு வாங்குதலுக்கு உங்களுக்குத் தேவைப்படுவது:\n1. பதிவு செய்யப்பட்ட கிரயப் பத்திரம்\n2. {0} — நிலப் பதிவுச் சாறு\n3. 13 முதல் 30 ஆண்டுகளுக்கான வில்லங்கச் சான்றிதழ்\n4. முந்தைய உரிமைப் பத்திரங்கள் (உரிமைத் தொடர்)\n5. நடப்புக்கு உரிய சொத்து வரி ரசீது\n6. வாங்குபவர், விற்பவர் இருவரின் Aadhaar மற்றும் PAN\n7. பாஸ்போர்ட் அளவு புகைப்படங்கள் மற்றும் முகவரிச் சான்று\n\nமீதமுள்ள ஆவணங்கள் வழக்கைப் பொறுத்தவை: வாரிசுரிமையாக வந்த நிலத்துக்கு வாரிசுச் சான்றிதழ், கட்டுமானத்துக்குப் பயன்படுத்தும் விவசாய நிலத்துக்கு NA ஆணை, நிறுவனம் வாங்கினால் இயக்குநர் குழுத் தீர்மானம் தேவை.\n\nஇவற்றைச் சேகரிக்கும்போது குறித்துக்கொள்ள ஆவணங்கள் பக்கத்தைத் திறங்கள்.",
    "Hello. I can help with land buying procedure, required documents, stamp duty, government offices, and fraud checks.": "வணக்கம். நிலம் வாங்கும் நடைமுறை, தேவையான ஆவணங்கள், முத்திரைத் தீர்வை, அரசு அலுவலகங்கள், மோசடிச் சரிபார்ப்பு — இவற்றில் நான் உதவ முடியும்.",
    "I also know your case: {0}.": "உங்கள் வழக்கும் எனக்குத் தெரியும்: {0}.",
    "I can answer questions about:\n• The step-by-step buying procedure\n• Required documents and what each one means\n• Stamp duty and registration charges\n• Which government office handles what\n• Fraud warning signs and how to check them\n\nTry asking it in plain words — for example, \"who do I meet first\" or \"is my land record too old\".": "இவை பற்றிய கேள்விகளுக்கு நான் பதில் சொல்ல முடியும்:\n• படிப்படியான வாங்கும் நடைமுறை\n• தேவையான ஆவணங்கள், ஒவ்வொன்றின் பொருள்\n• முத்திரைத் தீர்வை மற்றும் பதிவுக் கட்டணங்கள்\n• எந்த அரசு அலுவலகம் எதைக் கவனிக்கிறது\n• மோசடியின் அறிகுறிகள், அவற்றை எப்படிச் சரிபார்ப்பது\n\nஎளிய வார்த்தைகளில் கேளுங்கள் — உதாரணமாக, \"முதலில் யாரைச் சந்திக்க வேண்டும்\" அல்லது \"என் நிலப் பதிவு மிகவும் பழையதா\".",
    "In {0} the land record is called the {1}, issued by the {2}.\n\nIt tells you four things: who currently holds the land, the area, the tenure type, and — in the \"other rights\" column — any bank loan or dispute noted against it.\n\nHow to get it: download it from your state's land records portal, or apply at the {2}. It costs roughly ₹15 to ₹100.\n\nOne rule worth following: never accept an extract older than three months. Entries change.": "{0}-ல் நிலப் பதிவேடு {1} என்று அழைக்கப்படுகிறது; அதை {2} வழங்குகிறது.\n\nஅது நான்கு விஷயங்களைச் சொல்கிறது: தற்போது நிலத்தை யார் வைத்திருக்கிறார், பரப்பளவு, நில உரிமை வகை, மேலும் \"பிற உரிமைகள்\" பத்தியில் பதிவான வங்கிக் கடன் அல்லது தகராறு.\n\nஎப்படிப் பெறுவது: உங்கள் மாநில நிலப் பதிவேடு இணையதளத்தில் இருந்து பதிவிறக்கம் செய்யலாம், அல்லது {2}-ல் விண்ணப்பிக்கலாம். சுமார் ₹15 முதல் ₹100 வரை செலவாகும்.\n\nஒரு விதியைக் கட்டாயம் பின்பற்றுங்கள்: மூன்று மாதங்களுக்கும் பழைய சாற்றை ஏற்காதீர்கள். பதிவுகள் மாறிக்கொண்டே இருக்கும்.",
    "PAN is mandatory for property transactions above ₹5 lakh, for both parties.\n\nAadhaar is used for identity verification and biometrics at the Sub-Registrar office. In practice you will not get through registration without it, though the strict legal position varies by state.\n\nCarry originals plus two photocopies of each, for both buyer and seller.": "₹5 lakh-க்கு மேல் உள்ள சொத்து பரிவர்த்தனைகளுக்கு இரு தரப்பினருக்கும் PAN கட்டாயம்.\n\nசார்பதிவாளர் அலுவலகத்தில் அடையாளச் சரிபார்ப்புக்கும் கைரேகைக்கும் Aadhaar பயன்படுத்தப்படுகிறது. நடைமுறையில் அது இல்லாமல் பதிவை முடிக்க முடியாது; கண்டிப்பான சட்ட நிலை மாநிலத்துக்கு மாநிலம் மாறுபடும்.\n\nவாங்குபவர், விற்பவர் இருவரும் அசல் ஆவணங்களுடன் தலா இரண்டு நகல்களையும் எடுத்துச் செல்லுங்கள்.",
    "Partly. Most states let you download the land record extract and pay stamp duty online, and many publish encumbrance details on the registration portal.\n\nWhat still needs you in person: the registration appointment itself. Both parties and two witnesses have to appear at the Sub-Registrar office for biometrics and photographs.\n\nSo: do the research online, then book one office visit for registration.": "ஓரளவு. பெரும்பாலான மாநிலங்களில் நிலப் பதிவுச் சாற்றைப் பதிவிறக்கம் செய்யவும் முத்திரைத் தீர்வையை ஆன்லைனில் செலுத்தவும் முடியும்; பல மாநிலங்கள் பதிவு இணையதளத்தில் வில்லங்க விவரங்களையும் வெளியிடுகின்றன.\n\nநேரில் போக வேண்டியது பதிவுக்கான சந்திப்பு மட்டுமே. கைரேகை மற்றும் புகைப்படங்களுக்காக இரு தரப்பினரும் இரண்டு சாட்சிகளும் சார்பதிவாளர் அலுவலகத்தில் ஆஜராக வேண்டும்.\n\nஎனவே: ஆய்வை ஆன்லைனில் முடியுங்கள், பதிவுக்காக ஒரே ஒரு அலுவலகப் பயணத்தை ஏற்பாடு செய்யுங்கள்.",
    "Stamp duty in most states is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "பெரும்பாலான மாநிலங்களில் முத்திரைத் தீர்வை சொத்து மதிப்பில் சுமார் {1}% ஆகவும், பதிவுக் கட்டணம் {2}%{3} ஆகவும் இருக்கும்.\n\nமக்கள் தவறாகப் புரிந்துகொள்ளும் மூன்று விஷயங்கள்:\n1. உங்கள் ஒப்பந்த மதிப்பு, அரசு வழிகாட்டி மதிப்பு — இரண்டில் எது அதிகமோ அதன் மீதுதான் தீர்வை; நீங்கள் உண்மையில் கொடுத்த தொகையின் மீது அல்ல.\n2. {4}\n3. பதிவுக்கு முன்பே அதைச் செலுத்தி, மின்-முத்திரைச் சான்றிதழை அலுவலகத்துக்கு எடுத்துச் செல்லுங்கள்.\n\nஉங்கள் சொத்து மதிப்புக்கான தொகையை அறியக் கட்டணங்கள் பக்கத்தைப் பயன்படுத்துங்கள்.",
    "Stamp duty in {0} is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "{0}-ல் முத்திரைத் தீர்வை சொத்து மதிப்பில் சுமார் {1}% ஆகவும், பதிவுக் கட்டணம் {2}%{3} ஆகவும் இருக்கும்.\n\nமக்கள் தவறாகப் புரிந்துகொள்ளும் மூன்று விஷயங்கள்:\n1. உங்கள் ஒப்பந்த மதிப்பு, அரசு வழிகாட்டி மதிப்பு — இரண்டில் எது அதிகமோ அதன் மீதுதான் தீர்வை; நீங்கள் உண்மையில் கொடுத்த தொகையின் மீது அல்ல.\n2. {4}\n3. பதிவுக்கு முன்பே அதைச் செலுத்தி, மின்-முத்திரைச் சான்றிதழை அலுவலகத்துக்கு எடுத்துச் செல்லுங்கள்.\n\nஉங்கள் சொத்து மதிப்புக்கான தொகையை அறியக் கட்டணங்கள் பக்கத்தைப் பயன்படுத்துங்கள்.",
    "Start with the {0} from the {1} — the name on that record is the legal holder. Then:\n\n• Match that name against the seller's Aadhaar or PAN, letter for letter.\n• Ask for the previous title deeds and read the chain backwards for at least 30 years.\n• Pull the encumbrance certificate from the Sub-Registrar office to see every registered transaction.\n• If someone is selling on the owner's behalf, ask for a registered power of attorney and check it is still valid.\n\nIf the seller resists any of this, treat it as a warning sign, not an inconvenience.": "{1}-ல் இருந்து {0} பெறுவதில் தொடங்குங்கள் — அந்தப் பதிவேட்டில் உள்ள பெயர்தான் சட்டப்படியான உரிமையாளர். பிறகு:\n\n• அந்தப் பெயரை விற்பவரின் Aadhaar அல்லது PAN-உடன் எழுத்துக்கு எழுத்து ஒப்பிடுங்கள்.\n• முந்தைய உரிமைப் பத்திரங்களைக் கேட்டு, குறைந்தது 30 ஆண்டுகள் பின்னோக்கித் தொடரைப் படியுங்கள்.\n• பதிவான ஒவ்வொரு பரிவர்த்தனையையும் பார்க்கச் சார்பதிவாளர் அலுவலகத்தில் வில்லங்கச் சான்றிதழ் பெறுங்கள்.\n• உரிமையாளர் சார்பாக யாராவது விற்றால், பதிவு செய்யப்பட்ட அதிகாரப் பத்திரத்தைக் கேட்டு அது இன்னும் செல்லுபடியாகிறதா என்று பாருங்கள்.\n\nவிற்பவர் இவற்றில் எதற்கேனும் இழுத்தடித்தால், அதைச் சிரமம் என்று அல்ல, எச்சரிக்கை அறிகுறி என்றே எடுத்துக்கொள்ளுங்கள்.",
    "The patterns that catch most buyers:\n\n• The seller is not the recorded owner, or sells through an unregistered power of attorney.\n• The same land is sold to two buyers — visible in the encumbrance certificate.\n• A pending court case that never appears in the documents shown to you.\n• Farmland sold as plots without an NA conversion order.\n• Heavy pressure to pay in cash, quickly, \"before someone else takes it\".\n\nVerify the survey number through the official land records portal, and never pay in cash.": "பெரும்பாலான வாங்குபவர்களை மாட்டவைக்கும் முறைகள்:\n\n• விற்பவர் பதிவேட்டில் உள்ள உரிமையாளர் அல்ல, அல்லது பதிவு செய்யப்படாத அதிகாரப் பத்திரத்தின் மூலம் விற்கிறார்.\n• ஒரே நிலம் இரண்டு பேருக்கு விற்கப்படுகிறது — இது வில்லங்கச் சான்றிதழில் தெரியும்.\n• உங்களிடம் காட்டப்படும் ஆவணங்களில் எங்கும் வராத, நீதிமன்றத்தில் நிலுவையில் உள்ள வழக்கு.\n• NA மாற்று ஆணை இல்லாமல் விவசாய நிலம் மனைகளாக விற்கப்படுவது.\n• \"வேறு யாராவது எடுத்துவிடுவார்கள்\" என்று சொல்லி, அவசரமாக ரொக்கமாகப் பணம் கொடுக்கக் கடும் நிர்ப்பந்தம்.\n\nசர்வே எண்ணை அதிகாரப்பூர்வ நிலப் பதிவேடு இணையதளத்தில் சரிபாருங்கள்; ரொக்கமாக ஒருபோதும் பணம் கொடுக்காதீர்கள்.",
    "There is no female-buyer rebate in this state.": "இந்த மாநிலத்தில் பெண் வாங்குபவருக்குச் சலுகை எதுவும் இல்லை.",
    "Tip: select your state and district at the top so I can answer for your district instead of generally.": "குறிப்பு: மேலே உங்கள் மாநிலத்தையும் மாவட்டத்தையும் தேர்ந்தெடுங்கள் — பொதுவாகச் சொல்வதற்குப் பதிலாக உங்கள் மாவட்டத்துக்கேற்பப் பதில் சொல்ல முடியும்.",
    "You will deal with these offices:\n\n• {0} — land record extract, mutation, heir certificates\n• Sub-Registrar Office — sale deed registration, encumbrance certificate\n• Collector Office — NA conversion and appeals\n• Municipal body or Gram Panchayat — property tax and layout approval\n\nThe Land Buying page shows the actual addresses, working hours and distance for {1}, so you do not travel to the wrong counter.": "இந்த அலுவலகங்களுடன் நீங்கள் பழக வேண்டியிருக்கும்:\n\n• {0} — நிலப் பதிவுச் சாறு, பெயர் மாற்றம், வாரிசுச் சான்றிதழ்கள்\n• சார்பதிவாளர் அலுவலகம் — கிரயப் பத்திரப் பதிவு, வில்லங்கச் சான்றிதழ்\n• ஆட்சியர் அலுவலகம் — NA மாற்றம் மற்றும் மேல்முறையீடுகள்\n• நகராட்சி அல்லது கிராம ஊராட்சி — சொத்து வரி மற்றும் லேஅவுட் ஒப்புதல்\n\nநிலம் வாங்குதல் பக்கத்தில் {1}-க்கான உண்மையான முகவரிகள், வேலை நேரம், தூரம் ஆகியவை உள்ளன — தவறான கவுண்டருக்குப் போக வேண்டியிருக்காது.",
    "your state": "உங்கள் மாநிலம்",
    "your taluka": "உங்கள் தாலுகா",
  },
  te: {
    "A clean purchase usually runs 30 to 45 days end to end:\n\n• Ownership and record checks — 2 to 5 days\n• Encumbrance certificate — 1 to 3 days\n• Agreement to sale — 1 day\n• Stamp duty payment — 1 day\n• Registration — 1 to 2 days\n• Mutation — 15 to 30 days\n\nMutation is the long tail. Registration makes you the owner; mutation just updates the revenue record afterwards.": "శుభ్రమైన కొనుగోలుకు మొదటి నుంచి చివరి వరకు సాధారణంగా 30 నుంచి 45 రోజులు పడుతుంది:\n\n• యాజమాన్యం, రికార్డుల పరిశీలన — 2 నుంచి 5 రోజులు\n• ఎన్‌కంబరెన్స్ సర్టిఫికేట్ — 1 నుంచి 3 రోజులు\n• అమ్మకపు ఒప్పందం — 1 రోజు\n• స్టాంప్ డ్యూటీ చెల్లింపు — 1 రోజు\n• రిజిస్ట్రేషన్ — 1 నుంచి 2 రోజులు\n• మ్యుటేషన్ — 15 నుంచి 30 రోజులు\n\nఎక్కువ సమయం తీసుకునేది మ్యుటేషనే. రిజిస్ట్రేషన్‌తో మీరు యజమాని అవుతారు; మ్యుటేషన్ ఆ తర్వాత రెవెన్యూ రికార్డును నవీకరించడం మాత్రమే చేస్తుంది.",
    "A female buyer gets roughly {0}% less duty here.": "ఇక్కడ మహిళా కొనుగోలుదారుకు సుమారు {0}% తక్కువ డ్యూటీ ఉంటుంది.",
    "Agricultural land has extra rules:\n\n• Several states allow only an existing farmer to buy farmland — check whether {0} restricts this.\n• The tenure class on the {1} matters. Restricted tenure needs Collector permission to sell.\n• To build a house or shop you need an NA (non-agricultural) conversion order from the Collector — 30 to 90 days.\n• Ceiling limits cap how much agricultural land one family can hold.\n\nRun the Smart Procedure Generator on the Land Buying page — it adds the conversion step automatically when you say you plan to build.": "వ్యవసాయ భూమికి అదనపు నిబంధనలు ఉన్నాయి:\n\n• చాలా రాష్ట్రాల్లో ఇప్పటికే రైతుగా ఉన్నవారే వ్యవసాయ భూమిని కొనగలరు — {0} లో అలాంటి ఆంక్ష ఉందా చూసుకోండి.\n• {1} లోని టెన్యూర్ తరగతి ముఖ్యం. ఆంక్షలున్న తరగతి భూమిని అమ్మాలంటే కలెక్టర్ అనుమతి కావాలి.\n• ఇల్లు లేదా దుకాణం కట్టాలంటే కలెక్టర్ నుంచి NA (వ్యవసాయేతర) మార్పిడి ఉత్తర్వు తీసుకోవాలి — 30 నుంచి 90 రోజులు.\n• ఒక కుటుంబం ఎంత వ్యవసాయ భూమి కలిగి ఉండవచ్చో గరిష్ఠ పరిమితులు నిర్ణయిస్తాయి.\n\nభూమి కొనుగోలు పేజీలో స్మార్ట్ ప్రొసీజర్ జనరేటర్ నడపండి — నిర్మాణం చేస్తానని చెప్పగానే అది మార్పిడి దశను దానంతట అదే చేరుస్తుంది.",
    "Answering for {0}, {1}.": "{0}, {1} కోసం సమాధానం.",
    "Answering for {0}.": "{0} కోసం సమాధానం.",
    "Ask me something specific, like \"what documents do I need for agricultural land\" or \"how much is stamp duty here\".": "నిర్దిష్టంగా ఏదైనా అడగండి — ఉదాహరణకు, \"వ్యవసాయ భూమికి ఏ పత్రాలు కావాలి\" లేదా \"ఇక్కడ స్టాంప్ డ్యూటీ ఎంత\".",
    "For a straightforward purchase you need:\n1. Registered sale deed\n2. {0} — the land record extract\n3. Encumbrance certificate for 13 to 30 years\n4. Previous title deeds (chain of ownership)\n5. Property tax receipt, up to date\n6. Aadhaar and PAN of both buyer and seller\n7. Passport photos and address proof\n\nExtra documents depend on the case: inherited land needs a legal heir certificate, farmland used for construction needs an NA order, and a company buyer needs a board resolution.\n\nOpen the Documents page to tick these off as you collect them.": "సాదాసీదా కొనుగోలుకు మీకు కావాల్సినవి:\n1. రిజిస్టర్ చేసిన అమ్మకపు దస్తావేజు\n2. {0} — భూ రికార్డు నకలు\n3. 13 నుంచి 30 సంవత్సరాల ఎన్‌కంబరెన్స్ సర్టిఫికేట్\n4. గత హక్కు దస్తావేజులు (యాజమాన్య గొలుసు)\n5. తాజా ఆస్తి పన్ను రసీదు\n6. కొనేవారు, అమ్మేవారు ఇద్దరి Aadhaar మరియు PAN\n7. పాస్‌పోర్ట్ ఫోటోలు, చిరునామా రుజువు\n\nమిగిలిన పత్రాలు కేసును బట్టి ఉంటాయి: వారసత్వంగా వచ్చిన భూమికి వారసత్వ సర్టిఫికేట్, నిర్మాణానికి వాడే వ్యవసాయ భూమికి NA ఉత్తర్వు, కంపెనీ కొంటే బోర్డు తీర్మానం అవసరం.\n\nవీటిని సేకరిస్తూ టిక్ చేసుకోవడానికి పత్రాలు పేజీ తెరవండి.",
    "Hello. I can help with land buying procedure, required documents, stamp duty, government offices, and fraud checks.": "నమస్కారం. భూమి కొనుగోలు విధానం, అవసరమైన పత్రాలు, స్టాంప్ డ్యూటీ, ప్రభుత్వ కార్యాలయాలు, మోసాల పరిశీలన — వీటిలో నేను సాయం చేయగలను.",
    "I also know your case: {0}.": "మీ కేసు కూడా నాకు తెలుసు: {0}.",
    "I can answer questions about:\n• The step-by-step buying procedure\n• Required documents and what each one means\n• Stamp duty and registration charges\n• Which government office handles what\n• Fraud warning signs and how to check them\n\nTry asking it in plain words — for example, \"who do I meet first\" or \"is my land record too old\".": "నేను ఈ విషయాలపై సమాధానం చెప్పగలను:\n• దశలవారీ కొనుగోలు విధానం\n• అవసరమైన పత్రాలు, ఒక్కొక్కటి దేనికో\n• స్టాంప్ డ్యూటీ, రిజిస్ట్రేషన్ రుసుములు\n• ఏ ప్రభుత్వ కార్యాలయం ఏ పని చూస్తుంది\n• మోసపు హెచ్చరిక సంకేతాలు, వాటిని ఎలా పరిశీలించాలి\n\nసాధారణ మాటల్లోనే అడగండి — ఉదాహరణకు, \"ముందు ఎవరిని కలవాలి\" లేదా \"నా భూ రికార్డు చాలా పాతదా\".",
    "In {0} the land record is called the {1}, issued by the {2}.\n\nIt tells you four things: who currently holds the land, the area, the tenure type, and — in the \"other rights\" column — any bank loan or dispute noted against it.\n\nHow to get it: download it from your state's land records portal, or apply at the {2}. It costs roughly ₹15 to ₹100.\n\nOne rule worth following: never accept an extract older than three months. Entries change.": "{0} లో భూ రికార్డును {1} అంటారు, దీన్ని {2} జారీ చేస్తుంది.\n\nఅది నాలుగు విషయాలు చెబుతుంది: ప్రస్తుతం భూమి ఎవరి పేరిట ఉంది, విస్తీర్ణం, టెన్యూర్ రకం, మరియు \"ఇతర హక్కులు\" కాలమ్‌లో నమోదైన బ్యాంకు రుణం లేదా వివాదం.\n\nఎలా తీసుకోవాలి: మీ రాష్ట్ర భూ రికార్డుల పోర్టల్ నుంచి డౌన్‌లోడ్ చేసుకోండి, లేదా {2} లో దరఖాస్తు చేసుకోండి. సుమారు ₹15 నుంచి ₹100 ఖర్చవుతుంది.\n\nఒక నియమం తప్పక పాటించండి: మూడు నెలల కంటే పాత నకలును ఎప్పుడూ తీసుకోవద్దు. నమోదులు మారుతూ ఉంటాయి.",
    "PAN is mandatory for property transactions above ₹5 lakh, for both parties.\n\nAadhaar is used for identity verification and biometrics at the Sub-Registrar office. In practice you will not get through registration without it, though the strict legal position varies by state.\n\nCarry originals plus two photocopies of each, for both buyer and seller.": "₹5 lakh పైబడిన ఆస్తి లావాదేవీలకు ఇరు పక్షాలకూ PAN తప్పనిసరి.\n\nసబ్-రిజిస్ట్రార్ కార్యాలయంలో గుర్తింపు ధృవీకరణకు, బయోమెట్రిక్స్‌కు Aadhaar వాడతారు. ఆచరణలో అది లేకుండా రిజిస్ట్రేషన్ పూర్తికాదు; కచ్చితమైన చట్టపరమైన స్థితి రాష్ట్రాన్ని బట్టి మారుతుంది.\n\nకొనేవారు, అమ్మేవారు ఇద్దరూ ఒరిజినల్స్‌తో పాటు ఒక్కోదాని రెండు జిరాక్స్ కాపీలు తీసుకెళ్లండి.",
    "Partly. Most states let you download the land record extract and pay stamp duty online, and many publish encumbrance details on the registration portal.\n\nWhat still needs you in person: the registration appointment itself. Both parties and two witnesses have to appear at the Sub-Registrar office for biometrics and photographs.\n\nSo: do the research online, then book one office visit for registration.": "కొంతవరకు. చాలా రాష్ట్రాల్లో భూ రికార్డు నకలును డౌన్‌లోడ్ చేసుకోవచ్చు, స్టాంప్ డ్యూటీని ఆన్‌లైన్‌లో చెల్లించవచ్చు; చాలా రాష్ట్రాలు రిజిస్ట్రేషన్ పోర్టల్‌లో ఎన్‌కంబరెన్స్ వివరాలనూ ఇస్తున్నాయి.\n\nమీరు స్వయంగా వెళ్లాల్సింది రిజిస్ట్రేషన్ అపాయింట్‌మెంట్‌కు మాత్రమే. బయోమెట్రిక్స్, ఫోటోల కోసం ఇరు పక్షాలు, ఇద్దరు సాక్షులు సబ్-రిజిస్ట్రార్ కార్యాలయానికి హాజరు కావాలి.\n\nఅంటే: పరిశీలన అంతా ఆన్‌లైన్‌లో ముగించి, రిజిస్ట్రేషన్ కోసం ఒక్కసారి కార్యాలయానికి వెళ్లేలా ప్లాన్ చేసుకోండి.",
    "Stamp duty in most states is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "చాలా రాష్ట్రాల్లో స్టాంప్ డ్యూటీ ఆస్తి విలువలో సుమారు {1}%, రిజిస్ట్రేషన్ రుసుము {2}%{3} ఉంటుంది.\n\nజనం పొరపడే మూడు విషయాలు:\n1. మీ ఒప్పంద విలువ, ప్రభుత్వ సర్కిల్ రేటు — వీటిలో ఎక్కువ దానిపై డ్యూటీ వసూలు చేస్తారు; మీరు నిజంగా చెల్లించిన దానిపై కాదు.\n2. {4}\n3. రిజిస్ట్రేషన్‌కు ముందే దాన్ని చెల్లించి, ఇ-స్టాంప్ సర్టిఫికేట్‌ను కార్యాలయానికి తీసుకెళ్లండి.\n\nమీ ఆస్తి విలువకు తగిన అంకె తెలుసుకోవడానికి రుసుములు పేజీ వాడండి.",
    "Stamp duty in {0} is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "{0} లో స్టాంప్ డ్యూటీ ఆస్తి విలువలో సుమారు {1}%, రిజిస్ట్రేషన్ రుసుము {2}%{3} ఉంటుంది.\n\nజనం పొరపడే మూడు విషయాలు:\n1. మీ ఒప్పంద విలువ, ప్రభుత్వ సర్కిల్ రేటు — వీటిలో ఎక్కువ దానిపై డ్యూటీ వసూలు చేస్తారు; మీరు నిజంగా చెల్లించిన దానిపై కాదు.\n2. {4}\n3. రిజిస్ట్రేషన్‌కు ముందే దాన్ని చెల్లించి, ఇ-స్టాంప్ సర్టిఫికేట్‌ను కార్యాలయానికి తీసుకెళ్లండి.\n\nమీ ఆస్తి విలువకు తగిన అంకె తెలుసుకోవడానికి రుసుములు పేజీ వాడండి.",
    "Start with the {0} from the {1} — the name on that record is the legal holder. Then:\n\n• Match that name against the seller's Aadhaar or PAN, letter for letter.\n• Ask for the previous title deeds and read the chain backwards for at least 30 years.\n• Pull the encumbrance certificate from the Sub-Registrar office to see every registered transaction.\n• If someone is selling on the owner's behalf, ask for a registered power of attorney and check it is still valid.\n\nIf the seller resists any of this, treat it as a warning sign, not an inconvenience.": "{1} నుంచి {0} తీసుకోవడంతో మొదలుపెట్టండి — ఆ రికార్డులో ఉన్న పేరే చట్టబద్ధమైన హక్కుదారు. తర్వాత:\n\n• ఆ పేరును అమ్మేవారి Aadhaar లేదా PAN తో అక్షరం అక్షరం సరిపోల్చండి.\n• గత హక్కు దస్తావేజులు అడిగి, కనీసం 30 సంవత్సరాల వెనక్కి ఆ గొలుసును చదవండి.\n• నమోదైన ప్రతి లావాదేవీని చూడటానికి సబ్-రిజిస్ట్రార్ కార్యాలయం నుంచి ఎన్‌కంబరెన్స్ సర్టిఫికేట్ తీసుకోండి.\n• యజమాని తరఫున ఎవరైనా అమ్ముతుంటే, రిజిస్టర్ చేసిన పవర్ ఆఫ్ అటార్నీ అడిగి అది ఇంకా చెల్లుబాటులో ఉందా చూడండి.\n\nఅమ్మేవారు వీటిలో దేనికైనా మొండికేస్తే, దాన్ని ఇబ్బందిగా కాక హెచ్చరికగా భావించండి.",
    "The patterns that catch most buyers:\n\n• The seller is not the recorded owner, or sells through an unregistered power of attorney.\n• The same land is sold to two buyers — visible in the encumbrance certificate.\n• A pending court case that never appears in the documents shown to you.\n• Farmland sold as plots without an NA conversion order.\n• Heavy pressure to pay in cash, quickly, \"before someone else takes it\".\n\nVerify the survey number through the official land records portal, and never pay in cash.": "చాలామంది కొనుగోలుదారులు ఇవే వలల్లో పడతారు:\n\n• అమ్మేవారు రికార్డులో ఉన్న యజమాని కాదు, లేదా రిజిస్టర్ కాని పవర్ ఆఫ్ అటార్నీతో అమ్ముతుంటారు.\n• ఒకే భూమిని ఇద్దరికి అమ్మడం — ఇది ఎన్‌కంబరెన్స్ సర్టిఫికేట్‌లో కనిపిస్తుంది.\n• మీకు చూపిన పత్రాల్లో ఎక్కడా కనిపించని, కోర్టులో పెండింగ్‌లో ఉన్న కేసు.\n• NA మార్పిడి ఉత్తర్వు లేకుండా వ్యవసాయ భూమిని ప్లాట్లుగా అమ్మడం.\n• \"ఇంకెవరో తీసుకుపోతారు\" అంటూ హడావుడిగా నగదు చెల్లించమని తీవ్ర ఒత్తిడి.\n\nసర్వే నంబరును అధికారిక భూ రికార్డుల పోర్టల్‌లో ధృవీకరించుకోండి; నగదు రూపంలో ఎప్పుడూ చెల్లించవద్దు.",
    "There is no female-buyer rebate in this state.": "ఈ రాష్ట్రంలో మహిళా కొనుగోలుదారులకు రాయితీ లేదు.",
    "Tip: select your state and district at the top so I can answer for your district instead of generally.": "సూచన: పైన మీ రాష్ట్రం, జిల్లా ఎంచుకోండి — అప్పుడు సాధారణంగా కాకుండా మీ జిల్లాకు తగ్గట్టు సమాధానం చెప్పగలను.",
    "You will deal with these offices:\n\n• {0} — land record extract, mutation, heir certificates\n• Sub-Registrar Office — sale deed registration, encumbrance certificate\n• Collector Office — NA conversion and appeals\n• Municipal body or Gram Panchayat — property tax and layout approval\n\nThe Land Buying page shows the actual addresses, working hours and distance for {1}, so you do not travel to the wrong counter.": "మీకు ఈ కార్యాలయాలతో పని ఉంటుంది:\n\n• {0} — భూ రికార్డు నకలు, మ్యుటేషన్, వారసత్వ సర్టిఫికేట్లు\n• సబ్-రిజిస్ట్రార్ కార్యాలయం — అమ్మకపు దస్తావేజు రిజిస్ట్రేషన్, ఎన్‌కంబరెన్స్ సర్టిఫికేట్\n• కలెక్టర్ కార్యాలయం — NA మార్పిడి, అప్పీళ్లు\n• మున్సిపల్ సంస్థ లేదా గ్రామ పంచాయతీ — ఆస్తి పన్ను, లేఅవుట్ అనుమతి\n\nభూమి కొనుగోలు పేజీలో {1} కోసం అసలు చిరునామాలు, పనివేళలు, దూరం ఇచ్చి ఉంటాయి — తప్పు కౌంటర్‌కు వెళ్లాల్సిన పని ఉండదు.",
    "your state": "మీ రాష్ట్రం",
    "your taluka": "మీ మండలం",
  },
  kn: {
    "A clean purchase usually runs 30 to 45 days end to end:\n\n• Ownership and record checks — 2 to 5 days\n• Encumbrance certificate — 1 to 3 days\n• Agreement to sale — 1 day\n• Stamp duty payment — 1 day\n• Registration — 1 to 2 days\n• Mutation — 15 to 30 days\n\nMutation is the long tail. Registration makes you the owner; mutation just updates the revenue record afterwards.": "ಸ್ವಚ್ಛವಾದ ಖರೀದಿ ಸಾಮಾನ್ಯವಾಗಿ ಆರಂಭದಿಂದ ಕೊನೆಯವರೆಗೆ 30 ರಿಂದ 45 ದಿನಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ:\n\n• ಮಾಲೀಕತ್ವ ಮತ್ತು ದಾಖಲೆ ಪರಿಶೀಲನೆ — 2 ರಿಂದ 5 ದಿನಗಳು\n• ಋಣಭಾರ ಪ್ರಮಾಣಪತ್ರ — 1 ರಿಂದ 3 ದಿನಗಳು\n• ಮಾರಾಟ ಒಪ್ಪಂದ — 1 ದಿನ\n• ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಪಾವತಿ — 1 ದಿನ\n• ನೋಂದಣಿ — 1 ರಿಂದ 2 ದಿನಗಳು\n• ಖಾತಾ ಬದಲಾವಣೆ — 15 ರಿಂದ 30 ದಿನಗಳು\n\nಅತಿ ಹೆಚ್ಚು ಸಮಯ ತೆಗೆದುಕೊಳ್ಳುವುದು ಖಾತಾ ಬದಲಾವಣೆಯೇ. ನೋಂದಣಿಯಿಂದ ನೀವು ಮಾಲೀಕರಾಗುತ್ತೀರಿ; ಖಾತಾ ಬದಲಾವಣೆ ಆ ನಂತರ ಕಂದಾಯ ದಾಖಲೆಯನ್ನು ನವೀಕರಿಸುತ್ತದೆ ಅಷ್ಟೇ.",
    "A female buyer gets roughly {0}% less duty here.": "ಮಹಿಳಾ ಖರೀದಿದಾರರಿಗೆ ಇಲ್ಲಿ ಸುಮಾರು {0}% ಕಡಿಮೆ ಶುಲ್ಕ ಇರುತ್ತದೆ.",
    "Agricultural land has extra rules:\n\n• Several states allow only an existing farmer to buy farmland — check whether {0} restricts this.\n• The tenure class on the {1} matters. Restricted tenure needs Collector permission to sell.\n• To build a house or shop you need an NA (non-agricultural) conversion order from the Collector — 30 to 90 days.\n• Ceiling limits cap how much agricultural land one family can hold.\n\nRun the Smart Procedure Generator on the Land Buying page — it adds the conversion step automatically when you say you plan to build.": "ಕೃಷಿ ಭೂಮಿಗೆ ಹೆಚ್ಚುವರಿ ನಿಯಮಗಳಿವೆ:\n\n• ಹಲವು ರಾಜ್ಯಗಳಲ್ಲಿ ಈಗಾಗಲೇ ರೈತರಾಗಿರುವವರಿಗೆ ಮಾತ್ರ ಕೃಷಿ ಭೂಮಿ ಖರೀದಿಸಲು ಅವಕಾಶವಿದೆ — {0} ರಾಜ್ಯದಲ್ಲಿ ಈ ನಿರ್ಬಂಧ ಇದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ.\n• {1} ದಾಖಲೆಯಲ್ಲಿನ ಹಿಡುವಳಿ ವರ್ಗ ಮುಖ್ಯ. ನಿರ್ಬಂಧಿತ ಹಿಡುವಳಿಯನ್ನು ಮಾರಲು ಜಿಲ್ಲಾಧಿಕಾರಿಯ ಅನುಮತಿ ಬೇಕು.\n• ಮನೆ ಅಥವಾ ಅಂಗಡಿ ಕಟ್ಟಬೇಕಾದರೆ ಜಿಲ್ಲಾಧಿಕಾರಿಯಿಂದ NA (ಕೃಷಿಯೇತರ) ಪರಿವರ್ತನಾ ಆದೇಶ ಪಡೆಯಬೇಕು — 30 ರಿಂದ 90 ದಿನಗಳು.\n• ಒಂದು ಕುಟುಂಬ ಎಷ್ಟು ಕೃಷಿ ಭೂಮಿ ಹೊಂದಬಹುದು ಎಂಬುದಕ್ಕೆ ಗರಿಷ್ಠ ಮಿತಿ ಇದೆ.\n\nಭೂಮಿ ಖರೀದಿ ಪುಟದಲ್ಲಿ ಸ್ಮಾರ್ಟ್ ಕಾರ್ಯವಿಧಾನ ಜನರೇಟರ್ ಬಳಸಿ — ಕಟ್ಟಡ ಕಟ್ಟುವ ಯೋಜನೆ ಇದೆ ಎಂದು ಹೇಳಿದರೆ ಅದು ಪರಿವರ್ತನೆ ಹಂತವನ್ನು ತಾನಾಗಿಯೇ ಸೇರಿಸುತ್ತದೆ.",
    "Answering for {0}, {1}.": "{0}, {1} ಗಾಗಿ ಉತ್ತರಿಸಲಾಗುತ್ತಿದೆ.",
    "Answering for {0}.": "{0} ಗಾಗಿ ಉತ್ತರಿಸಲಾಗುತ್ತಿದೆ.",
    "Ask me something specific, like \"what documents do I need for agricultural land\" or \"how much is stamp duty here\".": "\"ಕೃಷಿ ಭೂಮಿಗೆ ಯಾವ ದಾಖಲೆಗಳು ಬೇಕು\" ಅಥವಾ \"ಇಲ್ಲಿ ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಎಷ್ಟು\" ಎಂಬಂತಹ ನಿರ್ದಿಷ್ಟ ಪ್ರಶ್ನೆಯನ್ನು ಕೇಳಿ.",
    "For a straightforward purchase you need:\n1. Registered sale deed\n2. {0} — the land record extract\n3. Encumbrance certificate for 13 to 30 years\n4. Previous title deeds (chain of ownership)\n5. Property tax receipt, up to date\n6. Aadhaar and PAN of both buyer and seller\n7. Passport photos and address proof\n\nExtra documents depend on the case: inherited land needs a legal heir certificate, farmland used for construction needs an NA order, and a company buyer needs a board resolution.\n\nOpen the Documents page to tick these off as you collect them.": "ಸರಳವಾದ ಖರೀದಿಗೆ ನಿಮಗೆ ಬೇಕಾಗುವುದು:\n1. ನೋಂದಾಯಿತ ಕ್ರಯಪತ್ರ\n2. {0} — ಭೂ ದಾಖಲೆ ಉತಾರ\n3. 13 ರಿಂದ 30 ವರ್ಷಗಳ ಋಣಭಾರ ಪ್ರಮಾಣಪತ್ರ\n4. ಹಿಂದಿನ ಹಕ್ಕುಪತ್ರಗಳು (ಮಾಲೀಕತ್ವದ ಸರಪಳಿ)\n5. ಇಲ್ಲಿಯವರೆಗೆ ಪಾವತಿಸಿದ ಆಸ್ತಿ ತೆರಿಗೆ ರಸೀದಿ\n6. ಖರೀದಿದಾರ ಮತ್ತು ಮಾರಾಟಗಾರ ಇಬ್ಬರ Aadhaar ಮತ್ತು PAN\n7. ಪಾಸ್‌ಪೋರ್ಟ್ ಅಳತೆಯ ಫೋಟೋಗಳು ಮತ್ತು ವಿಳಾಸ ದೃಢೀಕರಣ\n\nಹೆಚ್ಚುವರಿ ದಾಖಲೆಗಳು ಪ್ರಕರಣಕ್ಕೆ ತಕ್ಕಂತೆ ಬದಲಾಗುತ್ತವೆ: ಪಿತ್ರಾರ್ಜಿತ ಭೂಮಿಗೆ ಕಾನೂನುಬದ್ಧ ವಾರಸುದಾರ ಪ್ರಮಾಣಪತ್ರ, ಕಟ್ಟಡಕ್ಕೆ ಬಳಸುವ ಕೃಷಿ ಭೂಮಿಗೆ NA ಆದೇಶ, ಮತ್ತು ಖರೀದಿದಾರ ಕಂಪನಿಯಾಗಿದ್ದರೆ ಮಂಡಳಿ ನಿರ್ಣಯ.\n\nಸಂಗ್ರಹಿಸುತ್ತಾ ಗುರುತು ಹಾಕಿಕೊಳ್ಳಲು ದಾಖಲೆಗಳು ಪುಟವನ್ನು ತೆರೆಯಿರಿ.",
    "Hello. I can help with land buying procedure, required documents, stamp duty, government offices, and fraud checks.": "ನಮಸ್ಕಾರ. ಭೂಮಿ ಖರೀದಿ ಕಾರ್ಯವಿಧಾನ, ಬೇಕಾದ ದಾಖಲೆಗಳು, ಮುದ್ರಾಂಕ ಶುಲ್ಕ, ಸರ್ಕಾರಿ ಕಚೇರಿಗಳು ಮತ್ತು ವಂಚನೆ ಪರಿಶೀಲನೆಗಳ ಬಗ್ಗೆ ನಾನು ಸಹಾಯ ಮಾಡಬಲ್ಲೆ.",
    "I also know your case: {0}.": "ನಿಮ್ಮ ಪ್ರಕರಣದ ವಿವರವೂ ನನಗೆ ಗೊತ್ತು: {0}.",
    "I can answer questions about:\n• The step-by-step buying procedure\n• Required documents and what each one means\n• Stamp duty and registration charges\n• Which government office handles what\n• Fraud warning signs and how to check them\n\nTry asking it in plain words — for example, \"who do I meet first\" or \"is my land record too old\".": "ಇವುಗಳ ಬಗ್ಗೆ ನಾನು ಉತ್ತರಿಸಬಲ್ಲೆ:\n• ಹಂತ ಹಂತದ ಖರೀದಿ ಕಾರ್ಯವಿಧಾನ\n• ಬೇಕಾದ ದಾಖಲೆಗಳು ಮತ್ತು ಪ್ರತಿಯೊಂದರ ಅರ್ಥ\n• ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಮತ್ತು ನೋಂದಣಿ ಶುಲ್ಕ\n• ಯಾವ ಸರ್ಕಾರಿ ಕಚೇರಿ ಯಾವುದನ್ನು ನೋಡಿಕೊಳ್ಳುತ್ತದೆ\n• ವಂಚನೆಯ ಎಚ್ಚರಿಕೆ ಸೂಚನೆಗಳು ಮತ್ತು ಅವುಗಳನ್ನು ಪರಿಶೀಲಿಸುವ ಬಗೆ\n\nಸರಳ ಮಾತಿನಲ್ಲಿ ಕೇಳಿ — ಉದಾಹರಣೆಗೆ, \"ಮೊದಲು ಯಾರನ್ನು ಭೇಟಿ ಮಾಡಬೇಕು\" ಅಥವಾ \"ನನ್ನ ಭೂ ದಾಖಲೆ ತುಂಬಾ ಹಳೆಯದೇ\".",
    "In {0} the land record is called the {1}, issued by the {2}.\n\nIt tells you four things: who currently holds the land, the area, the tenure type, and — in the \"other rights\" column — any bank loan or dispute noted against it.\n\nHow to get it: download it from your state's land records portal, or apply at the {2}. It costs roughly ₹15 to ₹100.\n\nOne rule worth following: never accept an extract older than three months. Entries change.": "{0} ರಾಜ್ಯದಲ್ಲಿ ಭೂ ದಾಖಲೆಯನ್ನು {1} ಎಂದು ಕರೆಯುತ್ತಾರೆ, ಇದನ್ನು {2} ನೀಡುತ್ತದೆ.\n\nಅದು ನಾಲ್ಕು ವಿಷಯಗಳನ್ನು ತಿಳಿಸುತ್ತದೆ: ಪ್ರಸ್ತುತ ಭೂಮಿ ಯಾರ ಹಿಡುವಳಿಯಲ್ಲಿದೆ, ವಿಸ್ತೀರ್ಣ, ಹಿಡುವಳಿ ಪ್ರಕಾರ, ಮತ್ತು — \"ಇತರ ಹಕ್ಕುಗಳು\" ಕಾಲಂನಲ್ಲಿ — ಅದರ ಮೇಲೆ ನಮೂದಾಗಿರುವ ಬ್ಯಾಂಕ್ ಸಾಲ ಅಥವಾ ವಿವಾದ.\n\nಪಡೆಯುವ ಬಗೆ: ನಿಮ್ಮ ರಾಜ್ಯದ ಭೂ ದಾಖಲೆ ಪೋರ್ಟಲ್‌ನಿಂದ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ, ಅಥವಾ {2} ನಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ. ಇದಕ್ಕೆ ಸುಮಾರು ₹15 ರಿಂದ ₹100 ಖರ್ಚಾಗುತ್ತದೆ.\n\nಪಾಲಿಸಬೇಕಾದ ಒಂದು ನಿಯಮ: ಮೂರು ತಿಂಗಳಿಗಿಂತ ಹಳೆಯದಾದ ಉತಾರವನ್ನು ಎಂದಿಗೂ ಒಪ್ಪಬೇಡಿ. ನಮೂದುಗಳು ಬದಲಾಗುತ್ತಿರುತ್ತವೆ.",
    "PAN is mandatory for property transactions above ₹5 lakh, for both parties.\n\nAadhaar is used for identity verification and biometrics at the Sub-Registrar office. In practice you will not get through registration without it, though the strict legal position varies by state.\n\nCarry originals plus two photocopies of each, for both buyer and seller.": "₹5 ಲಕ್ಷಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಆಸ್ತಿ ವ್ಯವಹಾರಗಳಿಗೆ ಎರಡೂ ಪಕ್ಷಗಳಿಗೂ PAN ಕಡ್ಡಾಯ.\n\nಉಪ-ನೋಂದಣಾಧಿಕಾರಿ ಕಚೇರಿಯಲ್ಲಿ ಗುರುತಿನ ಪರಿಶೀಲನೆ ಮತ್ತು ಬಯೋಮೆಟ್ರಿಕ್‌ಗಾಗಿ Aadhaar ಬಳಸಲಾಗುತ್ತದೆ. ಕಾನೂನಿನ ಕಟ್ಟುನಿಟ್ಟಿನ ನಿಲುವು ರಾಜ್ಯದಿಂದ ರಾಜ್ಯಕ್ಕೆ ಬೇರೆಯಾದರೂ, ವಾಸ್ತವದಲ್ಲಿ ಅದಿಲ್ಲದೆ ನೋಂದಣಿ ಮುಗಿಯುವುದಿಲ್ಲ.\n\nಖರೀದಿದಾರ ಮತ್ತು ಮಾರಾಟಗಾರ ಇಬ್ಬರೂ ಪ್ರತಿಯೊಂದರ ಮೂಲ ಪ್ರತಿಯ ಜೊತೆಗೆ ಎರಡು ನಕಲು ಪ್ರತಿಗಳನ್ನು ತೆಗೆದುಕೊಂಡು ಹೋಗಿ.",
    "Partly. Most states let you download the land record extract and pay stamp duty online, and many publish encumbrance details on the registration portal.\n\nWhat still needs you in person: the registration appointment itself. Both parties and two witnesses have to appear at the Sub-Registrar office for biometrics and photographs.\n\nSo: do the research online, then book one office visit for registration.": "ಭಾಗಶಃ. ಹೆಚ್ಚಿನ ರಾಜ್ಯಗಳಲ್ಲಿ ಭೂ ದಾಖಲೆ ಉತಾರವನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಬಹುದು ಮತ್ತು ಮುದ್ರಾಂಕ ಶುಲ್ಕವನ್ನು ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಪಾವತಿಸಬಹುದು; ಹಲವು ರಾಜ್ಯಗಳು ನೋಂದಣಿ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಋಣಭಾರದ ವಿವರಗಳನ್ನೂ ಪ್ರಕಟಿಸುತ್ತವೆ.\n\nಇನ್ನೂ ಖುದ್ದಾಗಿ ಹೋಗಬೇಕಾದದ್ದು: ನೋಂದಣಿಯ ಭೇಟಿ. ಬಯೋಮೆಟ್ರಿಕ್ ಮತ್ತು ಫೋಟೋಗಾಗಿ ಎರಡೂ ಪಕ್ಷಗಳು ಮತ್ತು ಇಬ್ಬರು ಸಾಕ್ಷಿಗಳು ಉಪ-ನೋಂದಣಾಧಿಕಾರಿ ಕಚೇರಿಗೆ ಹಾಜರಾಗಲೇಬೇಕು.\n\nಹಾಗಾಗಿ: ಪರಿಶೀಲನೆಯನ್ನೆಲ್ಲ ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಮುಗಿಸಿ, ನಂತರ ನೋಂದಣಿಗಾಗಿ ಒಂದೇ ಕಚೇರಿ ಭೇಟಿಯನ್ನು ನಿಗದಿಪಡಿಸಿ.",
    "Stamp duty in most states is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "ಹೆಚ್ಚಿನ ರಾಜ್ಯಗಳಲ್ಲಿ ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಆಸ್ತಿ ಮೌಲ್ಯದ ಸುಮಾರು {1}% ಇರುತ್ತದೆ, ಮತ್ತು ನೋಂದಣಿ ಶುಲ್ಕ {2}%{3} ಇರುತ್ತದೆ.\n\nಜನರು ತಪ್ಪು ಮಾಡುವ ಮೂರು ವಿಷಯಗಳು:\n1. ನಿಮ್ಮ ಒಪ್ಪಂದದ ಮೌಲ್ಯ ಮತ್ತು ಸರ್ಕಾರಿ ಸರ್ಕಲ್ ದರ — ಇವುಗಳಲ್ಲಿ ಹೆಚ್ಚಿನದರ ಮೇಲೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುತ್ತದೆ, ನೀವು ನಿಜವಾಗಿ ಕೊಟ್ಟ ಮೊತ್ತದ ಮೇಲಲ್ಲ.\n2. {4}\n3. ನೋಂದಣಿಗೂ ಮೊದಲು ಅದನ್ನು ಪಾವತಿಸಿ ಮತ್ತು ಇ-ಸ್ಟಾಂಪ್ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಕಚೇರಿಗೆ ತೆಗೆದುಕೊಂಡು ಹೋಗಿ.\n\nನಿಮ್ಮ ಆಸ್ತಿ ಮೌಲ್ಯಕ್ಕೆ ನಿರ್ದಿಷ್ಟ ಅಂಕಿ ಪಡೆಯಲು ಶುಲ್ಕಗಳು ಪುಟವನ್ನು ಬಳಸಿ.",
    "Stamp duty in {0} is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "{0} ರಾಜ್ಯದಲ್ಲಿ ಮುದ್ರಾಂಕ ಶುಲ್ಕ ಆಸ್ತಿ ಮೌಲ್ಯದ ಸುಮಾರು {1}% ಇರುತ್ತದೆ, ಮತ್ತು ನೋಂದಣಿ ಶುಲ್ಕ {2}%{3} ಇರುತ್ತದೆ.\n\nಜನರು ತಪ್ಪು ಮಾಡುವ ಮೂರು ವಿಷಯಗಳು:\n1. ನಿಮ್ಮ ಒಪ್ಪಂದದ ಮೌಲ್ಯ ಮತ್ತು ಸರ್ಕಾರಿ ಸರ್ಕಲ್ ದರ — ಇವುಗಳಲ್ಲಿ ಹೆಚ್ಚಿನದರ ಮೇಲೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುತ್ತದೆ, ನೀವು ನಿಜವಾಗಿ ಕೊಟ್ಟ ಮೊತ್ತದ ಮೇಲಲ್ಲ.\n2. {4}\n3. ನೋಂದಣಿಗೂ ಮೊದಲು ಅದನ್ನು ಪಾವತಿಸಿ ಮತ್ತು ಇ-ಸ್ಟಾಂಪ್ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಕಚೇರಿಗೆ ತೆಗೆದುಕೊಂಡು ಹೋಗಿ.\n\nನಿಮ್ಮ ಆಸ್ತಿ ಮೌಲ್ಯಕ್ಕೆ ನಿರ್ದಿಷ್ಟ ಅಂಕಿ ಪಡೆಯಲು ಶುಲ್ಕಗಳು ಪುಟವನ್ನು ಬಳಸಿ.",
    "Start with the {0} from the {1} — the name on that record is the legal holder. Then:\n\n• Match that name against the seller's Aadhaar or PAN, letter for letter.\n• Ask for the previous title deeds and read the chain backwards for at least 30 years.\n• Pull the encumbrance certificate from the Sub-Registrar office to see every registered transaction.\n• If someone is selling on the owner's behalf, ask for a registered power of attorney and check it is still valid.\n\nIf the seller resists any of this, treat it as a warning sign, not an inconvenience.": "{1} ನಿಂದ {0} ಪಡೆಯುವುದರಿಂದ ಆರಂಭಿಸಿ — ಆ ದಾಖಲೆಯಲ್ಲಿರುವ ಹೆಸರೇ ಕಾನೂನುಬದ್ಧ ಹಿಡುವಳಿದಾರರದು. ನಂತರ:\n\n• ಆ ಹೆಸರನ್ನು ಮಾರಾಟಗಾರರ Aadhaar ಅಥವಾ PAN ಜೊತೆ ಅಕ್ಷರಶಃ ತಾಳೆ ನೋಡಿ.\n• ಹಿಂದಿನ ಹಕ್ಕುಪತ್ರಗಳನ್ನು ಕೇಳಿ ಪಡೆದು ಕನಿಷ್ಠ 30 ವರ್ಷಗಳಷ್ಟು ಹಿಂದಕ್ಕೆ ಸರಪಳಿಯನ್ನು ಓದಿ.\n• ನೋಂದಾಯಿತ ಪ್ರತಿಯೊಂದು ವ್ಯವಹಾರವನ್ನೂ ನೋಡಲು ಉಪ-ನೋಂದಣಾಧಿಕಾರಿ ಕಚೇರಿಯಿಂದ ಋಣಭಾರ ಪ್ರಮಾಣಪತ್ರ ಪಡೆಯಿರಿ.\n• ಮಾಲೀಕರ ಪರವಾಗಿ ಬೇರೊಬ್ಬರು ಮಾರುತ್ತಿದ್ದರೆ, ನೋಂದಾಯಿತ ಮುಖ್ತ್ಯಾರ್ ನಾಮೆ ಕೇಳಿ ಮತ್ತು ಅದು ಈಗಲೂ ಜಾರಿಯಲ್ಲಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ.\n\nಮಾರಾಟಗಾರರು ಇದರಲ್ಲಿ ಯಾವುದಕ್ಕೂ ಸತಾಯಿಸಿದರೆ, ಅದನ್ನು ಸಣ್ಣ ತೊಂದರೆ ಎಂದು ಭಾವಿಸಬೇಡಿ — ಎಚ್ಚರಿಕೆಯ ಸೂಚನೆ ಎಂದು ತಿಳಿಯಿರಿ.",
    "The patterns that catch most buyers:\n\n• The seller is not the recorded owner, or sells through an unregistered power of attorney.\n• The same land is sold to two buyers — visible in the encumbrance certificate.\n• A pending court case that never appears in the documents shown to you.\n• Farmland sold as plots without an NA conversion order.\n• Heavy pressure to pay in cash, quickly, \"before someone else takes it\".\n\nVerify the survey number through the official land records portal, and never pay in cash.": "ಹೆಚ್ಚಿನ ಖರೀದಿದಾರರು ಸಿಕ್ಕಿಬೀಳುವ ಮಾದರಿಗಳು:\n\n• ಮಾರಾಟಗಾರರು ದಾಖಲೆಯಲ್ಲಿರುವ ಮಾಲೀಕರಲ್ಲ, ಅಥವಾ ನೋಂದಣಿಯಾಗದ ಮುಖ್ತ್ಯಾರ್ ನಾಮೆ ಮೂಲಕ ಮಾರುತ್ತಿದ್ದಾರೆ.\n• ಒಂದೇ ಭೂಮಿಯನ್ನು ಇಬ್ಬರು ಖರೀದಿದಾರರಿಗೆ ಮಾರಾಟ ಮಾಡುವುದು — ಇದು ಋಣಭಾರ ಪ್ರಮಾಣಪತ್ರದಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.\n• ನಿಮಗೆ ತೋರಿಸಿದ ದಾಖಲೆಗಳಲ್ಲಿ ಎಲ್ಲಿಯೂ ಕಾಣದ ಬಾಕಿ ಇರುವ ನ್ಯಾಯಾಲಯ ಪ್ರಕರಣ.\n• NA ಪರಿವರ್ತನಾ ಆದೇಶವಿಲ್ಲದೆ ಕೃಷಿ ಭೂಮಿಯನ್ನು ನಿವೇಶನಗಳಾಗಿ ಮಾರುವುದು.\n• \"ಬೇರೆಯವರು ತೆಗೆದುಕೊಳ್ಳುವ ಮೊದಲು\" ಎಂದು ಬೇಗ ನಗದು ಕೊಡುವಂತೆ ತೀವ್ರ ಒತ್ತಡ ಹಾಕುವುದು.\n\nಸರ್ವೆ ಸಂಖ್ಯೆಯನ್ನು ಅಧಿಕೃತ ಭೂ ದಾಖಲೆ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಪರಿಶೀಲಿಸಿ, ಮತ್ತು ಎಂದಿಗೂ ನಗದು ಪಾವತಿ ಮಾಡಬೇಡಿ.",
    "There is no female-buyer rebate in this state.": "ಈ ರಾಜ್ಯದಲ್ಲಿ ಮಹಿಳಾ ಖರೀದಿದಾರರಿಗೆ ಯಾವುದೇ ರಿಯಾಯಿತಿ ಇಲ್ಲ.",
    "Tip: select your state and district at the top so I can answer for your district instead of generally.": "ಸಲಹೆ: ಸಾಮಾನ್ಯ ಉತ್ತರದ ಬದಲು ನಿಮ್ಮ ಜಿಲ್ಲೆಗೆ ತಕ್ಕ ಉತ್ತರ ಸಿಗಬೇಕಾದರೆ, ಮೇಲ್ಭಾಗದಲ್ಲಿ ನಿಮ್ಮ ರಾಜ್ಯ ಮತ್ತು ಜಿಲ್ಲೆಯನ್ನು ಆಯ್ಕೆ ಮಾಡಿ.",
    "You will deal with these offices:\n\n• {0} — land record extract, mutation, heir certificates\n• Sub-Registrar Office — sale deed registration, encumbrance certificate\n• Collector Office — NA conversion and appeals\n• Municipal body or Gram Panchayat — property tax and layout approval\n\nThe Land Buying page shows the actual addresses, working hours and distance for {1}, so you do not travel to the wrong counter.": "ನೀವು ಈ ಕಚೇರಿಗಳೊಂದಿಗೆ ವ್ಯವಹರಿಸಬೇಕಾಗುತ್ತದೆ:\n\n• {0} — ಭೂ ದಾಖಲೆ ಉತಾರ, ಖಾತಾ ಬದಲಾವಣೆ, ವಾರಸುದಾರ ಪ್ರಮಾಣಪತ್ರಗಳು\n• ಉಪ-ನೋಂದಣಾಧಿಕಾರಿ ಕಚೇರಿ — ಕ್ರಯಪತ್ರ ನೋಂದಣಿ, ಋಣಭಾರ ಪ್ರಮಾಣಪತ್ರ\n• ಜಿಲ್ಲಾಧಿಕಾರಿ ಕಚೇರಿ — NA ಪರಿವರ್ತನೆ ಮತ್ತು ಮೇಲ್ಮನವಿಗಳು\n• ಪಾಲಿಕೆ ಅಥವಾ ಗ್ರಾಮ ಪಂಚಾಯಿತಿ — ಆಸ್ತಿ ತೆರಿಗೆ ಮತ್ತು ಲೇಔಟ್ ಅನುಮೋದನೆ\n\nನೀವು ತಪ್ಪು ಕೌಂಟರ್‌ಗೆ ಅಲೆದಾಡದಂತೆ, {1} ಗೆ ಸಂಬಂಧಿಸಿದ ನಿಜವಾದ ವಿಳಾಸಗಳು, ಕೆಲಸದ ಸಮಯ ಮತ್ತು ದೂರವನ್ನು ಭೂಮಿ ಖರೀದಿ ಪುಟ ತೋರಿಸುತ್ತದೆ.",
    "your state": "ನಿಮ್ಮ ರಾಜ್ಯ",
    "your taluka": "ನಿಮ್ಮ ತಾಲೂಕು",
  },
  gu: {
    "A clean purchase usually runs 30 to 45 days end to end:\n\n• Ownership and record checks — 2 to 5 days\n• Encumbrance certificate — 1 to 3 days\n• Agreement to sale — 1 day\n• Stamp duty payment — 1 day\n• Registration — 1 to 2 days\n• Mutation — 15 to 30 days\n\nMutation is the long tail. Registration makes you the owner; mutation just updates the revenue record afterwards.": "સ્વચ્છ સોદો સામાન્ય રીતે શરૂથી અંત સુધી 30 થી 45 દિવસ લે છે:\n\n• માલિકી અને રેકોર્ડની ચકાસણી — 2 થી 5 દિવસ\n• એન્કમ્બ્રન્સ સર્ટિફિકેટ — 1 થી 3 દિવસ\n• વેચાણ કરાર — 1 દિવસ\n• સ્ટેમ્પ ડ્યુટીની ચુકવણી — 1 દિવસ\n• નોંધણી — 1 થી 2 દિવસ\n• નોંધ (મ્યુટેશન) — 15 થી 30 દિવસ\n\nસૌથી લાંબો સમય નોંધ (મ્યુટેશન) લે છે. નોંધણીથી તમે માલિક બની જાવ છો; નોંધ તો પછી માત્ર મહેસૂલ રેકોર્ડ અપડેટ કરે છે.",
    "A female buyer gets roughly {0}% less duty here.": "અહીં મહિલા ખરીદનારને આશરે {0}% ઓછી ડ્યુટી લાગે છે.",
    "Agricultural land has extra rules:\n\n• Several states allow only an existing farmer to buy farmland — check whether {0} restricts this.\n• The tenure class on the {1} matters. Restricted tenure needs Collector permission to sell.\n• To build a house or shop you need an NA (non-agricultural) conversion order from the Collector — 30 to 90 days.\n• Ceiling limits cap how much agricultural land one family can hold.\n\nRun the Smart Procedure Generator on the Land Buying page — it adds the conversion step automatically when you say you plan to build.": "ખેતીની જમીન માટે વધારાના નિયમો છે:\n\n• ઘણાં રાજ્યોમાં ખેતીની જમીન માત્ર પહેલેથી ખેડૂત હોય તે જ ખરીદી શકે છે — {0}માં આવો પ્રતિબંધ છે કે નહીં તે તપાસો.\n• {1}માં દર્શાવેલો ટેન્યોર વર્ગ મહત્ત્વનો છે. પ્રતિબંધિત ટેન્યોરવાળી જમીન વેચવા કલેક્ટરની પરવાનગી જોઈએ.\n• ઘર કે દુકાન બાંધવી હોય તો કલેક્ટર પાસેથી NA (બિનખેતી) રૂપાંતરણ હુકમ લેવો પડે — 30 થી 90 દિવસ.\n• ટોચમર્યાદાના કાયદા નક્કી કરે છે કે એક કુટુંબ કેટલી ખેતીની જમીન રાખી શકે.\n\nજમીન ખરીદી પાનાં પર સ્માર્ટ પ્રોસિજર જનરેટર ચલાવો — તમે બાંધકામનો ઇરાદો જણાવો કે તરત તે રૂપાંતરણનું પગલું આપમેળે ઉમેરી દે છે.",
    "Answering for {0}, {1}.": "{0}, {1} માટે જવાબ આપી રહ્યો છું.",
    "Answering for {0}.": "{0} માટે જવાબ આપી રહ્યો છું.",
    "Ask me something specific, like \"what documents do I need for agricultural land\" or \"how much is stamp duty here\".": "કંઈક ચોક્કસ પૂછો, જેમ કે \"ખેતીની જમીન માટે કયા દસ્તાવેજો જોઈએ\" અથવા \"અહીં સ્ટેમ્પ ડ્યુટી કેટલી થાય\".",
    "For a straightforward purchase you need:\n1. Registered sale deed\n2. {0} — the land record extract\n3. Encumbrance certificate for 13 to 30 years\n4. Previous title deeds (chain of ownership)\n5. Property tax receipt, up to date\n6. Aadhaar and PAN of both buyer and seller\n7. Passport photos and address proof\n\nExtra documents depend on the case: inherited land needs a legal heir certificate, farmland used for construction needs an NA order, and a company buyer needs a board resolution.\n\nOpen the Documents page to tick these off as you collect them.": "સીધા-સાદા સોદા માટે તમારે આટલું જોઈશે:\n1. નોંધાયેલો વેચાણ દસ્તાવેજ\n2. {0} — જમીન રેકોર્ડનો ઉતારો\n3. 13 થી 30 વર્ષનું એન્કમ્બ્રન્સ સર્ટિફિકેટ\n4. અગાઉના માલિકી દસ્તાવેજો (માલિકીની શૃંખલા)\n5. આજની તારીખ સુધી ભરેલી મિલકત વેરાની પહોંચ\n6. ખરીદનાર અને વેચનાર બંનેનાં Aadhaar અને PAN\n7. પાસપોર્ટ ફોટા અને સરનામાનો પુરાવો\n\nવધારાના દસ્તાવેજો કેસ પ્રમાણે બદલાય છે: વારસાગત જમીન માટે કાયદેસર વારસદાર પ્રમાણપત્ર, બાંધકામ માટે વપરાતી ખેતીની જમીન માટે NA હુકમ, અને ખરીદનાર કંપની હોય તો બોર્ડ ઠરાવ.\n\nજેમ જેમ ભેગા કરતા જાવ તેમ નિશાની કરવા દસ્તાવેજો પાનું ખોલો.",
    "Hello. I can help with land buying procedure, required documents, stamp duty, government offices, and fraud checks.": "નમસ્તે. જમીન ખરીદીની પ્રક્રિયા, જરૂરી દસ્તાવેજો, સ્ટેમ્પ ડ્યુટી, સરકારી કચેરીઓ અને છેતરપિંડીની ચકાસણીમાં હું મદદ કરી શકું છું.",
    "I also know your case: {0}.": "તમારા કેસની વિગત પણ મને ખબર છે: {0}.",
    "I can answer questions about:\n• The step-by-step buying procedure\n• Required documents and what each one means\n• Stamp duty and registration charges\n• Which government office handles what\n• Fraud warning signs and how to check them\n\nTry asking it in plain words — for example, \"who do I meet first\" or \"is my land record too old\".": "હું આ બાબતોના જવાબ આપી શકું:\n• પગલાં-વાર ખરીદીની પ્રક્રિયા\n• જરૂરી દસ્તાવેજો અને દરેકનો અર્થ\n• સ્ટેમ્પ ડ્યુટી અને નોંધણી ખર્ચ\n• કઈ સરકારી કચેરી શું સંભાળે છે\n• છેતરપિંડીનાં ચેતવણી ચિહ્નો અને તેમને કેવી રીતે તપાસવાં\n\nસાદી ભાષામાં પૂછો — દાખલા તરીકે, \"પહેલાં કોને મળવું\" કે \"મારો જમીન રેકોર્ડ બહુ જૂનો છે કે કેમ\".",
    "In {0} the land record is called the {1}, issued by the {2}.\n\nIt tells you four things: who currently holds the land, the area, the tenure type, and — in the \"other rights\" column — any bank loan or dispute noted against it.\n\nHow to get it: download it from your state's land records portal, or apply at the {2}. It costs roughly ₹15 to ₹100.\n\nOne rule worth following: never accept an extract older than three months. Entries change.": "{0}માં જમીન રેકોર્ડને {1} કહેવાય છે, જે {2} આપે છે.\n\nતે ચાર વાત જણાવે છે: હાલમાં જમીન કોના કબજામાં છે, ક્ષેત્રફળ, ટેન્યોરનો પ્રકાર, અને — \"અન્ય હક્કો\"ની કોલમમાં — તેની સામે નોંધાયેલી કોઈ બેંક લોન કે વિવાદ.\n\nકેવી રીતે મેળવવો: તમારા રાજ્યના જમીન રેકોર્ડ પોર્ટલ પરથી ડાઉનલોડ કરો, અથવા {2}માં અરજી કરો. ખર્ચ આશરે ₹15 થી ₹100 થાય છે.\n\nએક નિયમ પાળવા જેવો: ત્રણ મહિનાથી જૂનો ઉતારો કદી સ્વીકારશો નહીં. નોંધો બદલાતી રહે છે.",
    "PAN is mandatory for property transactions above ₹5 lakh, for both parties.\n\nAadhaar is used for identity verification and biometrics at the Sub-Registrar office. In practice you will not get through registration without it, though the strict legal position varies by state.\n\nCarry originals plus two photocopies of each, for both buyer and seller.": "₹5 લાખથી વધુની મિલકતના વ્યવહારમાં બંને પક્ષ માટે PAN ફરજિયાત છે.\n\nસબ-રજિસ્ટ્રાર કચેરીમાં ઓળખની ચકાસણી અને બાયોમેટ્રિક માટે Aadhaar વપરાય છે. કાયદાની કડક સ્થિતિ રાજ્યે રાજ્યે જુદી હોય, પણ વ્યવહારમાં તેના વગર નોંધણી પાર પડતી નથી.\n\nખરીદનાર અને વેચનાર બંને દરેક દસ્તાવેજની મૂળ નકલ સાથે બે ઝેરોક્ષ નકલ લઈ જાવ.",
    "Partly. Most states let you download the land record extract and pay stamp duty online, and many publish encumbrance details on the registration portal.\n\nWhat still needs you in person: the registration appointment itself. Both parties and two witnesses have to appear at the Sub-Registrar office for biometrics and photographs.\n\nSo: do the research online, then book one office visit for registration.": "થોડે અંશે. મોટા ભાગનાં રાજ્યોમાં જમીન રેકોર્ડનો ઉતારો ડાઉનલોડ કરી શકાય અને સ્ટેમ્પ ડ્યુટી ઓનલાઇન ભરી શકાય; ઘણાં રાજ્યો નોંધણી પોર્ટલ પર બોજાની વિગતો પણ મૂકે છે.\n\nજેમાં હજુ રૂબરૂ જવું પડે તે છે: નોંધણીની મુલાકાત. બાયોમેટ્રિક અને ફોટા માટે બંને પક્ષ અને બે સાક્ષીઓએ સબ-રજિસ્ટ્રાર કચેરીમાં હાજર રહેવું જ પડે.\n\nએટલે: તપાસ ઓનલાઇન પતાવો, અને પછી નોંધણી માટે એક જ કચેરી-મુલાકાત ગોઠવો.",
    "Stamp duty in most states is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "મોટા ભાગનાં રાજ્યોમાં સ્ટેમ્પ ડ્યુટી મિલકતના મૂલ્યના આશરે {1}% હોય છે, અને નોંધણી ફી {2}%{3} હોય છે.\n\nલોકો ત્રણ બાબતોમાં થાપ ખાય છે:\n1. ડ્યુટી તમારા કરાર મૂલ્ય અને સરકારી સર્કલ રેટમાંથી જે વધારે હોય તેના પર લાગે છે — તમે ખરેખર જે ચૂકવ્યું તેના પર નહીં.\n2. {4}\n3. નોંધણી પહેલાં તે ભરી દો અને ઈ-સ્ટેમ્પ સર્ટિફિકેટ કચેરીએ સાથે લઈ જાવ.\n\nતમારી મિલકતના મૂલ્ય માટે ચોક્કસ આંકડો મેળવવા ખર્ચ પાનું વાપરો.",
    "Stamp duty in {0} is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "{0}માં સ્ટેમ્પ ડ્યુટી મિલકતના મૂલ્યના આશરે {1}% હોય છે, અને નોંધણી ફી {2}%{3} હોય છે.\n\nલોકો ત્રણ બાબતોમાં થાપ ખાય છે:\n1. ડ્યુટી તમારા કરાર મૂલ્ય અને સરકારી સર્કલ રેટમાંથી જે વધારે હોય તેના પર લાગે છે — તમે ખરેખર જે ચૂકવ્યું તેના પર નહીં.\n2. {4}\n3. નોંધણી પહેલાં તે ભરી દો અને ઈ-સ્ટેમ્પ સર્ટિફિકેટ કચેરીએ સાથે લઈ જાવ.\n\nતમારી મિલકતના મૂલ્ય માટે ચોક્કસ આંકડો મેળવવા ખર્ચ પાનું વાપરો.",
    "Start with the {0} from the {1} — the name on that record is the legal holder. Then:\n\n• Match that name against the seller's Aadhaar or PAN, letter for letter.\n• Ask for the previous title deeds and read the chain backwards for at least 30 years.\n• Pull the encumbrance certificate from the Sub-Registrar office to see every registered transaction.\n• If someone is selling on the owner's behalf, ask for a registered power of attorney and check it is still valid.\n\nIf the seller resists any of this, treat it as a warning sign, not an inconvenience.": "{1}માંથી {0} મેળવવાથી શરૂઆત કરો — તે રેકોર્ડમાં જે નામ હોય તે જ કાયદેસર ધારક છે. પછી:\n\n• એ નામને વેચનારના Aadhaar કે PAN સાથે અક્ષરે અક્ષર મેળવો.\n• અગાઉના માલિકી દસ્તાવેજો માગો અને ઓછામાં ઓછાં 30 વર્ષ પાછળ સુધી શૃંખલા વાંચો.\n• દરેક નોંધાયેલો વ્યવહાર જોવા સબ-રજિસ્ટ્રાર કચેરીમાંથી એન્કમ્બ્રન્સ સર્ટિફિકેટ કઢાવો.\n• કોઈ માલિક વતી વેચતું હોય તો નોંધાયેલ પાવર ઑફ એટર્ની માગો અને તે હજી અમલમાં છે કે નહીં તે ચકાસો.\n\nવેચનાર આમાંથી કશામાં આનાકાની કરે, તો તેને નાની અગવડ નહીં — ચેતવણીનું ચિહ્ન ગણો.",
    "The patterns that catch most buyers:\n\n• The seller is not the recorded owner, or sells through an unregistered power of attorney.\n• The same land is sold to two buyers — visible in the encumbrance certificate.\n• A pending court case that never appears in the documents shown to you.\n• Farmland sold as plots without an NA conversion order.\n• Heavy pressure to pay in cash, quickly, \"before someone else takes it\".\n\nVerify the survey number through the official land records portal, and never pay in cash.": "મોટા ભાગના ખરીદનારા આ જ જાળમાં ફસાય છે:\n\n• વેચનાર રેકોર્ડ પરનો માલિક નથી, અથવા બિનનોંધાયેલ પાવર ઑફ એટર્ની દ્વારા વેચે છે.\n• એક જ જમીન બે ખરીદનારને વેચી દેવાય છે — એન્કમ્બ્રન્સ સર્ટિફિકેટમાં તે દેખાય છે.\n• કોર્ટમાં ચાલતો કેસ, જે તમને બતાવેલા દસ્તાવેજોમાં ક્યાંય દેખાતો નથી.\n• NA રૂપાંતરણ હુકમ વગર ખેતીની જમીન પ્લોટ તરીકે વેચવી.\n• \"બીજું કોઈ લઈ જાય તે પહેલાં\" કહીને રોકડમાં ઝડપથી ચૂકવવાનું ભારે દબાણ.\n\nસર્વે નંબર સત્તાવાર જમીન રેકોર્ડ પોર્ટલ પરથી ચકાસો, અને કદી રોકડમાં ચુકવણી ન કરો.",
    "There is no female-buyer rebate in this state.": "આ રાજ્યમાં મહિલા ખરીદનાર માટે કોઈ રાહત નથી.",
    "Tip: select your state and district at the top so I can answer for your district instead of generally.": "સૂચન: ઉપરથી તમારું રાજ્ય અને જિલ્લો પસંદ કરો, જેથી હું સામાન્ય જવાબને બદલે તમારા જિલ્લા પ્રમાણે જવાબ આપી શકું.",
    "You will deal with these offices:\n\n• {0} — land record extract, mutation, heir certificates\n• Sub-Registrar Office — sale deed registration, encumbrance certificate\n• Collector Office — NA conversion and appeals\n• Municipal body or Gram Panchayat — property tax and layout approval\n\nThe Land Buying page shows the actual addresses, working hours and distance for {1}, so you do not travel to the wrong counter.": "તમારે આ કચેરીઓ સાથે કામ પડશે:\n\n• {0} — જમીન રેકોર્ડનો ઉતારો, નોંધ (મ્યુટેશન), વારસદાર પ્રમાણપત્રો\n• સબ-રજિસ્ટ્રાર કચેરી — વેચાણ દસ્તાવેજની નોંધણી, એન્કમ્બ્રન્સ સર્ટિફિકેટ\n• કલેક્ટર કચેરી — NA રૂપાંતરણ અને અપીલ\n• નગરપાલિકા કે ગ્રામ પંચાયત — મિલકત વેરો અને લેઆઉટ મંજૂરી\n\nતમે ખોટા કાઉન્ટરે ધક્કો ન ખાવ તે માટે જમીન ખરીદી પાનું {1} માટેનાં સાચાં સરનામાં, કામકાજના કલાકો અને અંતર બતાવે છે.",
    "your state": "તમારું રાજ્ય",
    "your taluka": "તમારો તાલુકો",
  },
  bn: {
    "A clean purchase usually runs 30 to 45 days end to end:\n\n• Ownership and record checks — 2 to 5 days\n• Encumbrance certificate — 1 to 3 days\n• Agreement to sale — 1 day\n• Stamp duty payment — 1 day\n• Registration — 1 to 2 days\n• Mutation — 15 to 30 days\n\nMutation is the long tail. Registration makes you the owner; mutation just updates the revenue record afterwards.": "পরিষ্কার একটা কেনাবেচা শুরু থেকে শেষ পর্যন্ত সাধারণত 30 থেকে 45 দিন নেয়:\n\n• মালিকানা ও রেকর্ড যাচাই — 2 থেকে 5 দিন\n• এনকাম্ব্রেন্স সার্টিফিকেট — 1 থেকে 3 দিন\n• বিক্রয় চুক্তি — 1 দিন\n• স্ট্যাম্প ডিউটি জমা — 1 দিন\n• রেজিস্ট্রেশন — 1 থেকে 2 দিন\n• মিউটেশন — 15 থেকে 30 দিন\n\nসবচেয়ে বেশি সময় নেয় মিউটেশন। রেজিস্ট্রেশনেই আপনি মালিক হয়ে যান; মিউটেশন তার পরে শুধু রাজস্ব রেকর্ডটা হালনাগাদ করে।",
    "A female buyer gets roughly {0}% less duty here.": "এখানে মহিলা ক্রেতার ক্ষেত্রে ডিউটি প্রায় {0}% কম লাগে।",
    "Agricultural land has extra rules:\n\n• Several states allow only an existing farmer to buy farmland — check whether {0} restricts this.\n• The tenure class on the {1} matters. Restricted tenure needs Collector permission to sell.\n• To build a house or shop you need an NA (non-agricultural) conversion order from the Collector — 30 to 90 days.\n• Ceiling limits cap how much agricultural land one family can hold.\n\nRun the Smart Procedure Generator on the Land Buying page — it adds the conversion step automatically when you say you plan to build.": "কৃষিজমির জন্য বাড়তি নিয়ম আছে:\n\n• বেশ কয়েকটি রাজ্যে কেবল আগে থেকে চাষি এমন কেউই কৃষিজমি কিনতে পারেন — {0}-তে এই নিষেধাজ্ঞা আছে কি না দেখে নিন।\n• {1}-তে লেখা স্বত্বের শ্রেণিটি গুরুত্বপূর্ণ। নিয়ন্ত্রিত স্বত্বের জমি বিক্রি করতে কালেক্টরের অনুমতি লাগে।\n• বাড়ি বা দোকান বানাতে হলে কালেক্টরের কাছ থেকে NA (অকৃষি) রূপান্তর আদেশ নিতে হয় — 30 থেকে 90 দিন।\n• সিলিং আইন ঠিক করে দেয় একটি পরিবার সর্বোচ্চ কত কৃষিজমি রাখতে পারে।\n\nজমি কেনা পাতায় স্মার্ট প্রসিডিওর জেনারেটর চালান — আপনি নির্মাণের পরিকল্পনার কথা বললেই সেটি রূপান্তরের ধাপটি নিজে থেকেই যোগ করে দেয়।",
    "Answering for {0}, {1}.": "{0}, {1}-এর জন্য উত্তর দেওয়া হচ্ছে।",
    "Answering for {0}.": "{0}-এর জন্য উত্তর দেওয়া হচ্ছে।",
    "Ask me something specific, like \"what documents do I need for agricultural land\" or \"how much is stamp duty here\".": "নির্দিষ্ট করে কিছু জিজ্ঞাসা করুন, যেমন \"কৃষিজমির জন্য কী কী নথি লাগে\" বা \"এখানে স্ট্যাম্প ডিউটি কত\"।",
    "For a straightforward purchase you need:\n1. Registered sale deed\n2. {0} — the land record extract\n3. Encumbrance certificate for 13 to 30 years\n4. Previous title deeds (chain of ownership)\n5. Property tax receipt, up to date\n6. Aadhaar and PAN of both buyer and seller\n7. Passport photos and address proof\n\nExtra documents depend on the case: inherited land needs a legal heir certificate, farmland used for construction needs an NA order, and a company buyer needs a board resolution.\n\nOpen the Documents page to tick these off as you collect them.": "সাদামাটা একটা কেনাবেচার জন্য আপনার লাগবে:\n1. রেজিস্টার্ড বিক্রয় দলিল\n2. {0} — জমির রেকর্ডের নকল\n3. 13 থেকে 30 বছরের এনকাম্ব্রেন্স সার্টিফিকেট\n4. আগের স্বত্ব দলিল (মালিকানার ধারাবাহিকতা)\n5. হালনাগাদ সম্পত্তি করের রসিদ\n6. ক্রেতা ও বিক্রেতা দুজনেরই Aadhaar ও PAN\n7. পাসপোর্ট ছবি ও ঠিকানার প্রমাণ\n\nবাড়তি নথি নির্ভর করে ক্ষেত্রবিশেষের উপর: উত্তরাধিকারসূত্রে পাওয়া জমির জন্য আইনি উত্তরাধিকার শংসাপত্র, নির্মাণের কাজে লাগানো কৃষিজমির জন্য NA আদেশ, আর ক্রেতা কোনও কোম্পানি হলে বোর্ড রেজোলিউশন।\n\nযোগাড় করতে করতে টিক দিয়ে রাখতে নথিপত্র পাতাটি খুলুন।",
    "Hello. I can help with land buying procedure, required documents, stamp duty, government offices, and fraud checks.": "নমস্কার। জমি কেনার পদ্ধতি, প্রয়োজনীয় নথি, স্ট্যাম্প ডিউটি, সরকারি দপ্তর আর জালিয়াতি যাচাই — এসবে আমি সাহায্য করতে পারি।",
    "I also know your case: {0}.": "আপনার ক্ষেত্রটিও আমার জানা: {0}।",
    "I can answer questions about:\n• The step-by-step buying procedure\n• Required documents and what each one means\n• Stamp duty and registration charges\n• Which government office handles what\n• Fraud warning signs and how to check them\n\nTry asking it in plain words — for example, \"who do I meet first\" or \"is my land record too old\".": "আমি এসব নিয়ে উত্তর দিতে পারি:\n• ধাপে ধাপে জমি কেনার পদ্ধতি\n• প্রয়োজনীয় নথি এবং প্রতিটির মানে\n• স্ট্যাম্প ডিউটি ও রেজিস্ট্রেশন খরচ\n• কোন সরকারি দপ্তর কী দেখে\n• জালিয়াতির সতর্ক-সংকেত এবং সেগুলো যাচাইয়ের উপায়\n\nসহজ কথায় জিজ্ঞাসা করুন — যেমন, \"প্রথমে কার সঙ্গে দেখা করব\" বা \"আমার জমির রেকর্ড কি খুব পুরনো\"।",
    "In {0} the land record is called the {1}, issued by the {2}.\n\nIt tells you four things: who currently holds the land, the area, the tenure type, and — in the \"other rights\" column — any bank loan or dispute noted against it.\n\nHow to get it: download it from your state's land records portal, or apply at the {2}. It costs roughly ₹15 to ₹100.\n\nOne rule worth following: never accept an extract older than three months. Entries change.": "{0}-তে জমির রেকর্ডকে বলা হয় {1}, যা দেয় {2}।\n\nএটি চারটি জিনিস জানায়: এখন জমি কার দখলে, জমির পরিমাণ, স্বত্বের ধরন, এবং — \"অন্যান্য অধিকার\" কলামে — জমির বিরুদ্ধে লেখা কোনও ব্যাঙ্ক ঋণ বা বিবাদ।\n\nকীভাবে পাবেন: আপনার রাজ্যের জমির রেকর্ড পোর্টাল থেকে ডাউনলোড করুন, অথবা {2}-এ আবেদন করুন। খরচ পড়ে মোটামুটি ₹15 থেকে ₹100।\n\nএকটা নিয়ম মেনে চলা ভালো: তিন মাসের বেশি পুরনো নকল কখনও নেবেন না। রেকর্ডের এন্ট্রি বদলায়।",
    "PAN is mandatory for property transactions above ₹5 lakh, for both parties.\n\nAadhaar is used for identity verification and biometrics at the Sub-Registrar office. In practice you will not get through registration without it, though the strict legal position varies by state.\n\nCarry originals plus two photocopies of each, for both buyer and seller.": "₹5 লাখের বেশি সম্পত্তির লেনদেনে দুই পক্ষের জন্যই PAN বাধ্যতামূলক।\n\nসাব-রেজিস্ট্রার অফিসে পরিচয় যাচাই ও বায়োমেট্রিকের জন্য Aadhaar ব্যবহার হয়। কড়া আইনি অবস্থান রাজ্যভেদে আলাদা হলেও, বাস্তবে ওটা ছাড়া রেজিস্ট্রেশন পার হবে না।\n\nক্রেতা ও বিক্রেতা দুজনেরই প্রতিটির মূল কপির সঙ্গে দুটি করে ফটোকপি নিয়ে যান।",
    "Partly. Most states let you download the land record extract and pay stamp duty online, and many publish encumbrance details on the registration portal.\n\nWhat still needs you in person: the registration appointment itself. Both parties and two witnesses have to appear at the Sub-Registrar office for biometrics and photographs.\n\nSo: do the research online, then book one office visit for registration.": "আংশিকভাবে। বেশির ভাগ রাজ্যে জমির রেকর্ডের নকল ডাউনলোড করা আর স্ট্যাম্প ডিউটি অনলাইনে জমা দেওয়া যায়, আর অনেক রাজ্য রেজিস্ট্রেশন পোর্টালে দায়বদ্ধতার তথ্যও দেয়।\n\nএখনও সশরীরে যা করতে হয়: রেজিস্ট্রেশনের দিনটি। বায়োমেট্রিক ও ছবির জন্য দুই পক্ষ এবং দুজন সাক্ষীকে সাব-রেজিস্ট্রার অফিসে হাজির হতেই হবে।\n\nতাই: খোঁজখবরটা অনলাইনে সেরে নিন, তারপর রেজিস্ট্রেশনের জন্য একবারই অফিসে যাওয়ার দিন ঠিক করুন।",
    "Stamp duty in most states is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "বেশির ভাগ রাজ্যে স্ট্যাম্প ডিউটি সম্পত্তির মূল্যের প্রায় {1}%, আর রেজিস্ট্রেশন ফি {2}%{3}।\n\nতিনটি জায়গায় লোকে ভুল করে:\n1. আপনার চুক্তিমূল্য ও সরকারি সার্কেল রেটের মধ্যে যেটি বেশি, ডিউটি তার উপর ধার্য হয় — আপনি আসলে যা দিয়েছেন তার উপর নয়।\n2. {4}\n3. রেজিস্ট্রেশনের আগেই সেটি জমা দিন এবং ই-স্ট্যাম্প সার্টিফিকেট অফিসে সঙ্গে নিয়ে যান।\n\nআপনার সম্পত্তির মূল্যের জন্য নির্দিষ্ট অঙ্ক পেতে খরচ পাতাটি ব্যবহার করুন।",
    "Stamp duty in {0} is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "{0}-তে স্ট্যাম্প ডিউটি সম্পত্তির মূল্যের প্রায় {1}%, আর রেজিস্ট্রেশন ফি {2}%{3}।\n\nতিনটি জায়গায় লোকে ভুল করে:\n1. আপনার চুক্তিমূল্য ও সরকারি সার্কেল রেটের মধ্যে যেটি বেশি, ডিউটি তার উপর ধার্য হয় — আপনি আসলে যা দিয়েছেন তার উপর নয়।\n2. {4}\n3. রেজিস্ট্রেশনের আগেই সেটি জমা দিন এবং ই-স্ট্যাম্প সার্টিফিকেট অফিসে সঙ্গে নিয়ে যান।\n\nআপনার সম্পত্তির মূল্যের জন্য নির্দিষ্ট অঙ্ক পেতে খরচ পাতাটি ব্যবহার করুন।",
    "Start with the {0} from the {1} — the name on that record is the legal holder. Then:\n\n• Match that name against the seller's Aadhaar or PAN, letter for letter.\n• Ask for the previous title deeds and read the chain backwards for at least 30 years.\n• Pull the encumbrance certificate from the Sub-Registrar office to see every registered transaction.\n• If someone is selling on the owner's behalf, ask for a registered power of attorney and check it is still valid.\n\nIf the seller resists any of this, treat it as a warning sign, not an inconvenience.": "শুরু করুন {1}-এর {0} দিয়ে — ওই রেকর্ডে যে নাম আছে, তিনিই আইনি দখলদার। তারপর:\n\n• সেই নাম বিক্রেতার Aadhaar বা PAN-এর সঙ্গে অক্ষরে অক্ষরে মিলিয়ে নিন।\n• আগের স্বত্ব দলিল চেয়ে নিন এবং অন্তত 30 বছর পিছিয়ে ধারাবাহিকতাটা পড়ুন।\n• প্রতিটি রেজিস্টার্ড লেনদেন দেখতে সাব-রেজিস্ট্রার অফিস থেকে এনকাম্ব্রেন্স সার্টিফিকেট তুলুন।\n• কেউ মালিকের হয়ে বিক্রি করলে রেজিস্টার্ড পাওয়ার অফ অ্যাটর্নি চেয়ে নিন এবং সেটি এখনও বৈধ কি না দেখে নিন।\n\nবিক্রেতা এসবের কোনওটিতে গড়িমসি করলে সেটিকে ঝামেলা নয়, সতর্ক-সংকেত হিসেবেই ধরুন।",
    "The patterns that catch most buyers:\n\n• The seller is not the recorded owner, or sells through an unregistered power of attorney.\n• The same land is sold to two buyers — visible in the encumbrance certificate.\n• A pending court case that never appears in the documents shown to you.\n• Farmland sold as plots without an NA conversion order.\n• Heavy pressure to pay in cash, quickly, \"before someone else takes it\".\n\nVerify the survey number through the official land records portal, and never pay in cash.": "যে ছকে বেশির ভাগ ক্রেতা ধরা পড়েন:\n\n• বিক্রেতা রেকর্ডে থাকা মালিক নন, কিংবা অনিবন্ধিত পাওয়ার অফ অ্যাটর্নির জোরে বিক্রি করছেন।\n• একই জমি দুজন ক্রেতাকে বিক্রি — এনকাম্ব্রেন্স সার্টিফিকেটে তা ধরা পড়ে।\n• আদালতে ঝুলে থাকা মামলা, যা আপনাকে দেখানো নথিতে কোথাও নেই।\n• NA রূপান্তর আদেশ ছাড়াই কৃষিজমি প্লট করে বিক্রি।\n• \"অন্য কেউ নিয়ে নেওয়ার আগেই\" বলে তাড়াহুড়ো করে নগদে টাকা দেওয়ার প্রবল চাপ।\n\nসার্ভে নম্বরটি সরকারি জমির রেকর্ড পোর্টালে যাচাই করুন, আর কখনও নগদে টাকা দেবেন না।",
    "There is no female-buyer rebate in this state.": "এই রাজ্যে মহিলা ক্রেতার জন্য কোনও ছাড় নেই।",
    "Tip: select your state and district at the top so I can answer for your district instead of generally.": "পরামর্শ: উপরে আপনার রাজ্য ও জেলা বেছে নিন, যাতে আমি সাধারণভাবে না বলে আপনার জেলার হিসেবে উত্তর দিতে পারি।",
    "You will deal with these offices:\n\n• {0} — land record extract, mutation, heir certificates\n• Sub-Registrar Office — sale deed registration, encumbrance certificate\n• Collector Office — NA conversion and appeals\n• Municipal body or Gram Panchayat — property tax and layout approval\n\nThe Land Buying page shows the actual addresses, working hours and distance for {1}, so you do not travel to the wrong counter.": "আপনাকে এই দপ্তরগুলির সঙ্গে কাজ করতে হবে:\n\n• {0} — জমির রেকর্ডের নকল, মিউটেশন, উত্তরাধিকার শংসাপত্র\n• সাব-রেজিস্ট্রার অফিস — বিক্রয় দলিল রেজিস্ট্রেশন, এনকাম্ব্রেন্স সার্টিফিকেট\n• কালেক্টর অফিস — NA রূপান্তর ও আপিল\n• পুরসভা বা গ্রাম পঞ্চায়েত — সম্পত্তি কর ও লেআউট অনুমোদন\n\nআপনি যাতে ভুল কাউন্টারে গিয়ে না ঘোরেন, তাই জমি কেনা পাতায় {1}-এর জন্য আসল ঠিকানা, কাজের সময় ও দূরত্ব দেওয়া আছে।",
    "your state": "আপনার রাজ্য",
    "your taluka": "আপনার তালুকা",
  },
  pa: {
    "A clean purchase usually runs 30 to 45 days end to end:\n\n• Ownership and record checks — 2 to 5 days\n• Encumbrance certificate — 1 to 3 days\n• Agreement to sale — 1 day\n• Stamp duty payment — 1 day\n• Registration — 1 to 2 days\n• Mutation — 15 to 30 days\n\nMutation is the long tail. Registration makes you the owner; mutation just updates the revenue record afterwards.": "ਸਾਫ਼-ਸੁਥਰਾ ਸੌਦਾ ਸ਼ੁਰੂ ਤੋਂ ਅੰਤ ਤੱਕ ਆਮ ਤੌਰ 'ਤੇ 30 ਤੋਂ 45 ਦਿਨ ਲੈਂਦਾ ਹੈ:\n\n• ਮਾਲਕੀ ਤੇ ਰਿਕਾਰਡ ਦੀ ਪੜਤਾਲ — 2 ਤੋਂ 5 ਦਿਨ\n• ਇਨਕੰਬਰੈਂਸ ਸਰਟੀਫਿਕੇਟ — 1 ਤੋਂ 3 ਦਿਨ\n• ਵਿਕਰੀ ਦਾ ਇਕਰਾਰਨਾਮਾ — 1 ਦਿਨ\n• ਸਟੈਂਪ ਡਿਊਟੀ ਦੀ ਅਦਾਇਗੀ — 1 ਦਿਨ\n• ਰਜਿਸਟਰੀ — 1 ਤੋਂ 2 ਦਿਨ\n• ਇੰਤਕਾਲ — 15 ਤੋਂ 30 ਦਿਨ\n\nਸਭ ਤੋਂ ਵੱਧ ਸਮਾਂ ਇੰਤਕਾਲ ਲੈਂਦਾ ਹੈ। ਰਜਿਸਟਰੀ ਨਾਲ ਤੁਸੀਂ ਮਾਲਕ ਬਣ ਜਾਂਦੇ ਹੋ; ਇੰਤਕਾਲ ਤਾਂ ਬਾਅਦ ਵਿੱਚ ਸਿਰਫ਼ ਮਾਲ ਰਿਕਾਰਡ ਨੂੰ ਅੱਪਡੇਟ ਕਰਦਾ ਹੈ।",
    "A female buyer gets roughly {0}% less duty here.": "ਇੱਥੇ ਔਰਤ ਖਰੀਦਦਾਰ ਨੂੰ ਕਰੀਬ {0}% ਘੱਟ ਡਿਊਟੀ ਲੱਗਦੀ ਹੈ।",
    "Agricultural land has extra rules:\n\n• Several states allow only an existing farmer to buy farmland — check whether {0} restricts this.\n• The tenure class on the {1} matters. Restricted tenure needs Collector permission to sell.\n• To build a house or shop you need an NA (non-agricultural) conversion order from the Collector — 30 to 90 days.\n• Ceiling limits cap how much agricultural land one family can hold.\n\nRun the Smart Procedure Generator on the Land Buying page — it adds the conversion step automatically when you say you plan to build.": "ਖੇਤੀ ਵਾਲੀ ਜ਼ਮੀਨ ਲਈ ਵਾਧੂ ਨਿਯਮ ਹਨ:\n\n• ਕਈ ਰਾਜਾਂ ਵਿੱਚ ਖੇਤੀ ਵਾਲੀ ਜ਼ਮੀਨ ਸਿਰਫ਼ ਪਹਿਲਾਂ ਤੋਂ ਕਿਸਾਨ ਹੋਣ ਵਾਲਾ ਹੀ ਖਰੀਦ ਸਕਦਾ ਹੈ — ਦੇਖੋ ਕਿ {0} ਵਿੱਚ ਇਹ ਪਾਬੰਦੀ ਹੈ ਜਾਂ ਨਹੀਂ।\n• {1} ਉੱਤੇ ਦਰਜ ਹੱਕ-ਸ਼੍ਰੇਣੀ ਮਾਇਨੇ ਰੱਖਦੀ ਹੈ। ਪਾਬੰਦੀਸ਼ੁਦਾ ਸ਼੍ਰੇਣੀ ਵਾਲੀ ਜ਼ਮੀਨ ਵੇਚਣ ਲਈ ਡਿਪਟੀ ਕਮਿਸ਼ਨਰ ਦੀ ਮਨਜ਼ੂਰੀ ਚਾਹੀਦੀ ਹੈ।\n• ਘਰ ਜਾਂ ਦੁਕਾਨ ਬਣਾਉਣੀ ਹੋਵੇ ਤਾਂ ਡਿਪਟੀ ਕਮਿਸ਼ਨਰ ਤੋਂ NA (ਗੈਰ-ਖੇਤੀ) ਤਬਦੀਲੀ ਹੁਕਮ ਲੈਣਾ ਪੈਂਦਾ ਹੈ — 30 ਤੋਂ 90 ਦਿਨ।\n• ਹੱਦਬੰਦੀ ਕਾਨੂੰਨ ਤੈਅ ਕਰਦੇ ਹਨ ਕਿ ਇੱਕ ਪਰਿਵਾਰ ਵੱਧ ਤੋਂ ਵੱਧ ਕਿੰਨੀ ਖੇਤੀ ਵਾਲੀ ਜ਼ਮੀਨ ਰੱਖ ਸਕਦਾ ਹੈ।\n\nਜ਼ਮੀਨ ਦੀ ਖਰੀਦ ਵਾਲੇ ਪੰਨੇ 'ਤੇ ਸਮਾਰਟ ਵਿਧੀ ਜਨਰੇਟਰ ਚਲਾਓ — ਜਿਵੇਂ ਹੀ ਤੁਸੀਂ ਉਸਾਰੀ ਦੀ ਯੋਜਨਾ ਦੱਸਦੇ ਹੋ, ਇਹ ਤਬਦੀਲੀ ਵਾਲਾ ਪੜਾਅ ਆਪੇ ਜੋੜ ਦਿੰਦਾ ਹੈ।",
    "Answering for {0}, {1}.": "{0}, {1} ਲਈ ਜਵਾਬ ਦਿੱਤਾ ਜਾ ਰਿਹਾ ਹੈ।",
    "Answering for {0}.": "{0} ਲਈ ਜਵਾਬ ਦਿੱਤਾ ਜਾ ਰਿਹਾ ਹੈ।",
    "Ask me something specific, like \"what documents do I need for agricultural land\" or \"how much is stamp duty here\".": "ਕੁਝ ਖ਼ਾਸ ਪੁੱਛੋ, ਜਿਵੇਂ \"ਖੇਤੀ ਵਾਲੀ ਜ਼ਮੀਨ ਲਈ ਕਿਹੜੇ ਦਸਤਾਵੇਜ਼ ਚਾਹੀਦੇ ਹਨ\" ਜਾਂ \"ਇੱਥੇ ਸਟੈਂਪ ਡਿਊਟੀ ਕਿੰਨੀ ਹੈ\"।",
    "For a straightforward purchase you need:\n1. Registered sale deed\n2. {0} — the land record extract\n3. Encumbrance certificate for 13 to 30 years\n4. Previous title deeds (chain of ownership)\n5. Property tax receipt, up to date\n6. Aadhaar and PAN of both buyer and seller\n7. Passport photos and address proof\n\nExtra documents depend on the case: inherited land needs a legal heir certificate, farmland used for construction needs an NA order, and a company buyer needs a board resolution.\n\nOpen the Documents page to tick these off as you collect them.": "ਸਿੱਧੀ-ਸਾਦੀ ਖਰੀਦ ਲਈ ਤੁਹਾਨੂੰ ਇਹ ਚਾਹੀਦਾ ਹੈ:\n1. ਰਜਿਸਟਰਡ ਵਿਕਰੀ ਨਾਮਾ\n2. {0} — ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਦੀ ਨਕਲ\n3. 13 ਤੋਂ 30 ਸਾਲ ਦਾ ਇਨਕੰਬਰੈਂਸ ਸਰਟੀਫਿਕੇਟ\n4. ਪਿਛਲੇ ਮਾਲਕੀ ਦਸਤਾਵੇਜ਼ (ਮਾਲਕੀ ਦੀ ਲੜੀ)\n5. ਅੱਜ ਤੱਕ ਦੀ ਭਰੀ ਹੋਈ ਜਾਇਦਾਦ ਟੈਕਸ ਦੀ ਰਸੀਦ\n6. ਖਰੀਦਦਾਰ ਤੇ ਵੇਚਣ ਵਾਲੇ ਦੋਵਾਂ ਦੇ Aadhaar ਤੇ PAN\n7. ਪਾਸਪੋਰਟ ਫੋਟੋ ਤੇ ਪਤੇ ਦਾ ਸਬੂਤ\n\nਵਾਧੂ ਦਸਤਾਵੇਜ਼ ਮਾਮਲੇ ਮੁਤਾਬਕ ਹੁੰਦੇ ਹਨ: ਵਿਰਾਸਤ ਵਿੱਚ ਮਿਲੀ ਜ਼ਮੀਨ ਲਈ ਕਾਨੂੰਨੀ ਵਾਰਸ ਸਰਟੀਫਿਕੇਟ, ਉਸਾਰੀ ਲਈ ਵਰਤੀ ਜਾਣ ਵਾਲੀ ਖੇਤੀ ਜ਼ਮੀਨ ਲਈ NA ਹੁਕਮ, ਅਤੇ ਖਰੀਦਦਾਰ ਕੰਪਨੀ ਹੋਵੇ ਤਾਂ ਬੋਰਡ ਮਤਾ।\n\nਜਿਵੇਂ-ਜਿਵੇਂ ਇਕੱਠੇ ਕਰਦੇ ਜਾਓ, ਨਿਸ਼ਾਨ ਲਾਉਣ ਲਈ ਦਸਤਾਵੇਜ਼ ਵਾਲਾ ਪੰਨਾ ਖੋਲ੍ਹੋ।",
    "Hello. I can help with land buying procedure, required documents, stamp duty, government offices, and fraud checks.": "ਸਤ ਸ੍ਰੀ ਅਕਾਲ। ਜ਼ਮੀਨ ਖਰੀਦਣ ਦੀ ਵਿਧੀ, ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼, ਸਟੈਂਪ ਡਿਊਟੀ, ਸਰਕਾਰੀ ਦਫ਼ਤਰਾਂ ਤੇ ਧੋਖਾਧੜੀ ਦੀ ਜਾਂਚ ਵਿੱਚ ਮੈਂ ਮਦਦ ਕਰ ਸਕਦਾ ਹਾਂ।",
    "I also know your case: {0}.": "ਤੁਹਾਡੇ ਮਾਮਲੇ ਬਾਰੇ ਵੀ ਮੈਨੂੰ ਪਤਾ ਹੈ: {0}।",
    "I can answer questions about:\n• The step-by-step buying procedure\n• Required documents and what each one means\n• Stamp duty and registration charges\n• Which government office handles what\n• Fraud warning signs and how to check them\n\nTry asking it in plain words — for example, \"who do I meet first\" or \"is my land record too old\".": "ਮੈਂ ਇਨ੍ਹਾਂ ਗੱਲਾਂ ਦੇ ਜਵਾਬ ਦੇ ਸਕਦਾ ਹਾਂ:\n• ਕਦਮ-ਦਰ-ਕਦਮ ਖਰੀਦ ਦੀ ਵਿਧੀ\n• ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ ਤੇ ਹਰੇਕ ਦਾ ਮਤਲਬ\n• ਸਟੈਂਪ ਡਿਊਟੀ ਤੇ ਰਜਿਸਟਰੀ ਦੇ ਖਰਚੇ\n• ਕਿਹੜਾ ਸਰਕਾਰੀ ਦਫ਼ਤਰ ਕੀ ਦੇਖਦਾ ਹੈ\n• ਧੋਖਾਧੜੀ ਦੇ ਚੇਤਾਵਨੀ ਸੰਕੇਤ ਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਪਰਖਣ ਦਾ ਤਰੀਕਾ\n\nਸਿੱਧੀ ਭਾਸ਼ਾ ਵਿੱਚ ਪੁੱਛੋ — ਜਿਵੇਂ, \"ਪਹਿਲਾਂ ਕਿਸ ਨੂੰ ਮਿਲਾਂ\" ਜਾਂ \"ਮੇਰਾ ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਕਿਤੇ ਬਹੁਤ ਪੁਰਾਣਾ ਤਾਂ ਨਹੀਂ\"।",
    "In {0} the land record is called the {1}, issued by the {2}.\n\nIt tells you four things: who currently holds the land, the area, the tenure type, and — in the \"other rights\" column — any bank loan or dispute noted against it.\n\nHow to get it: download it from your state's land records portal, or apply at the {2}. It costs roughly ₹15 to ₹100.\n\nOne rule worth following: never accept an extract older than three months. Entries change.": "{0} ਵਿੱਚ ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਨੂੰ {1} ਕਿਹਾ ਜਾਂਦਾ ਹੈ, ਜੋ {2} ਜਾਰੀ ਕਰਦਾ ਹੈ।\n\nਇਹ ਚਾਰ ਗੱਲਾਂ ਦੱਸਦਾ ਹੈ: ਇਸ ਵੇਲੇ ਜ਼ਮੀਨ ਕਿਸ ਦੇ ਕਬਜ਼ੇ ਵਿੱਚ ਹੈ, ਰਕਬਾ, ਹੱਕ-ਸ਼੍ਰੇਣੀ, ਅਤੇ — \"ਹੋਰ ਹੱਕ\" ਵਾਲੇ ਕਾਲਮ ਵਿੱਚ — ਇਸ ਉੱਤੇ ਦਰਜ ਕੋਈ ਬੈਂਕ ਕਰਜ਼ਾ ਜਾਂ ਝਗੜਾ।\n\nਕਿਵੇਂ ਲੈਣਾ ਹੈ: ਆਪਣੇ ਰਾਜ ਦੇ ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਪੋਰਟਲ ਤੋਂ ਡਾਊਨਲੋਡ ਕਰੋ, ਜਾਂ {2} ਵਿੱਚ ਅਰਜ਼ੀ ਦਿਓ। ਖਰਚਾ ਕਰੀਬ ₹15 ਤੋਂ ₹100 ਆਉਂਦਾ ਹੈ।\n\nਇੱਕ ਗੱਲ ਪੱਲੇ ਬੰਨ੍ਹ ਲਓ: ਤਿੰਨ ਮਹੀਨੇ ਤੋਂ ਪੁਰਾਣੀ ਨਕਲ ਕਦੇ ਨਾ ਮੰਨੋ। ਇੰਦਰਾਜ ਬਦਲਦੇ ਰਹਿੰਦੇ ਹਨ।",
    "PAN is mandatory for property transactions above ₹5 lakh, for both parties.\n\nAadhaar is used for identity verification and biometrics at the Sub-Registrar office. In practice you will not get through registration without it, though the strict legal position varies by state.\n\nCarry originals plus two photocopies of each, for both buyer and seller.": "₹5 ਲੱਖ ਤੋਂ ਵੱਧ ਦੇ ਜਾਇਦਾਦ ਸੌਦਿਆਂ ਵਿੱਚ ਦੋਵਾਂ ਧਿਰਾਂ ਲਈ PAN ਲਾਜ਼ਮੀ ਹੈ।\n\nਸਬ-ਰਜਿਸਟਰਾਰ ਦਫ਼ਤਰ ਵਿੱਚ ਪਛਾਣ ਦੀ ਪੜਤਾਲ ਤੇ ਬਾਇਓਮੈਟ੍ਰਿਕ ਲਈ Aadhaar ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ। ਕਾਨੂੰਨੀ ਤੌਰ 'ਤੇ ਸਖ਼ਤ ਸਥਿਤੀ ਹਰ ਰਾਜ ਵਿੱਚ ਵੱਖਰੀ ਹੈ, ਪਰ ਅਮਲ ਵਿੱਚ ਇਸ ਤੋਂ ਬਿਨਾਂ ਰਜਿਸਟਰੀ ਨਹੀਂ ਹੁੰਦੀ।\n\nਖਰੀਦਦਾਰ ਤੇ ਵੇਚਣ ਵਾਲਾ, ਦੋਵੇਂ ਹਰ ਇੱਕ ਦੀ ਅਸਲ ਕਾਪੀ ਦੇ ਨਾਲ ਦੋ-ਦੋ ਫੋਟੋਕਾਪੀਆਂ ਲੈ ਕੇ ਜਾਣ।",
    "Partly. Most states let you download the land record extract and pay stamp duty online, and many publish encumbrance details on the registration portal.\n\nWhat still needs you in person: the registration appointment itself. Both parties and two witnesses have to appear at the Sub-Registrar office for biometrics and photographs.\n\nSo: do the research online, then book one office visit for registration.": "ਕੁਝ ਹੱਦ ਤੱਕ। ਬਹੁਤੇ ਰਾਜਾਂ ਵਿੱਚ ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਦੀ ਨਕਲ ਡਾਊਨਲੋਡ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ ਤੇ ਸਟੈਂਪ ਡਿਊਟੀ ਆਨਲਾਈਨ ਭਰੀ ਜਾ ਸਕਦੀ ਹੈ, ਅਤੇ ਕਈ ਰਾਜ ਰਜਿਸਟਰੀ ਪੋਰਟਲ ਉੱਤੇ ਬੋਝ ਦੇ ਵੇਰਵੇ ਵੀ ਪਾਉਂਦੇ ਹਨ।\n\nਜੋ ਹਾਲੇ ਵੀ ਖ਼ੁਦ ਜਾ ਕੇ ਕਰਨਾ ਪੈਂਦਾ ਹੈ: ਰਜਿਸਟਰੀ ਵਾਲਾ ਦਿਨ। ਬਾਇਓਮੈਟ੍ਰਿਕ ਤੇ ਫੋਟੋਆਂ ਲਈ ਦੋਵੇਂ ਧਿਰਾਂ ਤੇ ਦੋ ਗਵਾਹ ਸਬ-ਰਜਿਸਟਰਾਰ ਦਫ਼ਤਰ ਹਾਜ਼ਰ ਹੋਣੇ ਜ਼ਰੂਰੀ ਹਨ।\n\nਸੋ: ਖੋਜ-ਪੜਤਾਲ ਆਨਲਾਈਨ ਕਰ ਲਓ, ਫਿਰ ਰਜਿਸਟਰੀ ਲਈ ਇੱਕੋ ਵਾਰ ਦਫ਼ਤਰ ਜਾਣ ਦਾ ਸਮਾਂ ਲੈ ਲਓ।",
    "Stamp duty in most states is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "ਬਹੁਤੇ ਰਾਜਾਂ ਵਿੱਚ ਸਟੈਂਪ ਡਿਊਟੀ ਜਾਇਦਾਦ ਦੀ ਕੀਮਤ ਦਾ ਕਰੀਬ {1}% ਹੁੰਦੀ ਹੈ, ਤੇ ਰਜਿਸਟਰੀ ਫ਼ੀਸ {2}%{3} ਹੁੰਦੀ ਹੈ।\n\nਤਿੰਨ ਗੱਲਾਂ ਵਿੱਚ ਲੋਕ ਗ਼ਲਤੀ ਕਰਦੇ ਹਨ:\n1. ਡਿਊਟੀ ਤੁਹਾਡੇ ਇਕਰਾਰਨਾਮੇ ਦੀ ਕੀਮਤ ਤੇ ਸਰਕਾਰੀ ਕਲੈਕਟਰ ਰੇਟ, ਦੋਵਾਂ ਵਿੱਚੋਂ ਵੱਧ 'ਤੇ ਲੱਗਦੀ ਹੈ — ਉਸ 'ਤੇ ਨਹੀਂ ਜੋ ਤੁਸੀਂ ਅਸਲ ਵਿੱਚ ਦਿੱਤਾ।\n2. {4}\n3. ਇਸ ਨੂੰ ਰਜਿਸਟਰੀ ਤੋਂ ਪਹਿਲਾਂ ਭਰੋ ਤੇ ਈ-ਸਟੈਂਪ ਸਰਟੀਫਿਕੇਟ ਦਫ਼ਤਰ ਨਾਲ ਲੈ ਕੇ ਜਾਓ।\n\nਆਪਣੀ ਜਾਇਦਾਦ ਦੀ ਕੀਮਤ ਲਈ ਪੱਕਾ ਅੰਕੜਾ ਲੈਣ ਵਾਸਤੇ ਫ਼ੀਸਾਂ ਵਾਲਾ ਪੰਨਾ ਵਰਤੋ।",
    "Stamp duty in {0} is around {1}% of the property value, and the registration fee is {2}%{3}.\n\nThree things people get wrong:\n1. Duty is charged on the higher of your agreement value and the government circle rate — not on what you actually paid.\n2. {4}\n3. Pay it before registration and carry the e-stamp certificate to the office.\n\nUse the Charges page to get a number for your property value.": "{0} ਵਿੱਚ ਸਟੈਂਪ ਡਿਊਟੀ ਜਾਇਦਾਦ ਦੀ ਕੀਮਤ ਦਾ ਕਰੀਬ {1}% ਹੁੰਦੀ ਹੈ, ਤੇ ਰਜਿਸਟਰੀ ਫ਼ੀਸ {2}%{3} ਹੁੰਦੀ ਹੈ।\n\nਤਿੰਨ ਗੱਲਾਂ ਵਿੱਚ ਲੋਕ ਗ਼ਲਤੀ ਕਰਦੇ ਹਨ:\n1. ਡਿਊਟੀ ਤੁਹਾਡੇ ਇਕਰਾਰਨਾਮੇ ਦੀ ਕੀਮਤ ਤੇ ਸਰਕਾਰੀ ਕਲੈਕਟਰ ਰੇਟ, ਦੋਵਾਂ ਵਿੱਚੋਂ ਵੱਧ 'ਤੇ ਲੱਗਦੀ ਹੈ — ਉਸ 'ਤੇ ਨਹੀਂ ਜੋ ਤੁਸੀਂ ਅਸਲ ਵਿੱਚ ਦਿੱਤਾ।\n2. {4}\n3. ਇਸ ਨੂੰ ਰਜਿਸਟਰੀ ਤੋਂ ਪਹਿਲਾਂ ਭਰੋ ਤੇ ਈ-ਸਟੈਂਪ ਸਰਟੀਫਿਕੇਟ ਦਫ਼ਤਰ ਨਾਲ ਲੈ ਕੇ ਜਾਓ।\n\nਆਪਣੀ ਜਾਇਦਾਦ ਦੀ ਕੀਮਤ ਲਈ ਪੱਕਾ ਅੰਕੜਾ ਲੈਣ ਵਾਸਤੇ ਫ਼ੀਸਾਂ ਵਾਲਾ ਪੰਨਾ ਵਰਤੋ।",
    "Start with the {0} from the {1} — the name on that record is the legal holder. Then:\n\n• Match that name against the seller's Aadhaar or PAN, letter for letter.\n• Ask for the previous title deeds and read the chain backwards for at least 30 years.\n• Pull the encumbrance certificate from the Sub-Registrar office to see every registered transaction.\n• If someone is selling on the owner's behalf, ask for a registered power of attorney and check it is still valid.\n\nIf the seller resists any of this, treat it as a warning sign, not an inconvenience.": "ਸ਼ੁਰੂਆਤ {1} ਤੋਂ {0} ਲੈ ਕੇ ਕਰੋ — ਉਸ ਰਿਕਾਰਡ ਉੱਤੇ ਜੋ ਨਾਂ ਹੈ, ਉਹੀ ਕਾਨੂੰਨੀ ਮਾਲਕ ਹੈ। ਫਿਰ:\n\n• ਉਸ ਨਾਂ ਨੂੰ ਵੇਚਣ ਵਾਲੇ ਦੇ Aadhaar ਜਾਂ PAN ਨਾਲ ਅੱਖਰ-ਦਰ-ਅੱਖਰ ਮਿਲਾਓ।\n• ਪਿਛਲੇ ਮਾਲਕੀ ਦਸਤਾਵੇਜ਼ ਮੰਗੋ ਤੇ ਘੱਟੋ-ਘੱਟ 30 ਸਾਲ ਪਿੱਛੇ ਤੱਕ ਲੜੀ ਪੜ੍ਹੋ।\n• ਹਰ ਰਜਿਸਟਰਡ ਸੌਦਾ ਦੇਖਣ ਲਈ ਸਬ-ਰਜਿਸਟਰਾਰ ਦਫ਼ਤਰ ਤੋਂ ਇਨਕੰਬਰੈਂਸ ਸਰਟੀਫਿਕੇਟ ਕਢਵਾਓ।\n• ਜੇ ਕੋਈ ਮਾਲਕ ਵੱਲੋਂ ਵੇਚ ਰਿਹਾ ਹੈ, ਤਾਂ ਰਜਿਸਟਰਡ ਮੁਖਤਿਆਰਨਾਮਾ ਮੰਗੋ ਤੇ ਦੇਖੋ ਕਿ ਉਹ ਹਾਲੇ ਵੀ ਚੱਲਦਾ ਹੈ ਜਾਂ ਨਹੀਂ।\n\nਜੇ ਵੇਚਣ ਵਾਲਾ ਇਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕਿਸੇ ਗੱਲ ਤੋਂ ਟਾਲ-ਮਟੋਲ ਕਰੇ, ਤਾਂ ਇਸ ਨੂੰ ਮਾਮੂਲੀ ਖੇਚਲ ਨਹੀਂ, ਚੇਤਾਵਨੀ ਸਮਝੋ।",
    "The patterns that catch most buyers:\n\n• The seller is not the recorded owner, or sells through an unregistered power of attorney.\n• The same land is sold to two buyers — visible in the encumbrance certificate.\n• A pending court case that never appears in the documents shown to you.\n• Farmland sold as plots without an NA conversion order.\n• Heavy pressure to pay in cash, quickly, \"before someone else takes it\".\n\nVerify the survey number through the official land records portal, and never pay in cash.": "ਜ਼ਿਆਦਾਤਰ ਖਰੀਦਦਾਰ ਇਨ੍ਹਾਂ ਹੀ ਚਾਲਾਂ ਵਿੱਚ ਫਸਦੇ ਹਨ:\n\n• ਵੇਚਣ ਵਾਲਾ ਰਿਕਾਰਡ ਵਾਲਾ ਮਾਲਕ ਨਹੀਂ ਹੁੰਦਾ, ਜਾਂ ਬਿਨਾਂ ਰਜਿਸਟਰਡ ਮੁਖਤਿਆਰਨਾਮੇ ਦੇ ਵੇਚਦਾ ਹੈ।\n• ਇੱਕੋ ਜ਼ਮੀਨ ਦੋ ਖਰੀਦਦਾਰਾਂ ਨੂੰ ਵੇਚ ਦੇਣਾ — ਇਹ ਇਨਕੰਬਰੈਂਸ ਸਰਟੀਫਿਕੇਟ ਵਿੱਚ ਦਿਸ ਜਾਂਦਾ ਹੈ।\n• ਅਦਾਲਤ ਵਿੱਚ ਚੱਲਦਾ ਕੇਸ, ਜੋ ਤੁਹਾਨੂੰ ਦਿਖਾਏ ਦਸਤਾਵੇਜ਼ਾਂ ਵਿੱਚ ਕਿਤੇ ਨਹੀਂ ਆਉਂਦਾ।\n• NA ਤਬਦੀਲੀ ਹੁਕਮ ਤੋਂ ਬਿਨਾਂ ਖੇਤੀ ਵਾਲੀ ਜ਼ਮੀਨ ਦੇ ਪਲਾਟ ਵੇਚਣੇ।\n• \"ਕਿਤੇ ਕੋਈ ਹੋਰ ਨਾ ਲੈ ਜਾਵੇ\" ਕਹਿ ਕੇ ਛੇਤੀ ਨਕਦ ਦੇਣ ਦਾ ਭਾਰੀ ਦਬਾਅ।\n\nਸਰਵੇ ਨੰਬਰ ਸਰਕਾਰੀ ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਪੋਰਟਲ ਤੋਂ ਪਰਖੋ, ਤੇ ਕਦੇ ਵੀ ਨਕਦ ਅਦਾਇਗੀ ਨਾ ਕਰੋ।",
    "There is no female-buyer rebate in this state.": "ਇਸ ਰਾਜ ਵਿੱਚ ਔਰਤ ਖਰੀਦਦਾਰ ਲਈ ਕੋਈ ਛੋਟ ਨਹੀਂ ਹੈ।",
    "Tip: select your state and district at the top so I can answer for your district instead of generally.": "ਸੁਝਾਅ: ਉੱਪਰੋਂ ਆਪਣਾ ਰਾਜ ਤੇ ਜ਼ਿਲ੍ਹਾ ਚੁਣੋ, ਤਾਂ ਜੋ ਮੈਂ ਆਮ ਜਵਾਬ ਦੀ ਥਾਂ ਤੁਹਾਡੇ ਜ਼ਿਲ੍ਹੇ ਮੁਤਾਬਕ ਜਵਾਬ ਦੇ ਸਕਾਂ।",
    "You will deal with these offices:\n\n• {0} — land record extract, mutation, heir certificates\n• Sub-Registrar Office — sale deed registration, encumbrance certificate\n• Collector Office — NA conversion and appeals\n• Municipal body or Gram Panchayat — property tax and layout approval\n\nThe Land Buying page shows the actual addresses, working hours and distance for {1}, so you do not travel to the wrong counter.": "ਤੁਹਾਡਾ ਵਾਹ ਇਨ੍ਹਾਂ ਦਫ਼ਤਰਾਂ ਨਾਲ ਪਵੇਗਾ:\n\n• {0} — ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਦੀ ਨਕਲ, ਇੰਤਕਾਲ, ਵਾਰਸ ਸਰਟੀਫਿਕੇਟ\n• ਸਬ-ਰਜਿਸਟਰਾਰ ਦਫ਼ਤਰ — ਵਿਕਰੀ ਨਾਮੇ ਦੀ ਰਜਿਸਟਰੀ, ਇਨਕੰਬਰੈਂਸ ਸਰਟੀਫਿਕੇਟ\n• ਡਿਪਟੀ ਕਮਿਸ਼ਨਰ ਦਫ਼ਤਰ — NA ਤਬਦੀਲੀ ਤੇ ਅਪੀਲਾਂ\n• ਨਗਰ ਨਿਗਮ ਜਾਂ ਗ੍ਰਾਮ ਪੰਚਾਇਤ — ਜਾਇਦਾਦ ਟੈਕਸ ਤੇ ਲੇਆਉਟ ਦੀ ਮਨਜ਼ੂਰੀ\n\nਤੁਸੀਂ ਗ਼ਲਤ ਕਾਊਂਟਰ 'ਤੇ ਨਾ ਭਟਕੋ, ਇਸ ਲਈ ਜ਼ਮੀਨ ਦੀ ਖਰੀਦ ਵਾਲਾ ਪੰਨਾ {1} ਲਈ ਅਸਲ ਪਤੇ, ਕੰਮ ਦੇ ਘੰਟੇ ਤੇ ਦੂਰੀ ਦੱਸਦਾ ਹੈ।",
    "your state": "ਤੁਹਾਡਾ ਰਾਜ",
    "your taluka": "ਤੁਹਾਡੀ ਤਹਿਸੀਲ",
  },
};
Object.keys(DICT_ADD6).forEach((k) => { DICT[k] = Object.assign({}, DICT[k], DICT_ADD6[k]); });


/* District and taluka names in each script — see i18n.places.js. Merged into
 * DICT last, so tr("Jalna") works wherever a place name is shown and an
 * unknown one still falls back to its English spelling. */
Object.keys(PLACE_NAMES).forEach((k) => { DICT[k] = Object.assign({}, DICT[k], PLACE_NAMES[k]); });









/* ------------------------------------------------------------------ *
 *  i18n
 *  Two lookups share one engine:
 *    t("nav.home")        - keyed strings (kept for the original call sites)
 *    tr("Required Documents") - the English source text IS the key
 *  Using English as the key means any string that has not been translated
 *  yet renders as English instead of a blank or a raw key, and adding a
 *  language later means adding one more block to DICT - no code changes.
 * ------------------------------------------------------------------ */
export const makeTr = (lang) => {
  const d = DICT[lang] || null;
  return (text) => (!text || !d ? text : d[text] || text);
};

// t() first checks the keyed table, then falls back to the English value run
// through the dictionary — so anything added to DICT improves both lookups.
export const makeT = (lang) => {
  const table = STRINGS[lang] || null;
  const tr = makeTr(lang);
  return (key) => {
    if (table && table[key]) return table[key];
    const en = STRINGS.en[key];
    return en ? tr(en) : key;
  };
};

export const LangCtx = React.createContext("en");
export function useTr() {
  const lang = React.useContext(LangCtx);
  return useMemo(() => makeTr(lang), [lang]);
}

/* A sentence that has values dropped into it.
 *
 * The WHOLE sentence is one dictionary entry, with {0}, {1} … marking where
 * the values go — so a translator can place them wherever that language's
 * word order needs. Splitting such a sentence into fragments ("in", "of",
 * "and is issued by the") would force every language into English word order,
 * which reads broken in Tamil, Kannada, Bengali and Punjabi, where these are
 * postpositions. Values are returned as React nodes, so a value may itself be
 * an element (<b>…</b>).
 *
 *   const fill = useFill();
 *   fill("Question {0} of {1}", i + 1, total)
 */
/* The same idea as useFill(), but returning a plain string instead of React
 * nodes — for toasts, activity-log lines and anything else that is text, not
 * markup. fillText() takes the translator explicitly, so App.jsx (which is the
 * provider and therefore cannot call the hook) can use it too. */
export const fillText = (tr, text, ...vals) =>
  tr(text).replace(/\{(\d)\}/g, (_, i) => String(vals[Number(i)] ?? ""));

export function useFillText() {
  const tr = useTr();
  return (text, ...vals) => fillText(tr, text, ...vals);
}

export function useFill() {
  const tr = useTr();
  return (text, ...vals) =>
    tr(text)
      .split(/(\{\d\})/)
      .map((part, i) => {
        const m = /^\{(\d)\}$/.exec(part);
        return React.createElement(React.Fragment, { key: i }, m ? vals[Number(m[1])] : part);
      });
}
/**
 * Share of the interface each language actually translates.
 *
 * This is COMPUTED from the dictionaries above, not written down by hand.
 * The denominator is everything the app can ask for — every phrase in
 * TR_PHRASES plus every key in STRINGS.en — and a language only scores a
 * string it genuinely has. Add an English string tomorrow and forget to
 * translate it, and this figure drops on its own; it cannot go stale.
 */
function coverageOf(lang) {
  if (lang === "en") return 100;
  const d = DICT[lang] || {};
  const s = STRINGS[lang] || {};
  const keys = Object.keys(STRINGS.en);
  const done =
    TR_PHRASES.filter((p) => d[p]).length +
    PLACE_PHRASES.filter((p) => d[p]).length +
    keys.filter((k) => s[k] || d[STRINGS.en[k]]).length;
  return Math.round((done / (TR_PHRASES.length + PLACE_PHRASES.length + keys.length)) * 100);
}
export const LANG_COVERAGE = Object.fromEntries(LANGS.map(({ code }) => [code, coverageOf(code)]));
export const coverage = (lang) => LANG_COVERAGE[lang] ?? 0;

export const inr = (n) =>
  "₹" + Math.round(n).toLocaleString("en-IN");

